FONTS_FOLDER = resource_path("fonts")

_REPORTLAB_FONT_CACHE: tuple[str, str] | None = None
_TAMIL_FONT_CANDIDATE_CACHE: dict[str, list[str]] = {"regular": [], "bold": []}


def _unicode_tamil_font_candidates(kind: str = "regular") -> list[str]:
    key = "bold" if str(kind).strip().lower() == "bold" else "regular"
    cached = _TAMIL_FONT_CANDIDATE_CACHE.get(key)
    if cached:
        return cached

    if key == "bold":
        bundled_names = [
            "NotoSansTamil-Bold.ttf",
            "NotoSerifTamil-Bold.ttf",
            "NirmalaB.ttf",
            "Nirmala.ttf",
            "Latha.ttf",
            "Vijaya.ttf",
        ]
        windows_names = [
            "NirmalaB.ttf",
            "Nirmala.ttf",
            "Latha.ttf",
            "Vijaya.ttf",
            "NotoSansTamil-Bold.ttf",
            "NotoSerifTamil-Bold.ttf",
        ]
    else:
        bundled_names = [
            "NotoSansTamil-Regular.ttf",
            "NotoSerifTamil-Regular.ttf",
            "Nirmala.ttf",
            "Latha.ttf",
            "Vijaya.ttf",
        ]
        windows_names = [
            "Nirmala.ttf",
            "Latha.ttf",
            "Vijaya.ttf",
            "NotoSansTamil-Regular.ttf",
            "NotoSerifTamil-Regular.ttf",
        ]

    candidates: list[str] = []
    for name in bundled_names:
        candidates.append(os.path.join(FONTS_FOLDER, name))
        candidates.append(os.path.join(APP_DIR, "fonts", name))
    for name in windows_names:
        candidates.append(os.path.join(r"C:\Windows\Fonts", name))

    # Preserve order while removing duplicates.
    seen: set[str] = set()
    unique_candidates: list[str] = []
    for path in candidates:
        normalized = os.path.normcase(path)
        if normalized in seen:
            continue
        seen.add(normalized)
        unique_candidates.append(path)
    _TAMIL_FONT_CANDIDATE_CACHE[key] = unique_candidates
    return unique_candidates


def has_tamil_chars(text: str | None) -> bool:
    return any(0x0B80 <= ord(ch) <= 0x0BFF for ch in str(text or ""))


def get_reportlab_tamil_fonts() -> tuple[str, str]:
    global _REPORTLAB_FONT_CACHE
    if _REPORTLAB_FONT_CACHE is not None:
        return _REPORTLAB_FONT_CACHE

    regular_font = "Helvetica"
    bold_font = "Helvetica-Bold"
    regular_candidates = _unicode_tamil_font_candidates("regular")
    bold_candidates = _unicode_tamil_font_candidates("bold")

    for font_path in regular_candidates:
        if not os.path.exists(font_path):
            continue
        try:
            pdfmetrics.registerFont(TTFont("TamilFont", font_path))
            regular_font = "TamilFont"
            break
        except Exception:
            continue

    for font_path in bold_candidates:
        if not os.path.exists(font_path):
            continue
        try:
            pdfmetrics.registerFont(TTFont("TamilFont-Bold", font_path))
            bold_font = "TamilFont-Bold"
            break
        except Exception:
            continue

    if bold_font == "Helvetica-Bold" and regular_font != "Helvetica":
        bold_font = regular_font

    _REPORTLAB_FONT_CACHE = (regular_font, bold_font)
    return _REPORTLAB_FONT_CACHE

