    create("""
    IF OBJECT_ID('app_settings', 'U') IS NOT NULL
    BEGIN
        IF COL_LENGTH('app_settings', 'branch_code') IS NULL
            ALTER TABLE app_settings ADD branch_code NVARCHAR(100) NULL;

        DECLARE @legacy_setting_key_constraint SYSNAME;
        DECLARE @drop_legacy_setting_key_sql NVARCHAR(MAX);
        SELECT TOP 1 @legacy_setting_key_constraint = kc.name
        FROM sys.key_constraints kc
        INNER JOIN sys.index_columns ic
            ON ic.object_id = kc.parent_object_id
           AND ic.index_id = kc.unique_index_id
        INNER JOIN sys.columns c
            ON c.object_id = ic.object_id
           AND c.column_id = ic.column_id
        WHERE kc.parent_object_id = OBJECT_ID('app_settings')
          AND kc.type = 'UQ'
        GROUP BY kc.name
        HAVING COUNT(*) = 1 AND MAX(c.name) = 'key';

        IF @legacy_setting_key_constraint IS NOT NULL
        BEGIN
            SET @drop_legacy_setting_key_sql =
                N'ALTER TABLE app_settings DROP CONSTRAINT ' + QUOTENAME(@legacy_setting_key_constraint) + N';';
            EXEC(@drop_legacy_setting_key_sql);
        END

        IF NOT EXISTS (
            SELECT 1
            FROM sys.indexes
            WHERE object_id = OBJECT_ID('app_settings')
              AND name = 'UQ_app_settings_key_branch_code'
        )
            EXEC(
                N'CREATE UNIQUE INDEX UQ_app_settings_key_branch_code
                    ON app_settings([key], branch_code)
                    WHERE branch_code IS NOT NULL;'
            );

        IF NOT EXISTS (
            SELECT 1
            FROM sys.indexes
            WHERE object_id = OBJECT_ID('app_settings')
              AND name = 'UQ_app_settings_key_global'
        )
            EXEC(
                N'CREATE UNIQUE INDEX UQ_app_settings_key_global
                    ON app_settings([key])
                    WHERE branch_code IS NULL;'
            );
    END
    """)

