    create(f"""
    {table_not_exists('app_user_devices')}
        CREATE TABLE app_user_devices (
            id INT IDENTITY(1,1) PRIMARY KEY,
            user_id INT NOT NULL,
            device_type NVARCHAR(20) NOT NULL,
            device_id NVARCHAR(255) NOT NULL,
            device_platform NVARCHAR(50) NULL,
            bound_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),
            last_seen_at DATETIME2 NULL,
            CONSTRAINT fk_app_user_devices_user FOREIGN KEY (user_id) REFERENCES app_users(id)
        )
    {end()}
    """)

    create("""
    IF OBJECT_ID('app_user_devices', 'U') IS NOT NULL
    BEGIN
        IF COL_LENGTH('app_user_devices', 'last_seen_at') IS NULL
            ALTER TABLE app_user_devices ADD last_seen_at DATETIME2 NULL;

        IF NOT EXISTS (
            SELECT 1
            FROM sys.indexes
            WHERE object_id = OBJECT_ID('app_user_devices')
              AND name = 'UQ_app_user_devices_user_type_device'
        )
            EXEC(
                N'CREATE UNIQUE INDEX UQ_app_user_devices_user_type_device
                    ON app_user_devices(user_id, device_type, device_id);'
            );

        INSERT INTO app_user_devices (user_id, device_type, device_id, device_platform, bound_at)
        SELECT id, 'mobile', device_id, device_platform, COALESCE(device_bound_at, SYSDATETIME())
        FROM app_users u
        WHERE NULLIF(LTRIM(RTRIM(COALESCE(device_id, ''))), '') IS NOT NULL
          AND NOT EXISTS (
              SELECT 1
              FROM app_user_devices d
              WHERE d.user_id = u.id
                AND d.device_type = 'mobile'
                AND d.device_id = u.device_id
          );

        INSERT INTO app_user_devices (user_id, device_type, device_id, device_platform, bound_at)
        SELECT id, 'desktop', desktop_device_id, desktop_device_platform, COALESCE(desktop_device_bound_at, SYSDATETIME())
        FROM app_users u
        WHERE NULLIF(LTRIM(RTRIM(COALESCE(desktop_device_id, ''))), '') IS NOT NULL
          AND NOT EXISTS (
              SELECT 1
              FROM app_user_devices d
              WHERE d.user_id = u.id
                AND d.device_type = 'desktop'
                AND d.device_id = u.desktop_device_id
          );
    END
    """)

