    # ---------- Category name normalization ----------
    # Keep user-defined names (e.g. Shirt, Pant) instead of numeric IDs.
    create("""
    UPDATE categories
    SET name = 'Shirt'
    WHERE UPPER(LTRIM(RTRIM(name))) = 'S001'
    """)

    create("""
    UPDATE categories
    SET name = 'Pant'
    WHERE UPPER(LTRIM(RTRIM(name))) = 'P001'
    """)

    create("""
    UPDATE order_items
    SET item_type = REPLACE(
        REPLACE(
            REPLACE(
                REPLACE(item_type, 'S001 -', 'Shirt -'),
                'P001 -', 'Pant -'
            ),
            'S001', 'Shirt'
        ),
        'P001', 'Pant'
    )
    WHERE item_type LIKE '%S001%' OR item_type LIKE '%P001%'
    """)

    create("""
    UPDATE measurements
    SET kind = REPLACE(
        REPLACE(
            REPLACE(
                REPLACE(kind, 'S001 -', 'Shirt -'),
                'P001 -', 'Pant -'
            ),
            'S001', 'Shirt'
        ),
        'P001', 'Pant'
    )
    WHERE kind LIKE '%S001%' OR kind LIKE '%P001%'
    """)

    create("""
    UPDATE order_images
    SET item_type = REPLACE(
        REPLACE(
            REPLACE(
                REPLACE(item_type, 'S001 -', 'Shirt -'),
                'P001 -', 'Pant -'
            ),
            'S001', 'Shirt'
        ),
        'P001', 'Pant'
    )
    WHERE item_type LIKE '%S001%' OR item_type LIKE '%P001%'
    """)

