def now_str() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M")


def create_completed_notification(conn, order_id: int, event_time: str | None = None) -> None:
    if not order_id:
        return
    existing = conn.execute(
        """
        SELECT TOP 1 id
        FROM order_notifications
        WHERE order_id = ? AND event_type = 'completed'
        """,
        (order_id,),
    ).fetchone()
    if existing:
        return
    stamp = event_time or now_str()
    conn.execute(
        """
        INSERT INTO order_notifications (order_id, event_type, message, event_time, created_at)
        VALUES (?, 'completed', ?, ?, ?)
        """,
        (order_id, "Order completed", stamp, stamp),
    )


def sync_completed_notification(conn, order_id: int, previous_status: str, new_status: str, completed_at: str | None = None) -> None:
    if not order_id:
        return
    if new_status == "Completed":
        if previous_status != "Completed":
            create_completed_notification(conn, order_id, completed_at)
        return
    conn.execute(
        """
        DELETE FROM order_notifications
        WHERE order_id = ? AND event_type = 'completed'
        """,
        (order_id,),
    )

def generate_expense_no(conn: sqlite3.Connection) -> str:
    row = conn.execute(
        """
        SELECT ISNULL(MAX(TRY_CAST(SUBSTRING(expense_no, 5, 20) AS INT)), 0) AS max_num
        FROM expenses
        WHERE expense_no LIKE 'EXP-%'
        """
    ).fetchone()
    next_num = (int(row["max_num"] or 0) if row else 0) + 1
    return f"EXP-{next_num:04d}"


def _is_duplicate_expense_no_error(exc: Exception) -> bool:
    text = str(exc).lower()
    return (
        "duplicate key" in text
        and "expenses" in text
        and ("expense_no" in text or "uq__expenses" in text)
    )


def create_expense_record(
    conn: sqlite3.Connection,
    expense_name: str,
    amount: float,
    created_at: str,
    *,
    category: str | None = None,
    max_attempts: int = 5,
) -> tuple[int, str]:
    last_error: Exception | None = None
    for _ in range(max_attempts):
        expense_no = generate_expense_no(conn)
        cur = conn.cursor()
        try:
            cur.execute(
                """
                INSERT INTO expenses (expense_no, expense_name, amount, category, created_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (expense_no, expense_name, amount, (category or None), created_at),
            )
            return int(cur.lastrowid), expense_no
        except pyodbc.IntegrityError as exc:
            conn.rollback()
            if not _is_duplicate_expense_no_error(exc):
                raise
            last_error = exc
    if last_error is not None:
        raise last_error
    raise RuntimeError("Unable to create expense record.")


def _build_repair_expense_name(vehicle_name: str | None, vehicle_number: str | None) -> str:
    name = (vehicle_name or "").strip()
    number = (vehicle_number or "").strip()
    if name and number:
        return f"Repair - {name} ({number})"
    if name:
        return f"Repair - {name}"
    if number:
        return f"Repair - {number}"
    return "Repair expense"


def upsert_repair_expense(
    conn: sqlite3.Connection,
    expense_id: int | None,
    amount: float,
    vehicle_name: str | None,
    vehicle_number: str | None,
    created_at: str,
) -> int:
    expense_name = _build_repair_expense_name(vehicle_name, vehicle_number)
    if expense_id:
        row = conn.execute("SELECT id FROM expenses WHERE id = ?", (expense_id,)).fetchone()
        if row:
            conn.execute(
                """
                UPDATE expenses
                SET expense_name = ?, amount = ?, created_at = ?
                WHERE id = ?
                """,
                (expense_name, amount, created_at, expense_id),
            )
            return int(expense_id)
    expense_id, _ = create_expense_record(conn, expense_name, amount, created_at)
    return expense_id


def _order_type_prefix(order_type: str | None) -> str:
    key = (order_type or "").strip().lower()
    if key == "tailoring":
        return "T"
    if key == "alteration":
        return "A"
    return "M"


