def wrap_text(text: str, max_chars: int = 44) -> list[str]:
    clean = " ".join((text or "").split())
    if not clean:
        return []
    words = clean.split(" ")
    lines: list[str] = []
    current = ""
    for word in words:
        candidate = word if not current else f"{current} {word}"
        if len(candidate) <= max_chars:
            current = candidate
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def generate_repair_pdf_72x210mm(repair_row) -> str:
    folder = os.path.join(APP_DIR, "static", "repair_pdfs")
    os.makedirs(folder, exist_ok=True)

    repair_id = int(repair_row["id"])
    out_path = os.path.join(folder, f"repair_{repair_id}.pdf")

    width = 72 * mm
    height = 210 * mm
    pdf = canvas.Canvas(out_path, pagesize=(width, height))
    regular_font, bold_font = get_reportlab_tamil_fonts()

    def format_print_date(value) -> str:
        iso = date_only(value)
        if not iso or iso == "-":
            return "-"
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", str(iso))
        if m:
            return f"{m.group(3)}-{m.group(2)}-{m.group(1)}"
        return str(iso)

    def safe_float(value) -> float:
        try:
            return float(value)
        except Exception:
            return 0.0

    def safe_text(value) -> str:
        return ("" if value is None else str(value)).strip()

    company_name = get_setting("company_name", "").strip()
    gst_no = get_setting("gst_no", "").strip()

    kit_names = [x.strip() for x in safe_text(repair_row.get("repair_kits")).split(",") if x.strip()]
    kit_costs: dict[str, float] = {}
    raw_costs = safe_text(repair_row.get("repair_kit_costs"))
    if raw_costs:
        try:
            parsed = json.loads(raw_costs)
            if isinstance(parsed, dict):
                for k, v in parsed.items():
                    key = safe_text(k)
                    if not key:
                        continue
                    kit_costs[key] = max(0.0, safe_float(v))
        except Exception:
            kit_costs = {}

    total_cost = safe_float(repair_row.get("total_cost"))
    if total_cost <= 0 and kit_costs:
        total_cost = sum(kit_costs.values())
    advance_amount = safe_float(repair_row.get("advance_amount"))
    balance_amount = max(0.0, total_cost - advance_amount)

    y = height - 8 * mm
    left_x = 4 * mm
    right_x = width - 4 * mm
    line_h = 5 * mm

    def line(text: str, bold: bool = False, size: int = 9):
        nonlocal y
        if y <= 8 * mm:
            return
        pdf.setFont(bold_font if bold else regular_font, size)
        pdf.drawString(left_x, y, text)
        y -= line_h

    def hr():
        nonlocal y
        if y <= 10 * mm:
            return
        pdf.setLineWidth(0.6)
        pdf.line(left_x, y, right_x, y)
        y -= (line_h - 1 * mm)

    # Header
    line(company_name.upper(), bold=True, size=11)
    if gst_no:
        line(f"GST NO: {gst_no}", bold=False, size=9)
    hr()

    # Vehicle + Repair meta
    vehicle_name = safe_text(repair_row.get("vehicle_name"))
    vehicle_number = safe_text(repair_row.get("vehicle_number"))
    repair_date = safe_text(repair_row.get("repair_date")) or safe_text(repair_row.get("created_at"))
    payment_mode = safe_text(repair_row.get("payment_mode")) or "-"

    line(f"Repair ID : {repair_id}", bold=True)
    if vehicle_name or vehicle_number:
        line(f"Vehicle   : {vehicle_name} {vehicle_number}".strip())
    line(f"Date      : {format_print_date(repair_date)}")
    line(f"Pay Mode  : {payment_mode}")
    hr()

    desc = safe_text(repair_row.get("description")) or "-"
    line("Description:", bold=True)
    for part in wrap_text(desc, 38)[:6]:
        line(part)
    hr()

    if kit_names:
        line("Expense Details:", bold=True)
        for name in kit_names[:10]:
            cost = kit_costs.get(name, None)
            if cost is None:
                line(f"- {name}")
            else:
                line(f"- {name} : {INR_SYMBOL} {cost:,.2f}")
        hr()

    line(f"Total     : {INR_SYMBOL} {total_cost:,.2f}", bold=True)
    line(f"Advance   : {INR_SYMBOL} {advance_amount:,.2f}")
    line(f"Balance   : {INR_SYMBOL} {balance_amount:,.2f}")
    hr()
    line("Thank you", bold=True)
    line("System Generated")

    pdf.showPage()
    pdf.save()
    return out_path


def generate_repair_pdf_80mm(repair_row) -> str:
    folder = os.path.join(APP_DIR, "static", "repair_pdfs")
    os.makedirs(folder, exist_ok=True)

    repair_id = int(repair_row["id"])
    out_path = os.path.join(folder, f"repair_{repair_id}_customer.pdf")

    regular_font, bold_font = get_reportlab_tamil_fonts()

    def format_print_date(value) -> str:
        iso = date_only(value)
        if not iso or iso == "-":
            return "-"
        m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", str(iso))
        if m:
            return f"{m.group(3)}-{m.group(2)}-{m.group(1)}"
        return str(iso)

    def safe_float(value) -> float:
        try:
            return float(value)
        except Exception:
            return 0.0

    def safe_text(value) -> str:
        return ("" if value is None else str(value)).strip()

    company_name = get_setting("company_name", "").strip()
    gst_no = get_setting("gst_no", "").strip()

    kit_names = [x.strip() for x in safe_text(repair_row.get("repair_kits")).split(",") if x.strip()]
    kit_costs: dict[str, float] = {}
    raw_costs = safe_text(repair_row.get("repair_kit_costs"))
    if raw_costs:
        try:
            parsed = json.loads(raw_costs)
            if isinstance(parsed, dict):
                for k, v in parsed.items():
                    key = safe_text(k)
                    if not key:
                        continue
                    kit_costs[key] = max(0.0, safe_float(v))
        except Exception:
            kit_costs = {}

    total_cost = safe_float(repair_row.get("total_cost"))
    if total_cost <= 0 and kit_costs:
        total_cost = sum(kit_costs.values())
    advance_amount = safe_float(repair_row.get("advance_amount"))
    balance_amount = max(0.0, total_cost - advance_amount)

    vehicle_name = safe_text(repair_row.get("vehicle_name"))
    vehicle_number = safe_text(repair_row.get("vehicle_number"))
    repair_date = safe_text(repair_row.get("repair_date")) or safe_text(repair_row.get("created_at"))
    payment_mode = safe_text(repair_row.get("payment_mode")) or "-"
    desc = safe_text(repair_row.get("description")) or "-"

    wrap_width = 42
    text_lines: list[tuple[str, bool]] = []

    def add(text: str, bold: bool = False):
        text_lines.append((text, bold))

    add(company_name.upper(), True)
    add("REPAIR CUSTOMER COPY", True)
    if gst_no:
        add(f"GST NO: {gst_no}")
    add("-" * 32)
    add(f"Repair ID : {repair_id}", True)
    if vehicle_name or vehicle_number:
        add(f"Vehicle   : {vehicle_name} {vehicle_number}".strip())
    add(f"Date      : {format_print_date(repair_date)}")
    add(f"Pay Mode  : {payment_mode}")
    add("-" * 32)
    add("Description:", True)
    for part in wrap_text(desc, wrap_width)[:10]:
        add(part)
    if kit_names:
        add("-" * 32)
        add("Expense Details:", True)
        for name in kit_names[:18]:
            cost = kit_costs.get(name, None)
            if cost is None:
                for part in wrap_text(f"- {name}", wrap_width)[:2]:
                    add(part)
            else:
                for part in wrap_text(f"- {name} : {INR_SYMBOL} {cost:,.2f}", wrap_width)[:2]:
                    add(part)
    add("-" * 32)
    add(f"Total   : {INR_SYMBOL} {total_cost:,.2f}", True)
    add(f"Advance : {INR_SYMBOL} {advance_amount:,.2f}")
    add(f"Balance : {INR_SYMBOL} {balance_amount:,.2f}")
    add("-" * 32)
    add("Thank you for your order,visit again. ", True)

    # Estimate height based on lines.
    line_h = 5 * mm
    height = max(150 * mm, (len(text_lines) + 10) * line_h)
    pdf = canvas.Canvas(out_path, pagesize=(THERMAL_WIDTH, height))

    y = height - 8 * mm
    left_x = 5 * mm
    right_x = THERMAL_WIDTH - 5 * mm

    def line(text: str, bold: bool = False, size: int = 9):
        nonlocal y
        pdf.setFont(bold_font if bold else regular_font, size)
        pdf.drawString(left_x, y, text)
        y -= line_h

    def hr():
        nonlocal y
        pdf.setLineWidth(0.6)
        pdf.line(left_x, y, right_x, y)
        y -= (line_h - 1 * mm)

    for text, is_bold in text_lines:
        if text.strip() == "-" * 32:
            hr()
            continue
        if y <= 10 * mm:
            break
        line(text, bold=is_bold, size=11 if is_bold and text in {company_name.upper(), "REPAIR CUSTOMER COPY"} else 9)

    pdf.showPage()
    pdf.save()
    return out_path


