def create_measurement(
    customer_id: int,
    kind: str,
    fields: dict[str, str],
    allow_empty: bool = False,
    order_id: int | None = None,
    conn: sqlite3.Connection | None = None,
) -> None:
    numeric_keys = [
        "neck",
        "chest",
        "waist",
        "hip",
        "shoulder",
        "sleeve",
        "length",
        "cuff",
        "inseam",
        "outseam",
        "thigh",
        "knee",
        "bottom",
    ]
    invalid_lines: list[str] = []
    numeric_values: dict[str, float | None] = {}
    for key in numeric_keys:
        raw = str(fields.get(key) or "").strip()
        if not raw:
            numeric_values[key] = None
            continue
        parsed = parse_measure_value(raw)
        if parsed is None:
            numeric_values[key] = None
            invalid_lines.append(f"{key}: {raw}")
            continue
        numeric_values[key] = parsed

    notes_text = str(fields.get("notes") or "").strip()
    if invalid_lines:
        invalid_text = "Invalid measurement values:\n" + "\n".join(invalid_lines)
        notes_text = f"{notes_text}\n{invalid_text}".strip() if notes_text else invalid_text

    values = {
        "measure_status": (fields.get("measure_status") or "In-Progress"),
        "neck": numeric_values["neck"],
        "chest": numeric_values["chest"],
        "waist": numeric_values["waist"],
        "hip": numeric_values["hip"],
        "shoulder": numeric_values["shoulder"],
        "sleeve": numeric_values["sleeve"],
        "length": numeric_values["length"],
        "cuff": numeric_values["cuff"],
        "inseam": numeric_values["inseam"],
        "outseam": numeric_values["outseam"],
        "thigh": numeric_values["thigh"],
        "knee": numeric_values["knee"],
        "bottom": numeric_values["bottom"],
        "assigned_tailor": fields.get("assigned_tailor") or None,
        "notes": notes_text or None,
    }
    if not allow_empty and not any(values.values()):
        return

    owns_conn = conn is None
    conn = conn or get_db()
    conn.execute(
        """
        INSERT INTO measurements (
            customer_id, order_id, measure_status, kind, neck, chest, waist, hip, shoulder, sleeve, length, cuff,
            inseam, outseam, thigh, knee, bottom, assigned_tailor, notes, created_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            customer_id,
            order_id,
            values["measure_status"],
            kind,
            values["neck"],
            values["chest"],
            values["waist"],
            values["hip"],
            values["shoulder"],
            values["sleeve"],
            values["length"],
            values["cuff"],
            values["inseam"],
            values["outseam"],
            values["thigh"],
            values["knee"],
            values["bottom"],
            values["assigned_tailor"],
            values["notes"],
            now_str(),
        ),
    )
    if owns_conn:
        conn.commit()
        conn.close()


def generate_tailor_code(conn: sqlite3.Connection) -> str:
    return next_staff_code_for_role(conn, "shirt")


def _staff_prefix(role: str | None) -> str:
    role_text = (role or "").strip().lower()
    if "pant" in role_text:
        return "P"
    return "S"


def staff_code_from_role(role: str | None, staff_id: int) -> str:
    prefix = _staff_prefix(role)
    return f"{prefix}{int(staff_id):03d}"


def next_staff_code_for_role(conn: sqlite3.Connection, role: str | None) -> str:
    prefix = _staff_prefix(role)
    rows = conn.execute(
        "SELECT tailor_code FROM tailors WHERE tailor_code LIKE ?",
        (f"{prefix}%",),
    ).fetchall()
    max_num = 0
    for row in rows:
        value = str(row["tailor_code"] or "").strip()
        if not value.startswith(prefix):
            continue
        digits = value[1:]
        if digits.isdigit():
            max_num = max(max_num, int(digits))
    return f"{prefix}{(max_num + 1):03d}"


def allocate_staff_code(conn: sqlite3.Connection, role: str | None, exclude_id: int | None = None) -> str:
    prefix = _staff_prefix(role)
    next_number = 1
    rows = conn.execute(
        "SELECT id, tailor_code FROM tailors WHERE tailor_code LIKE ?",
        (f"{prefix}%",),
    ).fetchall()
    used_numbers: set[int] = set()
    for row in rows:
        if exclude_id is not None and int(row["id"]) == int(exclude_id):
            continue
        value = str(row["tailor_code"] or "").strip().upper()
        if not value.startswith(prefix):
            continue
        digits = value[1:]
        if digits.isdigit():
            used_numbers.add(int(digits))
    while next_number in used_numbers:
        next_number += 1
    return f"{prefix}{next_number:03d}"


def clean_staff_name(name: str | None) -> str:
    text = (name or "").strip()
    if not text:
        return ""
    lowered = text.lower()
    prefixes = [
        "pant tailor ",
        "shirt tailor ",
        "tailor ",
    ]
    for p in prefixes:
        if lowered.startswith(p):
            return text[len(p):].strip() or text
    return text


def get_business_mode() -> str:
    """Returns 'rental' or 'sale' (default). Branch-scoped, same as any other app_settings key."""
    mode = (get_setting("business_mode", "sale") or "sale").strip().lower()
    return "rental" if mode == "rental" else "sale"


def is_rental_mode() -> bool:
    return get_business_mode() == "rental"


def get_setting(key: str, default: str = "") -> str:
    conn = get_db()
    branch_code = get_current_branch_code()
    if branch_code:
        row = conn.execute(
            """
            SELECT TOP 1 value
            FROM app_settings
            WHERE [key] = ?
              AND COALESCE(branch_code, ?) = ?
            ORDER BY CASE WHEN branch_code = ? THEN 0 ELSE 1 END, id DESC
            """,
            (key, branch_code, branch_code, branch_code),
        ).fetchone()
    else:
        row = conn.execute(
            "SELECT TOP 1 value FROM app_settings WHERE [key] = ? AND branch_code IS NULL ORDER BY id DESC",
            (key,),
        ).fetchone()
    conn.close()
    return row["value"] if row else default


def set_setting(key: str, value: str) -> None:
    conn = get_db()
    branch_code = get_current_branch_code()
    if branch_code:
        exists = conn.execute(
            """
            SELECT TOP 1 id
            FROM app_settings
            WHERE [key] = ?
              AND COALESCE(branch_code, ?) = ?
            ORDER BY CASE WHEN branch_code = ? THEN 0 ELSE 1 END, id DESC
            """,
            (key, branch_code, branch_code, branch_code),
        ).fetchone()
    else:
        exists = conn.execute(
            "SELECT TOP 1 id FROM app_settings WHERE [key] = ? AND branch_code IS NULL ORDER BY id DESC",
            (key,),
        ).fetchone()
    if exists:
        conn.execute(
            "UPDATE app_settings SET value = ? WHERE id = ?",
            (value, exists["id"]),
        )
    else:
        conn.execute(
            "INSERT INTO app_settings ([key], value, branch_code) VALUES (?, ?, ?)",
            (key, value, branch_code),
        )
    conn.commit()
    conn.close()


def get_bool_setting(key: str, default: bool = False) -> bool:
    raw_default = "1" if default else "0"
    raw = str(get_setting(key, raw_default) or raw_default).strip().lower()
    return raw in {"1", "true", "yes", "y", "on"}


