def is_gst_enabled() -> bool:
    conn = get_db()
    rows = conn.execute(
        """
        SELECT [key], value
        FROM app_settings
        WHERE [key] IN (?, ?, ?, ?)
        """,
        (
            "gst_enabled",
            "gst_enable_tailoring",
            "gst_enable_alteration",
            "gst_enable_material",
        ),
    ).fetchall()
    conn.close()

    values = {str(row["key"]): str(row["value"]) for row in rows}
    explicit = values.get("gst_enabled")
    if explicit is not None:
        return explicit.strip() == "1"

    legacy_tailoring = values.get("gst_enable_tailoring")
    legacy_alteration = values.get("gst_enable_alteration")
    legacy_material = values.get("gst_enable_material")

    # Backward compatible defaults (old behavior):
    # - tailoring default ON
    # - alteration default OFF
    # - material default OFF
    if legacy_tailoring is None and legacy_alteration is None and legacy_material is None:
        return True

    tailoring_value = (legacy_tailoring if legacy_tailoring is not None else "1").strip()
    alteration_value = (legacy_alteration if legacy_alteration is not None else "0").strip()
    material_value = (legacy_material if legacy_material is not None else "0").strip()
    return tailoring_value == "1" or alteration_value == "1" or material_value == "1"


