def normalize_role_key(role: str | None) -> str:
    value = re.sub(r"[^a-z0-9]+", "_", str(role or "").strip().lower()).strip("_")
    return value or ROLE_USER


def normalize_permission_key(permission_key: str | None) -> str:
    clean_key = normalize_role_key(permission_key)
    return PERMISSION_KEY_ALIASES.get(clean_key, clean_key)


def normalize_user_role(role: str | None) -> str:
    return normalize_role_key(role)


def role_label(role: str | None) -> str:
    clean_key = normalize_user_role(role)
    if clean_key in ROLE_LABELS:
        return ROLE_LABELS[clean_key]
    text = clean_key.replace("_", " ").strip()
    return text.title() if text else "User"


def verify_user_password(stored_hash: str | None, password: str) -> bool:
    raw_hash = (stored_hash or "").strip()
    if not raw_hash:
        return False
    if "$" not in raw_hash and raw_hash.count(":") < 2:
        return raw_hash == password
    try:
        return check_password_hash(raw_hash, password)
    except ValueError:
        return raw_hash == password


# ---------------- Device Binding ----------------
# Each credential can be bound to a configurable number of mobile devices
# and desktop EXE machines per branch. Device records are stored in
# app_user_devices; the older single device columns are kept as compatibility
# fields for existing installs and admin tooling.

def is_device_binding_enforced() -> bool:
    return (os.getenv("ENFORCE_DEVICE_BINDING", "true") or "").strip().lower() in {
        "1", "true", "yes", "on",
    }


def normalize_device_type(device_type: str | None) -> str:
    clean = (device_type or "").strip().lower()
    if clean in {"desktop", "windows", "windows_desktop", "exe", "pc"}:
        return "desktop"
    return "mobile"


def device_limit_setting_key(device_type: str | None) -> str:
    return "max_desktop_devices" if normalize_device_type(device_type) == "desktop" else "max_mobile_devices"


def parse_device_limit(value: object, default: int = 1) -> int:
    try:
        parsed = int(str(value if value is not None else "").strip())
    except (TypeError, ValueError):
        parsed = default
    return max(1, min(parsed, 100))


def get_device_limit_on_connection(conn, device_type: str | None, branch_code: str | None = None) -> int:
    key = device_limit_setting_key(device_type)
    clean_branch_code = normalize_branch_code(branch_code or get_current_branch_code())
    if clean_branch_code:
        row = conn.execute(
            """
            SELECT TOP 1 value
            FROM app_settings
            WHERE [key] = ?
              AND COALESCE(branch_code, ?) = ?
            ORDER BY CASE WHEN branch_code = ? THEN 0 ELSE 1 END, id DESC
            """,
            (key, clean_branch_code, clean_branch_code, clean_branch_code),
        ).fetchone()
    else:
        row = conn.execute(
            "SELECT TOP 1 value FROM app_settings WHERE [key] = ? AND branch_code IS NULL ORDER BY id DESC",
            (key,),
        ).fetchone()
    return parse_device_limit(row["value"] if row else None, 1)


def device_is_bound(conn, user_id: int, device_type: str | None, device_id: str | None) -> bool:
    clean_device_id = (device_id or "").strip()
    if not clean_device_id:
        return False
    row = conn.execute(
        """
        SELECT TOP 1 id
        FROM app_user_devices
        WHERE user_id = ?
          AND device_type = ?
          AND device_id = ?
        """,
        (user_id, normalize_device_type(device_type), clean_device_id),
    ).fetchone()
    return bool(row)


def bind_or_check_device(
    conn,
    user_row,
    device_id: str | None,
    device_platform: str | None = None,
    *,
    device_type: str | None = None,
    branch_code: str | None = None,
    id_column: str = "device_id",
    bound_at_column: str = "device_bound_at",
    platform_column: str = "device_platform",
):
    """Returns (ok: bool, message: str).

    - If device binding isn't enforced, always ok.
    - If this device is already bound, refresh last_seen_at and allow.
    - If the credential has free slots for this device type, claim it.
    - If the configured branch limit is already reached, block the login.
    """
    if not is_device_binding_enforced():
        return True, "Device binding not enforced"

    clean_device_id = (device_id or "").strip()
    if not clean_device_id:
        return False, "Missing device identifier. Please update the app and try again."

    clean_device_type = normalize_device_type(device_type or device_platform or id_column)
    device_label = "desktop" if clean_device_type == "desktop" else "mobile"

    existing_device = conn.execute(
        """
        SELECT TOP 1 id
        FROM app_user_devices
        WHERE user_id = ?
          AND device_type = ?
          AND device_id = ?
        """,
        (user_row["id"], clean_device_type, clean_device_id),
    ).fetchone()
    if existing_device:
        conn.execute(
            """
            UPDATE app_user_devices
            SET device_platform = ?, last_seen_at = SYSDATETIME()
            WHERE id = ?
            """,
            (device_platform, existing_device["id"]),
        )
        conn.commit()
        return True, "Device verified"

    device_limit = get_device_limit_on_connection(conn, clean_device_type, branch_code)
    bound_count = conn.execute(
        """
        SELECT COUNT(*) AS total
        FROM app_user_devices
        WHERE user_id = ?
          AND device_type = ?
        """,
        (user_row["id"], clean_device_type),
    ).fetchone()
    if int(bound_count["total"] or 0) >= device_limit:
        return False, f"This account already reached the {device_label} device limit ({device_limit}). Contact your administrator to reset or increase the limit."

    conn.execute(
        """
        INSERT INTO app_user_devices (user_id, device_type, device_id, device_platform, bound_at, last_seen_at)
        VALUES (?, ?, ?, ?, SYSDATETIME(), SYSDATETIME())
        """,
        (user_row["id"], clean_device_type, clean_device_id, device_platform),
    )

    legacy_existing = (user_row[id_column] or "").strip() if id_column in user_row.keys() else ""
    if not legacy_existing:
        conn.execute(
            f"UPDATE app_users SET {id_column} = ?, {bound_at_column} = ?, {platform_column} = ? WHERE id = ?",
            (clean_device_id, datetime.now().isoformat(timespec="seconds"), device_platform, user_row["id"]),
        )

    conn.commit()
    return True, "Device bound"


def check_license_expiry(user_row):
    """Returns (ok: bool, message: str). None expiry = no expiry set (unlimited)."""
    expiry_raw = user_row["license_expiry_date"] if "license_expiry_date" in user_row.keys() else None
    if not expiry_raw:
        return True, "No expiry set"

    try:
        if isinstance(expiry_raw, str):
            expiry_dt = datetime.fromisoformat(expiry_raw)
        else:
            expiry_dt = expiry_raw  # already a datetime from pyodbc
    except Exception:
        return True, "Could not parse expiry, allowing"  # fail-open on bad data, not fail-closed on client

    if datetime.now() > expiry_dt:
        return False, f"Your license expired on {expiry_dt.strftime('%d %b %Y')}. Please contact your administrator to renew."

    return True, "License valid"


def ensure_default_role_records(conn) -> None:
    now = now_str()
    default_roles = [
        (ROLE_SUPER_ADMIN, ROLE_LABELS[ROLE_SUPER_ADMIN], 1, 1, 1, SYSTEM_ROLE_ORDER[ROLE_SUPER_ADMIN]),
        (ROLE_ADMIN, ROLE_LABELS[ROLE_ADMIN], 1, 0, 1, SYSTEM_ROLE_ORDER[ROLE_ADMIN]),
        (ROLE_STAFF, ROLE_LABELS[ROLE_STAFF], 1, 0, 1, SYSTEM_ROLE_ORDER[ROLE_STAFF]),
        (ROLE_USER, ROLE_LABELS[ROLE_USER], 1, 0, 1, SYSTEM_ROLE_ORDER[ROLE_USER]),
    ]
    for role_key, name, is_system, is_super_admin, is_active, sort_order in default_roles:
        existing = conn.execute(
            "SELECT id FROM app_roles WHERE role_key = ?",
            (role_key,),
        ).fetchone()
        if existing:
            conn.execute(
                """
                UPDATE app_roles
                SET name = ?, is_system = ?, is_super_admin = ?, is_active = ?, sort_order = ?, updated_at = SYSDATETIME()
                WHERE role_key = ?
                """,
                (name, is_system, is_super_admin, is_active, sort_order, role_key),
            )
        else:
            conn.execute(
                """
                INSERT INTO app_roles (role_key, name, is_system, is_super_admin, is_active, sort_order, created_at, updated_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (role_key, name, is_system, is_super_admin, is_active, sort_order, now, now),
            )

    for role_key, permission_keys in DEFAULT_ROLE_PERMISSIONS.items():
        existing_count = conn.execute(
            "SELECT COUNT(*) AS total FROM role_permissions WHERE role_key = ? AND is_allowed = 1",
            (role_key,),
        ).fetchone()
        if int(existing_count["total"] or 0):
            continue
        legacy_rows = conn.execute(
            """
            SELECT ump.menu_key
            FROM user_menu_permissions ump
            JOIN app_users u ON u.id = ump.user_id
            WHERE LOWER(COALESCE(u.role, '')) = ? AND ump.is_allowed = 1
            """,
            (role_key,),
        ).fetchall()
        legacy_permissions = {
            normalize_permission_key(row["menu_key"])
            for row in legacy_rows
            if row.get("menu_key") and normalize_permission_key(row["menu_key"]) in ALL_PERMISSION_KEYS
        }
        save_role_permissions(conn, role_key, legacy_permissions or permission_keys)


def list_app_roles(conn, *, include_inactive: bool = True) -> list[dict]:
    ensure_default_role_records(conn)
    where_clause = "" if include_inactive else "WHERE is_active = 1 OR is_super_admin = 1"
    rows = conn.execute(
        f"""
        SELECT *
        FROM app_roles
        {where_clause}
        ORDER BY sort_order ASC, name ASC, role_key ASC
        """
    ).fetchall()
    roles: list[dict] = []
    for row in rows:
        item = dict(row)
        item["role_key"] = normalize_user_role(item.get("role_key"))
        item["name"] = str(item.get("name") or role_label(item["role_key"])).strip() or role_label(item["role_key"])
        item["is_system"] = bool(item.get("is_system", 0))
        item["is_super_admin"] = bool(item.get("is_super_admin", 0))
        item["is_active"] = bool(item.get("is_active", 1))
        item["permissions"] = get_role_permissions(conn, item["role_key"])
        roles.append(item)
    return roles


def get_role_record(conn, role_key: str | None) -> dict | None:
    ensure_default_role_records(conn)
    clean_key = normalize_user_role(role_key)
    row = conn.execute("SELECT * FROM app_roles WHERE role_key = ?", (clean_key,)).fetchone()
    if not row:
        return None
    item = dict(row)
    item["role_key"] = clean_key
    item["name"] = str(item.get("name") or role_label(clean_key)).strip() or role_label(clean_key)
    item["is_system"] = bool(item.get("is_system", 0))
    item["is_super_admin"] = bool(item.get("is_super_admin", 0))
    item["is_active"] = bool(item.get("is_active", 1))
    item["permissions"] = get_role_permissions(conn, clean_key)
    return item


def get_role_permissions(conn, role_key: str | None) -> set[str]:
    clean_key = normalize_user_role(role_key)
    rows = conn.execute(
        """
        SELECT permission_key
        FROM role_permissions
        WHERE role_key = ? AND is_allowed = 1
        """,
        (clean_key,),
    ).fetchall()
    return {
        normalize_permission_key(row["permission_key"])
        for row in rows
        if row.get("permission_key") and normalize_permission_key(row["permission_key"]) in ALL_PERMISSION_KEYS
    }


def save_role_permissions(conn, role_key: str, permission_keys: list[str] | set[str]) -> None:
    clean_role_key = normalize_user_role(role_key)
    cleaned_keys = sorted({
        normalize_permission_key(key)
        for key in permission_keys
        if normalize_permission_key(key) in ALL_PERMISSION_KEYS
    })
    conn.execute("DELETE FROM role_permissions WHERE role_key = ?", (clean_role_key,))
    for permission_key in cleaned_keys:
        conn.execute(
            """
            INSERT INTO role_permissions (role_key, permission_key, is_allowed, created_at, updated_at)
            VALUES (?, ?, 1, SYSDATETIME(), SYSDATETIME())
            """,
            (clean_role_key, permission_key),
        )


def get_user_permissions(conn, user_id: int) -> set[str]:
    user_row = conn.execute("SELECT role FROM app_users WHERE id = ?", (user_id,)).fetchone()
    role_key = normalize_user_role(user_row["role"]) if user_row else ROLE_USER
    role_permissions = get_role_permissions(conn, role_key)
    if role_permissions:
        return role_permissions
    rows = conn.execute(
        """
        SELECT menu_key
        FROM user_menu_permissions
        WHERE user_id = ? AND is_allowed = 1
        """,
        (user_id,),
    ).fetchall()
    return {
        normalize_permission_key(row["menu_key"])
        for row in rows
        if row.get("menu_key") and normalize_permission_key(row["menu_key"]) in ALL_PERMISSION_KEYS
    }


def build_user_profile(
    row,
    permissions: set[str] | None = None,
    *,
    role_name: str | None = None,
    is_super_admin: bool | None = None,
) -> dict | None:
    if not row:
        return None
    role = normalize_user_role(row["role"])
    resolved_super_admin = (role == ROLE_SUPER_ADMIN) if is_super_admin is None else bool(is_super_admin)
    allowed_permissions = set(SUPER_ADMIN_FIXED_PERMISSION_KEYS if resolved_super_admin else (permissions or set()))
    return {
        "id": row["id"],
        "username": (row["username"] or "").strip(),
        "display_name": (row.get("display_name") or row["username"] or "").strip(),
        "branch_code": (row.get("branch_code") or "").strip() if row.get("branch_code") else None,
        "role": role,
        "role_label": (str(role_name or "").strip() or role_label(role)),
        "is_active": bool(row.get("is_active", 1)),
        "is_super_admin": resolved_super_admin,
        "permissions": allowed_permissions,
    }


def get_user_profile_by_id(user_id: int | None):
    if not user_id:
        return None
    conn = get_db()
    ensure_default_role_records(conn)
    row = conn.execute("SELECT * FROM app_users WHERE id = ?", (user_id,)).fetchone()
    if not row:
        conn.close()
        return None
    permissions = get_user_permissions(conn, row["id"])
    role_row = get_role_record(conn, row.get("role"))
    conn.close()
    return build_user_profile(
        row,
        permissions,
        role_name=(role_row or {}).get("name"),
        is_super_admin=(role_row or {}).get("is_super_admin"),
    )


def get_user_profile_by_username(username: str | None):
    clean_username = (username or "").strip()
    if not clean_username:
        return None
    conn = get_db()
    ensure_default_role_records(conn)
    row = conn.execute("SELECT * FROM app_users WHERE username = ?", (clean_username,)).fetchone()
    if not row:
        conn.close()
        return None
    permissions = get_user_permissions(conn, row["id"])
    role_row = get_role_record(conn, row.get("role"))
    conn.close()
    return build_user_profile(
        row,
        permissions,
        role_name=(role_row or {}).get("name"),
        is_super_admin=(role_row or {}).get("is_super_admin"),
    )


def get_current_user_profile():
    cached = getattr(g, "current_user_profile", None)
    if cached is not None:
        return cached

    user_profile = None
    if session.get("user_id"):
        user_profile = get_user_profile_by_id(session.get("user_id"))
    if not user_profile and session.get("username"):
        user_profile = get_user_profile_by_username(session.get("username"))
        if user_profile:
            session["user_id"] = user_profile["id"]
            session["role"] = user_profile["role"]
    g.current_user_profile = user_profile
    return user_profile


def endpoint_permission_key(endpoint: str | None) -> str | None:
    clean_endpoint = (endpoint or "").strip()
    if clean_endpoint == "inventory":
        active_tab = (request.args.get("tab") or "vehicles").strip().lower()
        if active_tab == "sold":
            return "sold_vehicle"
        return "inventory"
    return ENDPOINT_PERMISSION_MAP.get(clean_endpoint)


def user_has_permission(user_profile, permission_key: str | None) -> bool:
    if not permission_key:
        return True
    if not user_profile:
        return False
    if user_profile["is_super_admin"]:
        return True
    return permission_key in user_profile["permissions"]


def require_app_permission(permission_key: str) -> None:
    if not user_has_permission(get_current_user_profile(), permission_key):
        abort(403)


def get_default_landing_endpoint(user_profile) -> str:
    if not user_profile:
        return "login"
    for item in MENU_PERMISSION_DEFINITIONS:
        if user_has_permission(user_profile, item["key"]):
            return item["endpoint"]
    return "logout"


def build_sidebar_menu_items(user_profile) -> list[dict]:
    def with_sidebar_state(item: dict) -> dict:
        sidebar_item = dict(item)
        endpoint_args = dict(sidebar_item.get("endpoint_args") or {})
        sidebar_item["href"] = url_for(sidebar_item["endpoint"], **endpoint_args)
        active_endpoints = set(sidebar_item.get("active_endpoints") or [sidebar_item["endpoint"]])
        is_active = (request.endpoint or "") in active_endpoints
        active_args = sidebar_item.get("active_args") or {}
        for arg_key, allowed_values in active_args.items():
            current_value = (request.args.get(arg_key) or "").strip().lower()
            normalized_allowed = {str(value or "").strip().lower() for value in allowed_values}
            if current_value not in normalized_allowed:
                is_active = False
                break
        sidebar_item["is_active"] = is_active
        return sidebar_item

    items = []
    for item in MENU_PERMISSION_DEFINITIONS:
        if user_has_permission(user_profile, item["key"]):
            items.append(with_sidebar_state(item))
    vehicle_add_item = next((item for item in ACTION_PERMISSION_DEFINITIONS if item["key"] == "vehicle_add"), None)
    if vehicle_add_item and user_has_permission(user_profile, "vehicle_add"):
        items.insert(2 if len(items) >= 2 else len(items), with_sidebar_state(vehicle_add_item))
    if user_profile and user_profile["is_super_admin"]:
        items.append(with_sidebar_state({
            "key": "access_control",
            "label": "Add Users",
            "icon": "bi bi-person-plus",
            "endpoint": "settings",
            "endpoint_args": {"tab": "access-control"},
            "active_endpoints": ["settings"],
            "active_args": {"tab": ["access-control"]},
        }))
        items.append(with_sidebar_state({
            "key": "settings",
            "label": "Settings",
            "icon": "bi bi-gear",
            "endpoint": "settings",
            "active_endpoints": ["settings"],
            "active_args": {"tab": ["", "data-settings", "billing-message", "gst-settings", "printer-settings", "staff-roles", "company-settings"]},
        }))
    return items


def save_user_permissions(conn, user_id: int, menu_keys: list[str] | set[str]) -> None:
    cleaned_keys = sorted({key for key in menu_keys if key in MENU_PERMISSION_KEYS})
    conn.execute("DELETE FROM user_menu_permissions WHERE user_id = ?", (user_id,))
    for menu_key in cleaned_keys:
        conn.execute(
            """
            INSERT INTO user_menu_permissions (user_id, menu_key, is_allowed, created_at, updated_at)
            VALUES (?, ?, 1, SYSDATETIME(), SYSDATETIME())
            """,
            (user_id, menu_key),
        )


@app.context_processor
def inject_app_setting():
    def app_setting_value(key: str, default: str = "") -> str:
        if (key or "").strip().lower() == "gst_enabled":
            return "1" if is_gst_enabled() else "0"
        return get_setting(key, default)

    current_user = get_current_user_profile()
    current_branch = get_current_branch()
    return {
        "app_setting": app_setting_value,
        "current_user": current_user,
        "current_branch": current_branch,
        "available_branches": list_branches(),
        "sidebar_menu_items": build_sidebar_menu_items(current_user),
        "menu_permission_definitions": MENU_PERMISSION_DEFINITIONS,
        "action_permission_definitions": ACTION_PERMISSION_DEFINITIONS,
        "role_label": role_label,
    }


def parse_order_tax_payload(form, total_value: float | None) -> dict[str, float]:
    def to_float(name: str, default: float = 0.0) -> float:
        raw = (form.get(name) or "").strip()
        try:
            value = float(raw)
        except (TypeError, ValueError):
            return default
        return value if math.isfinite(value) else default

    taxable_amount = max(0.0, to_float("taxable_amount", 0.0))
    gst_percent = max(0.0, to_float("gst_percent", 0.0))
    gst_amount = max(0.0, to_float("gst_amount", 0.0))
    cgst_percent = max(0.0, to_float("cgst_percent", 0.0))
    cgst_amount = max(0.0, to_float("cgst_amount", 0.0))
    sgst_percent = max(0.0, to_float("sgst_percent", 0.0))
    sgst_amount = max(0.0, to_float("sgst_amount", 0.0))

    if taxable_amount <= 0 and total_value:
        taxable_amount = max(0.0, float(total_value) - gst_amount)

    if gst_amount <= 0 and taxable_amount > 0 and gst_percent > 0:
        gst_amount = taxable_amount * gst_percent / 100.0

    if gst_percent <= 0 and taxable_amount > 0 and gst_amount > 0:
        gst_percent = (gst_amount * 100.0) / taxable_amount

    if cgst_amount <= 0 and gst_amount > 0:
        cgst_amount = gst_amount / 2.0
    if sgst_amount <= 0 and gst_amount > 0:
        sgst_amount = gst_amount / 2.0
    if cgst_percent <= 0 and gst_percent > 0:
        cgst_percent = gst_percent / 2.0
    if sgst_percent <= 0 and gst_percent > 0:
        sgst_percent = gst_percent / 2.0

    return {
        "taxable_amount": round(taxable_amount, 2),
        "gst_percent": round(gst_percent, 2),
        "gst_amount": round(gst_amount, 2),
        "cgst_percent": round(cgst_percent, 2),
        "cgst_amount": round(cgst_amount, 2),
        "sgst_percent": round(sgst_percent, 2),
        "sgst_amount": round(sgst_amount, 2),
    }


def parse_order_discount_amount(form, taxable_amount: float) -> float:
    raw_discount = (form.get("discount") or "").strip()
    try:
        discount_value = float(raw_discount) if raw_discount else 0.0
    except (TypeError, ValueError):
        discount_value = 0.0
    if not math.isfinite(discount_value):
        discount_value = 0.0
    discount_value = max(0.0, discount_value)

    discount_mode = (form.get("discount_type") or "percent").strip().lower()
    if discount_mode == "amount":
        return round(discount_value, 2)

    if discount_value <= 0:
        return 0.0
    if discount_value >= 100:
        return 0.0
    subtotal = taxable_amount / (1.0 - (discount_value / 100.0))
    discount_amount = max(0.0, subtotal - taxable_amount)
    return round(discount_amount, 2)


def is_gst_enabled_for_order_type(order_type: str) -> bool:
    return is_gst_enabled()


def apply_gst_toggle_to_tax_payload(
    tax_payload: dict[str, float],
    total_value: float | None,
    gst_enabled: bool,
) -> dict[str, float]:
    if gst_enabled:
        return tax_payload
    safe_total = max(0.0, float(total_value or 0.0))
    return {
        "taxable_amount": round(safe_total, 2),
        "gst_percent": 0.0,
        "gst_amount": 0.0,
        "cgst_percent": 0.0,
        "cgst_amount": 0.0,
        "sgst_percent": 0.0,
        "sgst_amount": 0.0,
    }


def get_installed_printer_names() -> list[str]:
    if os.name != "nt":
        return []
    try:
        import win32print  # type: ignore
    except Exception:
        return []
    try:
        flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
        rows = win32print.EnumPrinters(flags)
        names = [str(row[2]).strip() for row in rows if len(row) > 2 and str(row[2]).strip()]
        return sorted(set(names), key=str.lower)
    except Exception:
        return []


def archive_print_softcopy(pdf_path: str, order_id: int, mode: str) -> str:
    if getattr(sys, "frozen", False):
        base_dir = os.path.dirname(sys.executable)
    else:
        base_dir = APP_DIR
    target_dir = os.path.join(base_dir, "print_softcopies")
    os.makedirs(target_dir, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    target_name = f"order_{order_id}_{mode}_{stamp}.pdf"
    target_path = os.path.join(target_dir, target_name)
    shutil.copy2(pdf_path, target_path)
    return target_path


def print_pdf_to_configured_printer(pdf_path: str, printer_name: str) -> tuple[bool, str]:
    if os.name != "nt":
        return False, "Auto print is supported on Windows only."
    clean_printer = printer_name.strip()
    errors: list[str] = []

    try:
        import win32api  # type: ignore
        try:
            if clean_printer:
                win32api.ShellExecute(0, "printto", pdf_path, f'"{clean_printer}"', ".", 0)
                return True, ""
        except Exception as ex:
            errors.append(f"win32 printto: {ex}")
        try:
            win32api.ShellExecute(0, "print", pdf_path, None, ".", 0)
            return True, ""
        except Exception as ex:
            errors.append(f"win32 print: {ex}")
    except Exception:
        errors.append("win32api not available")

    # Fallback path: use PowerShell print verbs.
    try:
        safe_pdf = pdf_path.replace("'", "''")
        if clean_printer:
            safe_printer = clean_printer.replace("'", "''")
            script = (
                f"Start-Process -FilePath '{safe_pdf}' "
                f"-Verb PrintTo -ArgumentList '\"{safe_printer}\"' -WindowStyle Hidden"
            )
        else:
            script = f"Start-Process -FilePath '{safe_pdf}' -Verb Print -WindowStyle Hidden"
        subprocess.run(
            ["powershell", "-NoProfile", "-Command", script],
            check=True,
            capture_output=True,
            text=True,
            timeout=20,
        )
        return True, ""
    except Exception as ex:
        errors.append(f"powershell print verb: {ex}")

    return False, "; ".join(errors)


def process_post_print_actions(pdf_path: str, order_id: int, mode: str) -> None:
    if not pdf_path or not os.path.exists(pdf_path):
        return
    try:
        archive_print_softcopy(pdf_path, order_id, mode)
    except Exception as ex:
        print(f"[PRINT] Softcopy save failed for order {order_id}: {ex}")
    if get_setting("auto_print_on_click", "0").strip() == "1":
        printer_name = get_setting("default_printer_name", "").strip()
        ok, err = print_pdf_to_configured_printer(pdf_path, printer_name)
        if not ok:
            print(f"[PRINT] Auto print failed for order {order_id}: {err}")


def force_print_to_selected_printer(pdf_path: str, order_id: int, mode: str) -> tuple[bool, str]:
    if not pdf_path or not os.path.exists(pdf_path):
        return False, "Print file not found."
    try:
        archive_print_softcopy(pdf_path, order_id, mode)
    except Exception as ex:
        print(f"[PRINT] Softcopy save failed for order {order_id}: {ex}")
    printer_name = get_setting("default_printer_name", "").strip()
    if not printer_name:
        return False, "Default printer is not configured in Settings."
    return print_pdf_to_configured_printer(pdf_path, printer_name)


def get_company_address_lines() -> list[str]:
    line1 = get_setting("address_line1", "").strip()
    line2 = get_setting("address_line2", "").strip()
    line3 = get_setting("address_line3", "").strip()
    lines = [line for line in (line1, line2, line3) if line]
    if lines:
        return lines

    # Backward compatibility for existing single-line address setting.
    fallback = get_setting("address_name", "").strip()
    if not fallback:
        return []
    parts = [part.strip() for part in re.split(r"[\r\n,]+", fallback) if part.strip()]
    return parts[:3]


def generate_inventory_code(conn: sqlite3.Connection, name: str) -> str:
    base = "".join(ch for ch in name.upper() if ch.isalnum())
    prefix = base[:3] if len(base) >= 3 else (base or "INV")
    cur = conn.cursor()
    cur.execute(
        "SELECT inventory_code FROM inventory WHERE inventory_code LIKE ? ORDER BY id DESC LIMIT 1",
        (f"{prefix}-%",),
    )
    row = cur.fetchone()
    if row and row["inventory_code"]:
        try:
            last_num = int(row["inventory_code"].split("-")[-1])
            return f"{prefix}-{last_num + 1:03d}"
        except ValueError:
            pass
    return f"{prefix}-001"


def generate_vendor_code(conn: sqlite3.Connection) -> str:
    cur = conn.cursor()
    cur.execute("SELECT vendor_code FROM vendors ORDER BY id DESC LIMIT 1")
    row = cur.fetchone()
    if row and row["vendor_code"] and row["vendor_code"].startswith("VND"):
        try:
            last_num = int(row["vendor_code"][3:])
            return f"VND{last_num + 1:04d}"
        except ValueError:
            pass
    cur.execute("SELECT COUNT(*) FROM vendors")
    count = cur.fetchone()[0] + 1
    return f"VND{count:04d}"

