def build_dashboard_search_results(
    conn,
    q: str,
    *,
    from_date: str = "",
    to_date: str = "",
) -> list[dict[str, str]]:
    q = (q or "").strip()
    if not q:
        return []

    date_filter_active = bool(from_date and to_date)
    q_like = f"%{q}%"
    q_compact = re.sub(r"[^a-z0-9]+", "", q.lower())
    q_digits_only = re.sub(r"\D+", "", q)
    q_numeric_value = int(q_digits_only) if q_digits_only else None
    search_results: list[dict[str, str]] = []

    try:
        customer_sql = """
            SELECT TOP 8
                c.id,
                c.name,
                c.phone,
                c.address,
                c.notes
            FROM customers c
            WHERE
                c.name LIKE ?
                OR c.phone LIKE ?
                OR ISNULL(c.address, '') LIKE ?
                OR ISNULL(c.notes, '') LIKE ?
                OR (? IS NOT NULL AND c.id = ?)
            ORDER BY c.created_at DESC, c.id DESC
        """
        customer_rows = conn.execute(
            customer_sql,
            (q_like, q_like, q_like, q_like, q_numeric_value, q_numeric_value),
        ).fetchall()
        search_results.extend(
            {
                "href": url_for("customer_detail", customer_id=row["id"], source="customers"),
                "title": f"{row['name']} (CUST-{customer_display_id(int(row['id']))})",
                "subtitle": f"{row.get('phone') or '-'} · {row.get('address') or '-'}",
                "meta": "Customer",
            }
            for row in customer_rows
        )
    except Exception:
        pass

    try:
        order_sql = """
            SELECT orders.*, customers.name, customers.phone
            FROM orders
            JOIN customers ON (
                customers.id = orders.customer_id
                OR customers.id = orders.customer_display_id
            )
            WHERE (
                customers.name LIKE ?
                OR customers.phone LIKE ?
                OR customers.address LIKE ?
                OR ISNULL(orders.invoice_id, '') LIKE ?
                OR ISNULL(orders.order_no, '') LIKE ?
                OR ISNULL(orders.status, '') LIKE ?
                OR ISNULL(orders.priority, '') LIKE ?
                OR ISNULL(orders.notes, '') LIKE ?
                OR ISNULL(orders.assigned_tailor, '') LIKE ?
                OR EXISTS (
                    SELECT 1
                    FROM order_items oi
                    WHERE oi.order_id = orders.id
                      AND (
                          ISNULL(oi.item_type, '') LIKE ?
                          OR ISNULL(oi.notes, '') LIKE ?
                      )
                )
                OR EXISTS (
                    SELECT 1
                    FROM measurements m
                    WHERE m.order_id = orders.id
                      AND ISNULL(m.assigned_tailor, '') LIKE ?
                )
                OR (? IS NOT NULL AND (
                    orders.id = ?
                    OR customers.id = ?
                    OR ISNULL(orders.customer_display_id, -1) = ?
                ))
            )
        """
        order_params = [
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_like,
            q_numeric_value,
            q_numeric_value,
            q_numeric_value,
            q_numeric_value,
        ]
        if date_filter_active:
            order_sql += " AND date(orders.created_at) BETWEEN ? AND ?"
            order_params.extend([from_date, to_date])
        order_sql += " ORDER BY orders.created_at DESC LIMIT 12"
        order_rows = conn.execute(order_sql, tuple(order_params)).fetchall()
        search_results.extend(
            {
                "href": url_for("order_detail", order_id=row["id"]),
                "title": f"{fmt_order_id(row['id'], row.get('order_type'))} {row['name']}",
                "subtitle": f"{row['phone']} · {row.get('order_type') or 'Order'}",
                "meta": "Order",
            }
            for row in order_rows
        )
    except Exception:
        pass

    try:
        vehicle_sql = """
            SELECT TOP 12
                v.id,
                v.vehicle_name,
                v.vehicle_number,
                v.registration_no,
                v.current_fc,
                v.notes,
                v.purchase_customer_name,
                v.purchase_customer_phone,
                v.purchase_customer_address,
                v.purchase_customer_id,
                v.purchase_mode,
                v.purchase_id_proof_ref,
                v.purchase_finance_company,
                v.purchase_finance_yard_ref,
                v.purchase_finance_settlement_date,
                v.purchase_agent_name,
                v.purchase_agent_broker_details,
                v.purchase_branch_from_branch,
                v.purchase_branch_transfer_id,
                v.purchase_branch_handled_by
            FROM vehicles v
            WHERE
                ISNULL(v.vehicle_name, '') LIKE ?
                OR ISNULL(v.vehicle_number, '') LIKE ?
                OR REPLACE(REPLACE(REPLACE(LOWER(ISNULL(v.vehicle_number, '')), '-', ''), ' ', ''), '.', '') LIKE ?
                OR ISNULL(v.registration_no, '') LIKE ?
                OR REPLACE(REPLACE(REPLACE(LOWER(ISNULL(v.registration_no, '')), '-', ''), ' ', ''), '.', '') LIKE ?
                OR ISNULL(v.current_fc, '') LIKE ?
                OR ISNULL(v.notes, '') LIKE ?
                OR ISNULL(v.purchase_customer_name, '') LIKE ?
                OR ISNULL(v.purchase_customer_phone, '') LIKE ?
                OR ISNULL(v.purchase_customer_address, '') LIKE ?
                OR ISNULL(v.purchase_customer_id, '') LIKE ?
                OR ISNULL(v.purchase_mode, '') LIKE ?
                OR ISNULL(v.purchase_id_proof_ref, '') LIKE ?
                OR ISNULL(v.purchase_finance_company, '') LIKE ?
                OR ISNULL(v.purchase_finance_yard_ref, '') LIKE ?
                OR ISNULL(v.purchase_finance_settlement_date, '') LIKE ?
                OR ISNULL(v.purchase_agent_name, '') LIKE ?
                OR ISNULL(v.purchase_agent_broker_details, '') LIKE ?
                OR ISNULL(v.purchase_branch_from_branch, '') LIKE ?
                OR ISNULL(v.purchase_branch_transfer_id, '') LIKE ?
                OR ISNULL(v.purchase_branch_handled_by, '') LIKE ?
                OR (? IS NOT NULL AND v.id = ?)
            ORDER BY ISNULL(v.updated_at, v.created_at) DESC, v.id DESC
        """
        vehicle_rows = conn.execute(
            vehicle_sql,
            (
                q_like,
                q_like,
                f"%{q_compact}%",
                q_like,
                f"%{q_compact}%",
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_like,
                q_numeric_value,
                q_numeric_value,
            ),
        ).fetchall()
        search_results.extend(
            {
                "href": url_for("inventory_vehicle_edit", vehicle_id=row["id"], mode="view"),
                "title": f"{row['vehicle_name']} ({row['vehicle_number']})",
                "subtitle": f"{derive_vehicle_brand(row.get('vehicle_name'))} · {row.get('registration_no') or row.get('purchase_customer_name') or '-'} · {row.get('purchase_customer_phone') or row.get('current_fc') or '-'}",
                "meta": "Vehicle",
            }
            for row in vehicle_rows
        )
    except Exception:
        pass

    deduped_results = []
    seen_search_keys: set[tuple[str, str]] = set()
    for item in search_results:
        key = (str(item.get("href") or ""), str(item.get("title") or ""))
        if key in seen_search_keys:
            continue
        seen_search_keys.add(key)
        deduped_results.append(item)
    return deduped_results[:20]


def get_insurance_expiry_notifications(conn, limit: int = 12):
    try:
        alert_days = max(int(get_setting("insurance_alert_days", "0") or 0), 0)
    except Exception:
        alert_days = 0
    try:
        loss_amount = max(float(get_setting("loss_amount", "0") or 0), 0.0)
    except Exception:
        loss_amount = 0.0
    if alert_days <= 0:
        return []
    today = date.today().isoformat()
    last_day = (date.today() + timedelta(days=alert_days)).isoformat()
    rows = conn.execute(
        f"""
        SELECT TOP {int(limit)}
            id,
            vehicle_name,
            vehicle_number,
            insurance_date,
            status
        FROM vehicles
        WHERE insurance_date IS NOT NULL
          AND CAST(insurance_date AS DATE) BETWEEN ? AND ?
          AND LOWER(COALESCE(status, 'available')) NOT IN ('sold', 'transferred')
        ORDER BY CAST(insurance_date AS DATE) ASC, id ASC
        """,
        (today, last_day),
    ).fetchall()
    notifications = []
    for row in rows:
        item = dict(row)
        item["loss_amount"] = loss_amount
        notifications.append(item)
    return notifications


@app.route("/gallery")
def gallery():
    conn = get_db()
    vehicle_rows = conn.execute(
        "SELECT * FROM vehicles WHERE LOWER(COALESCE(status, 'available')) <> 'transferred' ORDER BY ISNULL(updated_at, created_at) DESC, id DESC"
    ).fetchall()
    vehicles = [build_gallery_vehicle_payload(row) for row in vehicle_rows]
    status_counts = {"available": 0, "in_progress": 0, "in_repair": 0, "sold": 0}
    for vehicle in vehicles:
        status_value = normalize_vehicle_status(vehicle.get("status_value"))
        if status_value == "sold":
            status_counts["sold"] += 1
        elif status_value == "in_repair":
            status_counts["in_repair"] += 1
        elif status_value == "in_progress":
            status_counts["in_progress"] += 1
        else:
            status_counts["available"] += 1

    try:
        sales_count = int(
            conn.execute(
                """
                SELECT COUNT(*) AS total
                FROM vehicle_sale_orders vso
                LEFT JOIN orders o ON o.id = vso.order_id
                WHERE LOWER(COALESCE(o.status, 'in-progress')) <> 'cancelled'
                """
            ).fetchone()["total"]
            or 0
        )
    except Exception:
        sales_count = status_counts["sold"]

    def fetch_total(sql: str, key: str = "total") -> float:
        try:
            return float(conn.execute(sql).fetchone()[key] or 0)
        except Exception:
            return 0.0

    purchase_total = fetch_total(
        "SELECT COALESCE(SUM(total_amount), 0) AS total FROM vendor_purchase_orders"
    )
    salary_total = fetch_total(
        "SELECT COALESCE(SUM(salary_amount), 0) AS total FROM salaries"
    )
    repair_total = fetch_total(
        "SELECT COALESCE(SUM(total_cost), 0) AS total FROM vehicle_repairs"
    )
    staff_total = int(fetch_total("SELECT COUNT(*) AS total FROM tailors"))
    try:
        expense_total = float(
            conn.execute(
                """
                SELECT COALESCE(SUM(e.amount), 0) AS total
                FROM expenses e
                LEFT JOIN vehicle_repairs vr ON vr.expense_id = e.id
                LEFT JOIN salaries s ON s.expense_id = e.id
                WHERE vr.id IS NULL AND s.id IS NULL
                """
            ).fetchone()["total"]
            or 0
        )
    except Exception:
        expense_total = 0.0
    conn.close()

    catalog_summary_rows = [
        [
            {"label": "Total Vehicles", "value": len(vehicles), "kind": "count"},
            {"label": "Sales", "value": sales_count, "kind": "count"},
            {"label": "Available", "value": status_counts["available"], "kind": "count"},
            {"label": "In Progress", "value": status_counts["in_progress"], "kind": "count"},
            {"label": "Sold", "value": status_counts["sold"], "kind": "count"},
        ],
        [
            {"label": "Purchase", "value": purchase_total, "kind": "currency"},
            {"label": "Expense", "value": expense_total, "kind": "currency"},
            {"label": "Salary", "value": salary_total, "kind": "currency"},
            {"label": "Repair", "value": repair_total, "kind": "currency"},
            {"label": "Staff", "value": staff_total, "kind": "count"},
        ],
    ]
    brands = sorted({vehicle["brand"] for vehicle in vehicles})
    statuses = ["available", "in_progress", "in_repair", "sold"]
    price_buckets = [
        "Below 1 Lakh",
        "1 to 3 Lakhs",
        "3 to 7 Lakhs",
        "7 Lakhs and above",
        "Price on request",
    ]
    purchase_types = ["Direct", "Finance", "Agent", "Branch"]
    return render_template(
        "gallery.html",
        vehicles=vehicles,
        brands=brands,
        statuses=statuses,
        price_buckets=price_buckets,
        purchase_types=purchase_types,
        catalog_summary_rows=catalog_summary_rows,
    )

@app.route("/vehicle/<int:vehicle_id>")
def vehicle_detail(vehicle_id):
    conn = get_db()

    vehicle_row = conn.execute(
        "SELECT * FROM vehicles WHERE id = ?",
        (vehicle_id,),
    ).fetchone()

    if not vehicle_row:
        conn.close()
        return "Vehicle not found", 404

    # ===== ADD THIS BLOCK =====
    status = str(vehicle_row.get("status") or "").strip().lower()

    if status == "sold":
        sale_row = conn.execute(
            """
            SELECT TOP 1 order_id
            FROM vehicle_sale_orders
            WHERE vehicle_id = ?
            ORDER BY id DESC
            """,
            (vehicle_id,),
        ).fetchone()

        if sale_row and sale_row.get("order_id"):
            conn.close()
            return redirect(
                url_for(
                    "order_detail",
                    order_id=sale_row["order_id"],
                    source="orders"
                )
            )
    # ===== END BLOCK =====

    vehicle = build_gallery_vehicle_payload(vehicle_row)

    related_rows = conn.execute(
        """
        SELECT TOP 4 *
        FROM vehicles
        WHERE id <> ?
        ORDER BY
            CASE WHEN LOWER(ISNULL(status, 'available')) = ? THEN 0 ELSE 1 END,
            CASE WHEN vehicle_name LIKE ? THEN 0 ELSE 1 END,
            ISNULL(updated_at, created_at) DESC,
            id DESC
        """,
        (vehicle_id, vehicle["status_value"], f"{vehicle['brand']}%"),
    ).fetchall()

    conn.close()

    related_vehicles = [build_gallery_vehicle_payload(row) for row in related_rows]

    return render_template(
        "vehicle_detail.html",
        vehicle=vehicle,
        related_vehicles=related_vehicles,
        enquiry_error="",
        enquiry_success=request.args.get("status", "").strip() == "enquiry_sent",
    )


@app.route("/vehicle/<int:vehicle_id>/enquiry", methods=["POST"])
def vehicle_enquiry_submit(vehicle_id: int):
    customer_name = (request.form.get("customer_name") or "").strip()
    customer_phone = (request.form.get("customer_phone") or "").strip()
    if not customer_name or not customer_phone:
        conn = get_db()
        vehicle_row = conn.execute(
            "SELECT * FROM vehicles WHERE id = ?",
            (vehicle_id,),
        ).fetchone()
        if not vehicle_row:
            conn.close()
            return redirect(url_for("gallery"))
        vehicle = build_gallery_vehicle_payload(vehicle_row)
        related_rows = conn.execute(
            """
            SELECT TOP 4 *
            FROM vehicles
            WHERE id <> ?
            ORDER BY ISNULL(updated_at, created_at) DESC, id DESC
            """,
            (vehicle_id,),
        ).fetchall()
        conn.close()
        related_vehicles = [build_gallery_vehicle_payload(row) for row in related_rows]
        return render_template(
            "vehicle_detail.html",
            vehicle=vehicle,
            related_vehicles=related_vehicles,
            enquiry_error="Customer name and phone number are required.",
            enquiry_success=False,
        )

    branch = get_current_branch()
    branch_name = (branch or {}).get("name") or get_setting("branch_name", "")
    conn = get_db()
    vehicle_exists = conn.execute("SELECT id FROM vehicles WHERE id = ?", (vehicle_id,)).fetchone()
    if not vehicle_exists:
        conn.close()
        return redirect(url_for("gallery"))
    conn.execute(
        """
        INSERT INTO vehicle_enquiries (
            vehicle_id,
            customer_name,
            customer_phone,
            branch_name,
            created_at,
            is_read
        )
        VALUES (?, ?, ?, ?, SYSDATETIME(), 0)
        """,
        (vehicle_id, customer_name, customer_phone, branch_name or None),
    )
    conn.commit()
    conn.close()
    return redirect(url_for("vehicle_detail", vehicle_id=vehicle_id, status="enquiry_sent"))

@app.route("/sell-your-bike")
def customer_sell_page():
    status = request.args.get("status", "")
