    enquiry = dict(enquiry_row)
    enquiry["brand"] = derive_vehicle_brand(enquiry.get("vehicle_name"))
    enquiry["status_value"] = ((enquiry.get("status") or "available").strip() or "available").lower()
    enquiry["price_bucket"] = derive_vehicle_price_bucket(enquiry.get("selling_price"))
    return render_template("vehicle_enquiry_detail.html", enquiry=enquiry)

