def generate_vehicle_sales_report(
    from_date: str,
    to_date: str,
    *,
    payment_mode: str = "",
    q: str = "",
    status_filter: str = "",
):
    from_dt = from_date + " 00:00:00"
    to_dt = to_date + " 23:59:59"

    conn = get_db()
    query = """
        SELECT
            vso.sale_code,
            vso.created_at,
            vso.vehicle_name,
            vso.vehicle_number,
            vso.customer_name,
            vso.total_amount,
            vso.advance_amount,
            o.paid_amount,
            vso.payment_method,
            o.status AS order_status
        FROM vehicle_sale_orders vso
        LEFT JOIN orders o ON o.id = vso.order_id
        WHERE LOWER(COALESCE(o.status, 'in-progress')) <> 'cancelled'
          AND vso.created_at BETWEEN ? AND ?
    """
    params: list[str] = [from_dt, to_dt]
    if payment_mode:
        query += " AND LOWER(COALESCE(vso.payment_method, '')) = ?"
        params.append(payment_mode.lower())
    if q:
        query += " AND (LOWER(COALESCE(vso.vehicle_number, '')) LIKE ? OR LOWER(COALESCE(vso.vehicle_name, '')) LIKE ? OR LOWER(COALESCE(vso.customer_name, '')) LIKE ?)"
        like = f"%{q.lower()}%"
        params.extend([like, like, like])
    query += " ORDER BY vso.created_at"
    rows = conn.execute(query, tuple(params)).fetchall()
    conn.close()

    filtered_rows = []
    for row in rows:
        try:
            total_amount = float(row["total_amount"] or 0)
        except Exception:
            total_amount = 0.0
        try:
            advance_amount = float(row["advance_amount"] or 0)
        except Exception:
            advance_amount = 0.0
        try:
            paid_amount = float(row["paid_amount"] or 0)
        except Exception:
            paid_amount = 0.0
        paid_total = max(0.0, advance_amount + paid_amount)
        due_amount = max(0.0, total_amount - paid_total)
        if total_amount <= 0:
            settlement_status = "Unpaid"
        elif due_amount <= 0.009:
            settlement_status = "Paid"
        elif paid_total > 0:
            settlement_status = "Partial"
        else:
            settlement_status = "Unpaid"
        if status_filter and settlement_status != status_filter:
            continue
        filtered_rows.append((row, total_amount, paid_total, due_amount, settlement_status))

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    file_path = os.path.join(REPORT_DIR, f"sales_report_{ts}.pdf")
    os.makedirs(os.path.dirname(file_path), exist_ok=True)

    doc = SimpleDocTemplate(
        file_path,
        pagesize=A4,
        leftMargin=24,
        rightMargin=24,
        topMargin=REPORT_TOP_MARGIN,
        bottomMargin=24,
    )
    regular_report_font, bold_report_font = get_reportlab_tamil_fonts()
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        name="SalesReportTitle",
        parent=styles["Heading2"],
        fontName=bold_report_font,
        fontSize=15,
        leading=18,
        spaceAfter=6,
    )
    subtitle_style = ParagraphStyle(
        name="SalesReportSubtitle",
        parent=styles["Normal"],
        fontName=regular_report_font,
        fontSize=10,
        textColor=colors.HexColor("#333333"),
        spaceAfter=12,
    )
    normal_style = ParagraphStyle(
        name="SalesReportNormalTamil",
        parent=styles["Normal"],
        fontName=regular_report_font,
    )

    elements: list = []
    elements.append(Paragraph("Sales Report", title_style))
    elements.append(Paragraph(f"From {from_date} To {to_date}", subtitle_style))

    table_data = [["Sale", "Date", "Vehicle No", "Buyer", "Total", "Paid", "Due", "Paymode", "Status"]]
    for row, total_amount, paid_total, due_amount, settlement_status in filtered_rows:
        table_data.append(
            [
                str(row["sale_code"] or ""),
                format_report_date(row["created_at"]),
                str(row["vehicle_number"] or ""),
                str(row["customer_name"] or ""),
                f"{total_amount:.2f}",
                f"{paid_total:.2f}",
                f"{due_amount:.2f}",
                str(row["payment_method"] or ""),
                settlement_status,
            ]
        )

    if len(table_data) == 1:
        elements.append(Paragraph("No sales found for selected date range.", normal_style))
    else:
        col_widths = [70, 60, 85, 120, 55, 55, 55, 60, 55]
        table = Table(table_data, colWidths=col_widths, repeatRows=1)
        table.setStyle(
            TableStyle(
                [
                    ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#efefef")),
                    ("TEXTCOLOR", (0, 0), (-1, 0), colors.black),
                    ("FONTNAME", (0, 0), (-1, 0), bold_report_font),
                    ("FONTNAME", (0, 1), (-1, -1), regular_report_font),
                    ("FONTSIZE", (0, 0), (-1, -1), 9),
                    ("ALIGN", (4, 1), (6, -1), "RIGHT"),
                    ("ALIGN", (0, 0), (-1, 0), "CENTER"),
                    ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                    ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#b5b5b5")),
                    ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#fafafa")]),
                    ("LEFTPADDING", (0, 0), (-1, -1), 6),
                    ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                    ("TOPPADDING", (0, 0), (-1, -1), 5),
                    ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
                ]
            )
        )
        elements.append(table)
        elements.append(Spacer(1, 8))

    header_draw = build_report_page_header()
    doc.build(elements, onFirstPage=header_draw, onLaterPages=header_draw)
    return redirect(url_for("static", filename=f"reports/sales_report_{ts}.pdf"))

def generate_sales_summary_report(from_date: str, to_date: str, *, q: str = ""):
    from_dt = from_date + " 00:00:00"
    to_dt = to_date + " 23:59:59"

    conn = get_db()
    query = """
        SELECT
            vso.sale_code,
            vso.created_at,
            vso.vehicle_name,
            vso.vehicle_number,
            v.purchase_price AS purchase_cost,
            vso.repair_cost AS repair_cost,
            vso.total_amount AS selling_amount
        FROM vehicle_sale_orders vso
        JOIN vehicles v ON v.id = vso.vehicle_id
        LEFT JOIN orders o ON o.id = vso.order_id
        WHERE vso.order_id IS NOT NULL
          AND LOWER(COALESCE(o.status, 'in-progress')) <> 'cancelled'
          AND vso.created_at BETWEEN ? AND ?
    """
    params: list[str] = [from_dt, to_dt]
    if q:
        query += " AND (LOWER(COALESCE(vso.vehicle_number, '')) LIKE ? OR LOWER(COALESCE(vso.vehicle_name, '')) LIKE ?)"
        like = f"%{q.lower()}%"
        params.extend([like, like])
    query += " ORDER BY vso.created_at"
    rows = conn.execute(query, tuple(params)).fetchall()
    conn.close()

    computed_rows = []
    total_purchase = 0.0
    total_repair = 0.0
    total_selling = 0.0
    total_profit = 0.0
    for row in rows:
        purchase_cost = float(row["purchase_cost"] or 0)
        repair_cost = float(row["repair_cost"] or 0)
        selling_amount = float(row["selling_amount"] or 0)
        profit = round(selling_amount - purchase_cost - repair_cost, 2)
        total_purchase += purchase_cost
        total_repair += repair_cost
        total_selling += selling_amount
        total_profit += profit
        computed_rows.append((row, purchase_cost, repair_cost, selling_amount, profit))

    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    file_path = os.path.join(REPORT_DIR, f"sales_summary_report_{ts}.pdf")
    os.makedirs(os.path.dirname(file_path), exist_ok=True)

    doc = SimpleDocTemplate(
        file_path,
        pagesize=A4,
        leftMargin=24,
        rightMargin=24,
        topMargin=REPORT_TOP_MARGIN,
        bottomMargin=24,
    )
    regular_report_font, bold_report_font = get_reportlab_tamil_fonts()
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        name="SalesSummaryReportTitle",
        parent=styles["Heading2"],
        fontName=bold_report_font,
        fontSize=15,
        leading=18,
        spaceAfter=6,
    )
    subtitle_style = ParagraphStyle(
        name="SalesSummaryReportSubtitle",
        parent=styles["Normal"],
        fontName=regular_report_font,
        fontSize=10,
        textColor=colors.HexColor("#333333"),
        spaceAfter=12,
    )
    normal_style = ParagraphStyle(
        name="SalesSummaryReportNormalTamil",
        parent=styles["Normal"],
        fontName=regular_report_font,
    )

    elements: list = []
    elements.append(Paragraph("Sales Summary Report", title_style))
    elements.append(Paragraph(f"From {from_date} To {to_date}", subtitle_style))

    table_data = [["Sale", "Date", "Vehicle No", "Vehicle", "Purchase", "Repair", "Selling", "Profit"]]
    for row, purchase_cost, repair_cost, selling_amount, profit in computed_rows:
        table_data.append(
            [
                str(row["sale_code"] or ""),
                format_report_date(row["created_at"]),
                str(row["vehicle_number"] or ""),
                str(row["vehicle_name"] or ""),
                f"{purchase_cost:.2f}",
                f"{repair_cost:.2f}",
                f"{selling_amount:.2f}",
                f"{profit:.2f}",
            ]
        )

    if len(table_data) == 1:
        elements.append(Paragraph("No sales found for selected date range.", normal_style))
    else:
        table_data.append(
            [
                "", "", "", "Total",
                f"{total_purchase:.2f}",
                f"{total_repair:.2f}",
                f"{total_selling:.2f}",
                f"{total_profit:.2f}",
            ]
        )
        col_widths = [65, 60, 85, 110, 60, 60, 60, 60]
        table = Table(table_data, colWidths=col_widths, repeatRows=1)
