        discount_amount = round(min(as_money(form_data["discount_amount"]), subtotal_amount), 2)
        advance_amount = round(as_money(form_data["advance_amount"]), 2)
        taxable_amount = round(max(subtotal_amount - discount_amount, 0.0), 2)
