@app.route("/orders/new/material", methods=["GET", "POST"])
def order_new_material():
    conn = get_db()
    reseed_identity_if_empty(conn, "customers", seed=0)
    next_order_id = conn.execute(
        "SELECT COALESCE(MAX(id), 0) + 1 FROM orders"
    ).fetchone()[0]
    # next_order_code = generate_order_no(conn, "Material")
    next_order_code = "Will generate after customer selected"
    next_customer_display_id = conn.execute(
        "SELECT COALESCE(MAX(id), 0) + 1 FROM customers"
    ).fetchone()[0]
    now_dt = datetime.now()
    order_date_offset_days = int(get_setting("order_date_offset_days", "0") or 0)
    if order_date_offset_days:
        now_dt = now_dt + timedelta(days=order_date_offset_days)
    today_date = now_dt.strftime("%Y-%m-%d %H:%M")
    base_date = now_dt.date()
    worker_days = int(get_setting("worker_delivery_days", "0") or 0)
    delivery_days = int(get_setting("delivery_days", "0") or 0)
    worker_default = (base_date + timedelta(days=worker_days)).isoformat() if worker_days else ""
    delivery_default = (base_date + timedelta(days=delivery_days)).isoformat() if delivery_days else ""
    inventory = conn.execute(
        """
        SELECT inventory.id, inventory.inventory_code, inventory.name, inventory.qty,
               inventory.selling_price, inventory.uom_id, uoms.name AS uom_name
        FROM inventory
        LEFT JOIN uoms ON uoms.id = inventory.uom_id
        ORDER BY inventory.name ASC
        """
    ).fetchall()

    customer_id_param = request.args.get("customer_id", "").strip()
    prefill_customer_id = None
    prefill_name = ""
    prefill_phone = ""
    prefill_address = ""
    prefill_notes = ""

    if customer_id_param.isdigit():
        prefill_customer_id = int(customer_id_param)
        row = conn.execute(
            "SELECT id, name, phone, address, notes FROM customers WHERE id = ?",
            (prefill_customer_id,),
        ).fetchone()
        if row:
            prefill_name = row["name"]
            prefill_phone = row["phone"]
            prefill_address = row["address"]
            prefill_notes = row["notes"]
    display_customer_id = int(next_customer_display_id)
    conn.close()

    if request.method == "POST":
        name = request.form.get("name", "").strip()
        phone = request.form.get("phone", "").strip()
        notes = request.form.get("customer_notes", "").strip()
        address = request.form.get("address", "").strip()
        if not name or not phone:
            return render_template(
                "order_new_material.html",
                next_order_id=next_order_id,
                next_order_code=next_order_code,
                display_customer_id=display_customer_id,
                inventory=inventory,
                today_date=today_date,
                worker_default=worker_default,
                delivery_default=delivery_default,
                prefill_customer_id=prefill_customer_id,
                prefill_name=name,
                prefill_phone=phone,
                prefill_address=address,
                prefill_notes=notes,
                error="Customer name and phone are required.",
            )
        if not is_valid_phone(phone):
            return render_template(
                "order_new_material.html",
                next_order_id=next_order_id,
                next_order_code=next_order_code,
                display_customer_id=display_customer_id,
                inventory=inventory,
                today_date=today_date,
                worker_default=worker_default,
                delivery_default=delivery_default,
                prefill_customer_id=prefill_customer_id,
                prefill_name=name,
                prefill_phone=phone,
                prefill_address=address,
                prefill_notes=notes,
                error="Phone number must contain digits only. (+ is optional.)",
            )

        # Always resolve customer by phone first; reuse existing ID when matched.
        customer_id = upsert_customer(name, phone, notes, address)
        order_notes = request.form.get("order_notes", "").strip() or None
        payment_method = request.form.get("payment_method", "Cash").strip()
        allowed_payment_methods = {"Cash", "GPay", "Card"}
        if payment_method not in allowed_payment_methods:
            payment_method = "Cash"
        payment_text = f"Payment method: {payment_method}"
        order_notes = f"{payment_text}\n{order_notes}" if order_notes else payment_text
        due_date = None
        advance_amount = request.form.get("advance_amount", "").strip()
        total_amount = request.form.get("total_amount", "").strip()
        advance_value = float(advance_amount) if advance_amount else None
        total_value = float(total_amount) if total_amount else None
        if not total_value or total_value <= 0:
            return render_template(
                "order_new_material.html",
                next_order_id=next_order_id,
                next_order_code=next_order_code,
                display_customer_id=display_customer_id,
                inventory=inventory,
                today_date=today_date,
                worker_default=worker_default,
                delivery_default=delivery_default,
                prefill_customer_id=prefill_customer_id,
                prefill_name=prefill_name,
                prefill_phone=prefill_phone,
                prefill_address=prefill_address,
                prefill_notes=prefill_notes,
                error="Total cost must be greater than 0.",
            )
        gst_enabled = is_gst_enabled_for_order_type("Material")
        tax_payload = parse_order_tax_payload(request.form, total_value)
        tax_payload = apply_gst_toggle_to_tax_payload(tax_payload, total_value, gst_enabled)
        discount_amount = parse_order_discount_amount(request.form, tax_payload["taxable_amount"])

        item_ids = request.form.getlist("material_item_id")
        qty_values = request.form.getlist("material_qty")
        unit_price_values = request.form.getlist("material_unit_price")

        order_customer_display_id = customer_display_id(customer_id)
        conn = get_db()
        cur = conn.cursor()
        # order_no = generate_order_no(conn, "Material")
        order_no = generate_order_no(conn, customer_id)
        cur.execute(
            """
            INSERT INTO orders (
                customer_id, customer_display_id, order_no, due_date, status, priority,
                assigned_team, assigned_tailor, notes,
                advance_amount, discount_amount, total_amount, taxable_amount, gst_percent, gst_amount,
                cgst_percent, cgst_amount, sgst_percent, sgst_amount,
                order_type, order_material_source,
                inventory_applied, created_at
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                customer_id,
                order_customer_display_id,
                order_no,
                due_date,
                "Delivered",
                "Normal",
                None,
                None,
                order_notes,
                advance_value,
                discount_amount,
                total_value,
                tax_payload["taxable_amount"],
                tax_payload["gst_percent"],
                tax_payload["gst_amount"],
                tax_payload["cgst_percent"],
                tax_payload["cgst_amount"],
                tax_payload["sgst_percent"],
                tax_payload["sgst_amount"],
                "Material",
                "inventory",
                1,
                now_str(),
            ),
        )
        order_id = cur.lastrowid
        if order_id is None:
            conn.rollback()
            conn.close()
            return render_template(
                "order_new_material.html",
                next_order_id=next_order_id,
                next_order_code=next_order_code,
                display_customer_id=display_customer_id,
                inventory=inventory,
                today_date=today_date,
                worker_default=worker_default,
                delivery_default=delivery_default,
                prefill_customer_id=prefill_customer_id,
                prefill_name=prefill_name,
                prefill_phone=prefill_phone,
                prefill_address=prefill_address,
                prefill_notes=prefill_notes,
                error="Unable to save order. Please try again.",
            )

        inv_rows = cur.execute(
            """
            SELECT inventory.id, inventory.name, inventory.qty, inventory.uom_id,
                   uoms.name AS uom_name
            FROM inventory
            LEFT JOIN uoms ON uoms.id = inventory.uom_id
            """
        ).fetchall()
        inv_map = {str(row["id"]): row for row in inv_rows}

        for item_id, qty_raw, unit_price_raw in zip(item_ids, qty_values, unit_price_values, strict=False):
            if not item_id or item_id not in inv_map:
                continue
            try:
                qty = float(qty_raw)
                unit_price = float(unit_price_raw)
            except (TypeError, ValueError):
                continue
            if qty <= 0 or unit_price < 0:
                continue
            inv_row = inv_map[item_id]
            line_total = unit_price * qty
            cur.execute(
                """
                INSERT INTO order_material_items
                    (order_id, inventory_id, uom_id, qty, unit_price, line_total)
                VALUES (?, ?, ?, ?, ?, ?)
                """,
                (order_id, int(item_id), inv_row["uom_id"], qty, unit_price, line_total),
            )
            new_qty = max(float(inv_row["qty"] or 0) - qty, 0)
            cur.execute(
                "UPDATE inventory SET qty = ?, updated_at = ? WHERE id = ?",
                (new_qty, now_str(), int(item_id)),
            )

        conn.commit()
        conn.close()
        return redirect(url_for("order_detail", order_id=order_id))

    return render_template(
        "order_new_material.html",
        next_order_id=next_order_id,
        next_order_code=next_order_code,
        display_customer_id=display_customer_id,
        inventory=inventory,
        today_date=today_date,
        worker_default=worker_default,
        delivery_default=delivery_default,
        prefill_customer_id=prefill_customer_id,
        prefill_name=prefill_name,
        prefill_phone=prefill_phone,
        prefill_address=prefill_address,
        prefill_notes=prefill_notes,
    )

@app.route("/expense", methods=["GET", "POST"])
def expense_dashboard():
    raw_type = (request.args.get("type") or "").strip().lower()
    filter_type = raw_type or "repair"  # expense | repair (default: repair)
    if filter_type not in {"expense", "repair"}:
        filter_type = "repair"
    category_filter = (request.args.get("category") or "").strip()
    conn = get_db()
    ensure_expenses_category_column(conn)
    ensure_expense_categories_table(conn)

    quick_error = None
    quick_form = None

    if request.method == "POST":
        is_repair = (request.form.get("is_repair") == "1")
        description = (request.form.get("description") or "").strip()
        category_input = (request.form.get("category") or "").strip()
        vehicle_number_input = (request.form.get("vehicle_number") or "").strip()
        amount_raw = (request.form.get("amount") or "").strip()
        amount = 0.0
        error = None

        if not description:
            error = "Description is required."
        if not error and not is_repair and not category_input:
            error = "Category is required."
        if not error:
            try:
                amount = float(amount_raw)
            except ValueError:
                error = "Invalid amount."
        if not error and amount <= 0:
            error = "Amount should be greater than 0."
        if not error and is_repair and not vehicle_number_input:
            error = "Vehicle number is required for repair."

        if not error:
            created_at = now_str()
            try:
                if is_repair:
                    vehicle_row = conn.execute(
                        """
                        SELECT TOP 1 id, vehicle_name, vehicle_number
                        FROM vehicles
                        WHERE UPPER(LTRIM(RTRIM(vehicle_number))) = UPPER(LTRIM(RTRIM(?)))
                          AND LOWER(COALESCE(status, 'available')) NOT IN ('sold', 'transferred')
                        ORDER BY id DESC
                        """,
                        (vehicle_number_input,),
                    ).fetchone()
                    if not vehicle_row:
                        error = "Vehicle not found. Enter a valid vehicle number."
                    else:
                        print("=== ADD REPAIR API CALLED ===")
                        print("Vehicle ID:", vehicle_row["id"])
                        expense_id = upsert_repair_expense(
                            conn,
                            None,
                            amount,
                            vehicle_row.get("vehicle_name"),
                            vehicle_row.get("vehicle_number"),
                            created_at,
                        )
                        repair_date = datetime.now().date().isoformat()
                        conn.execute(
                            """
                            INSERT INTO vehicle_repairs
                                (vehicle_id, expense_id, repair_status, repair_date, description, cost, total_cost, created_at)
                            VALUES
                                (?, ?, ?, ?, ?, ?, ?, ?)
                            """,
                            (
                                int(vehicle_row["id"]),
                                int(expense_id),
                                "Completed",
                                repair_date,
                                description,
                                amount,
                                amount,
                                created_at,
                            ),
                        )
                        update_cursor = conn.execute(
                            """
                            UPDATE vehicles
                            SET status = ?
                            WHERE id = ?
                            """,
                            (
                                "In Repair",
                                int(vehicle_row["id"]),
                            ),
                        )
                        print("Rows updated:", update_cursor.rowcount)
                else:
                    create_expense_record(conn, description, amount, now_str(), category=category_input)
                    add_expense_category_if_missing(conn, category_input)
            except Exception:
                error = "Unable to save. Please try again."

        if error:
            conn.rollback()
            quick_error = error
            quick_form = {
                "is_repair": "1" if is_repair else "0",
                "vehicle_number": vehicle_number_input,
                "description": description,
                "category": category_input,
                "amount": amount_raw,
            }
            filter_type = "repair" if is_repair else "expense"
        else:
            conn.commit()
            conn.close()
            redirect_args = {"type": ("repair" if is_repair else "expense"), "open": "1"}
            if not is_repair and category_input:
                redirect_args["category"] = category_input
            return redirect(url_for("expense_dashboard", **redirect_args))

    expense_totals = get_expense_breakdown_totals(conn)
    total_expense = float(expense_totals.get("misc") or 0.0)
    total_salary = float(expense_totals.get("salary") or 0.0)
    total_repair = float(expense_totals.get("repair") or 0.0)
    total_all_expenses = float(expense_totals.get("all") or 0.0)
    expense_series = get_expense_breakdown_daily_series(conn, end_date=datetime.now().date(), days=7)

    repairs = []
    expenses = []
    category_tabs: list[str] = []
    if filter_type == "repair":
        repairs = conn.execute(
            """
            SELECT r.id,
                   e.expense_no,
                   r.repair_date,
                   r.description,
                   r.cost,
                   r.total_cost,
                   r.advance_amount,
                   r.repair_kits,
                   r.payment_mode,
                   r.assigned_staff_no,
                   r.repair_status,
                   r.created_at,
                   v.vehicle_name,
                   v.vehicle_number,
                   v.photo_filename,
                   t.name AS assigned_staff_name
            FROM vehicle_repairs r
            JOIN vehicles v ON v.id = r.vehicle_id
            LEFT JOIN expenses e ON e.id = r.expense_id
            LEFT JOIN tailors t
              ON CAST(t.id AS NVARCHAR(100)) = r.assigned_staff_no
              OR t.tailor_code = r.assigned_staff_no
            ORDER BY COALESCE(r.repair_date, CAST(r.created_at AS DATE)) DESC, r.id DESC
            """
        ).fetchall()
    else:
        try:
            category_rows = conn.execute(
                "SELECT name FROM expense_categories ORDER BY name"
            ).fetchall()
            category_tabs = [row["name"] for row in category_rows if row.get("name")]
        except Exception:
            category_tabs = []

        expense_sql = """
            SELECT e.id,
                   e.expense_no,
                   e.expense_name,
                   e.amount,
                   e.category,
                   e.created_at,
                   vr.id AS repair_id
            FROM expenses e
            LEFT JOIN vehicle_repairs vr ON vr.expense_id = e.id
            LEFT JOIN salaries s ON s.expense_id = e.id
            WHERE s.id IS NULL AND vr.id IS NULL
        """
        expense_params: list[str] = []
        if category_filter:
            expense_sql += " AND LOWER(COALESCE(e.category, '')) = LOWER(?)"
            expense_params.append(category_filter)
        expense_sql += " ORDER BY e.created_at DESC"
        expenses = conn.execute(expense_sql, tuple(expense_params)).fetchall()

    quick_expense_no = generate_expense_no(conn)
    conn.close()

    return render_template(
        "expense_dashboard.html",
        total_expense=total_expense,
        total_salary=total_salary,
        total_repair=total_repair,
        total_all_expenses=total_all_expenses,
        expense_day_labels=expense_series.get("labels") or [],
        expense_day_misc_values=expense_series.get("misc") or [],
        expense_day_salary_values=expense_series.get("salary") or [],
        expense_day_repair_values=expense_series.get("repair") or [],
        expense_day_total_values=expense_series.get("total") or [],
        expenses=expenses,
        repairs=repairs,
        filter_type=filter_type,
        category_tabs=category_tabs,
        category_filter=category_filter,
        quick_expense_no=quick_expense_no,
        quick_error=quick_error,
        quick_form=quick_form,
    )


@app.route("/expense/category/add", methods=["POST"])
def expense_category_add():
    name = (request.form.get("name") or "").strip()
    if not name and request.is_json:
        data = request.get_json(silent=True) or {}
        name = (data.get("name") or "").strip()
    if not name:
        return jsonify({"ok": False, "error": "Category name is required."}), 400

    conn = get_db()
    try:
        ensure_expense_categories_table(conn)
        existing = conn.execute(
            "SELECT TOP 1 id, name FROM expense_categories WHERE LOWER(name) = LOWER(?)",
            (name,),
        ).fetchone()
        if existing:
            conn.close()
            return jsonify({"ok": True, "name": existing["name"], "existing": True})
        conn.execute(
            "INSERT INTO expense_categories (name, created_at) VALUES (?, ?)",
            (name, now_str()),
        )
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "name": name, "existing": False})
    except Exception:
        conn.rollback()
        conn.close()
        return jsonify({"ok": False, "error": "Unable to add category."}), 500


@app.route("/expense/repair/add", methods=["GET", "POST"])
def expense_repair_add():
    conn = get_db()
    prefill_vehicle_id = (request.args.get("vehicle_id") or "").strip()
    prefill_vehicle = None
    if prefill_vehicle_id:
        try:
            prefill_vehicle = conn.execute(
                """
                SELECT id, vehicle_name, vehicle_number
                FROM vehicles
                WHERE id = ?
                """,
                (int(prefill_vehicle_id),),
            ).fetchone()
        except Exception:
            prefill_vehicle = None
    vehicles = conn.execute(
        "SELECT id, vehicle_name, vehicle_number, model_year, status, photo_filename FROM vehicles WHERE LOWER(COALESCE(status, 'available')) NOT IN ('sold', 'transferred') ORDER BY vehicle_name"
    ).fetchall()

    error = ""
    if request.method == "POST":
        vehicle_name_input = (request.form.get("vehicle_name") or "").strip()
        vehicle_number_input = (request.form.get("vehicle_number") or "").strip()
        repair_date = (request.form.get("repair_date") or "").strip() or None
        total_cost_raw = (request.form.get("total_cost") or "").strip()
        description = (request.form.get("description") or "").strip()
        if not error and not vehicle_name_input:
            error = "Vehicle name is required."
        elif not error and not vehicle_number_input:
            error = "Vehicle number is required."
        elif not error and not total_cost_raw:
            error = "Repair amount is required."

        vehicle_row = None
        if not error:
            try:
                total_cost = float(total_cost_raw) if total_cost_raw else 0.0
            except ValueError:
                error = "Repair amount is invalid."
        if not error and total_cost <= 0:
            error = "Repair amount is required."
        if not error:
            vehicle_row = conn.execute(
                """
                SELECT id, vehicle_name, vehicle_number
                FROM vehicles
                WHERE LTRIM(RTRIM(vehicle_name)) = ? AND LTRIM(RTRIM(vehicle_number)) = ?
                  AND LOWER(COALESCE(status, 'available')) NOT IN ('sold', 'transferred')
                """,
                (vehicle_name_input, vehicle_number_input),
            ).fetchone()
            if not vehicle_row:
                error = "Vehicle not found. Enter the same vehicle name and number as in inventory."

        created_repairs: list[int] = []
        if not error and vehicle_row:
            created_at = f"{repair_date} 00:00" if repair_date else now_str()
            expense_id = upsert_repair_expense(
                conn,
                None,
                total_cost,
                vehicle_row.get("vehicle_name"),
                vehicle_row.get("vehicle_number"),
                created_at,
            )
            cur = conn.cursor()
            cur.execute(
                """
                INSERT INTO vehicle_repairs
                    (vehicle_id, expense_id, assigned_staff_no, repair_status, repair_date, description, cost, total_cost, advance_amount, repair_kits, repair_kit_costs, payment_mode, created_at)
                VALUES
                    (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    int(vehicle_row["id"]),
                    expense_id,
                    None,
                    "In-Progress",
                    repair_date,
                    description or "Repair expense",
                    total_cost,
                    total_cost,
                    0.0,
                    None,
                    None,
                    None,
                    created_at,
                ),
            )
            status_update_cur = conn.execute(
                """
                UPDATE vehicles
                SET status = ?
                WHERE id = ?
                """,
                (
                    "In Repair",
                    int(vehicle_row["id"]),
                ),
            )
            print("Vehicle ID:", vehicle_row["id"])
            print("Rows updated:", status_update_cur.rowcount)
            if cur.lastrowid:
                created_repairs.append(int(cur.lastrowid))

        if error:
            conn.rollback()
        elif created_repairs:
            conn.commit()
            repair_id = created_repairs[-1]
            repair_row = conn.execute(
                """
                SELECT r.*, v.vehicle_name, v.vehicle_number
                FROM vehicle_repairs r
                JOIN vehicles v ON v.id = r.vehicle_id
                WHERE r.id = ?
                """,
                (repair_id,),
            ).fetchone()
            if repair_row:
                try:
                    generate_repair_pdf_72x210mm(repair_row)
                except Exception:
                    pass
                conn.close()
                return redirect(url_for("expense_repair_detail", repair_id=repair_id, mode="view", saved="1"))
            conn.close()
            return redirect(url_for("expense_dashboard", type="repair"))

    conn.close()
    return render_template(
        "repair_add.html",
        mode="add",
        vehicles=vehicles,
        repair=None,
        prefill_vehicle=prefill_vehicle,
        today_date=date.today().isoformat(),
        error=error,
        saved=False,
        back_url="",
    )


@app.route("/expense/repair/<int:repair_id>", methods=["GET", "POST"])
def expense_repair_detail(repair_id: int):
    mode = (request.args.get("mode") or "view").strip().lower()
    view_only = mode != "edit"
    back_url = (request.args.get("back_url") or "").strip()
    conn = get_db()
    vehicles = conn.execute(
        "SELECT id, vehicle_name, vehicle_number, model_year, status, photo_filename FROM vehicles ORDER BY vehicle_name"
    ).fetchall()
    repair = conn.execute(
        """
        SELECT r.*, v.vehicle_name, v.vehicle_number, v.model_year, v.status, v.photo_filename,
               t.name AS assigned_staff_name
        FROM vehicle_repairs r
        JOIN vehicles v ON v.id = r.vehicle_id
        LEFT JOIN tailors t
          ON CAST(t.id AS NVARCHAR(100)) = r.assigned_staff_no
          OR t.tailor_code = r.assigned_staff_no
        WHERE r.id = ?
        """,
        (repair_id,),
    ).fetchone()
    if not repair:
        conn.close()
        return redirect(url_for("expense_dashboard", type="repair"))

    error = ""
    if request.method == "POST":
        if view_only:
            conn.close()
            return redirect(url_for("expense_repair_detail", repair_id=repair_id, mode="view"))

        vehicle_name_input = (request.form.get("vehicle_name") or "").strip()
        vehicle_number_input = (request.form.get("vehicle_number") or "").strip()
        repair_date = (request.form.get("repair_date") or "").strip() or None
        total_cost_raw = (request.form.get("total_cost") or "").strip()
        description = (request.form.get("description") or "").strip()

        if not error and not vehicle_name_input:
            error = "Vehicle name is required."
        elif not error and not vehicle_number_input:
            error = "Vehicle number is required."
        elif not error and not total_cost_raw:
            error = "Repair amount is required."
        if not error:
            try:
                total_cost = float(total_cost_raw) if total_cost_raw else 0.0
            except ValueError:
                error = "Repair amount is invalid."
        if not error and total_cost <= 0:
            error = "Repair amount is required."

        vehicle_row = None
        if not error:
            vehicle_row = conn.execute(
                """
                SELECT id, vehicle_name, vehicle_number
                FROM vehicles
                WHERE LTRIM(RTRIM(vehicle_name)) = ? AND LTRIM(RTRIM(vehicle_number)) = ?
                  AND LOWER(COALESCE(status, 'available')) NOT IN ('sold', 'transferred')
                """,
                (vehicle_name_input, vehicle_number_input),
            ).fetchone()
            if not vehicle_row:
                error = "Vehicle not found. Enter the same vehicle name and number as in inventory."

        if not error:
            created_at = f"{repair_date} 00:00" if repair_date else now_str()
            expense_id = upsert_repair_expense(
                conn,
                int(repair.get("expense_id") or 0) or None,
                total_cost,
                vehicle_row.get("vehicle_name"),
                vehicle_row.get("vehicle_number"),
                created_at,
            )
            conn.execute(
                """
                UPDATE vehicle_repairs
                SET vehicle_id = ?,
                    expense_id = ?,
                    assigned_staff_no = ?,
                    repair_status = ?,
                    repair_date = ?,
                    description = ?,
                    cost = ?,
                    total_cost = ?,
                    advance_amount = ?,
                    repair_kits = ?,
                    repair_kit_costs = ?,
                    payment_mode = ?,
                    created_at = ?
                WHERE id = ?
                """,
                (
                    int(vehicle_row["id"]),
                    expense_id,
                    None,
                    "In-Progress",
                    repair_date,
                    description or "Repair expense",
                    total_cost,
                    total_cost,
                    0.0,
                    None,
                    None,
                    None,
                    created_at,
                    repair_id,
                ),
            )
            conn.commit()
            try:
                updated = conn.execute(
                    """
                    SELECT r.*, v.vehicle_name, v.vehicle_number
                    FROM vehicle_repairs r
                    JOIN vehicles v ON v.id = r.vehicle_id
                    WHERE r.id = ?
                    """,
                    (repair_id,),
                ).fetchone()
                if updated:
                    generate_repair_pdf_72x210mm(updated)
            except Exception:
                pass
            conn.close()
            return redirect(url_for("expense_repair_detail", repair_id=repair_id, mode="view", saved="1"))

    conn.close()
    return render_template(
        "repair_add.html",
        mode=("view" if view_only else "edit"),
        vehicles=vehicles,
        repair=repair,
        today_date=date.today().isoformat(),
        error=error,
        saved=request.args.get("saved") == "1",
        back_url=back_url,
    )


@app.route("/expense/repair/<int:repair_id>/print")
def expense_repair_print(repair_id: int):
    download = (request.args.get("download") or "").strip() in {"1", "true", "yes"}
    paper = (request.args.get("paper") or "customer").strip().lower()
    conn = get_db()
    row = conn.execute(
        """
        SELECT r.*, v.vehicle_name, v.vehicle_number, e.expense_no
        FROM vehicle_repairs r
        JOIN vehicles v ON v.id = r.vehicle_id
        LEFT JOIN expenses e ON e.id = r.expense_id
        WHERE r.id = ?
        """,
        (repair_id,),
    ).fetchone()
    conn.close()
    if not row:
        return redirect(url_for("expense_dashboard", type="repair"))

    out_path = ""
    prefer_slip = paper in {"slip", "72", "72mm"}
    try:
        out_path = generate_repair_pdf_72x210mm(row) if prefer_slip else generate_repair_pdf_80mm(row)
    except Exception:
        app.logger.exception("Repair PDF generation failed (paper=%s, id=%s)", paper, repair_id)
        # Fallback: try the other paper format instead of silently redirecting.
        try:
            out_path = generate_repair_pdf_80mm(row) if prefer_slip else generate_repair_pdf_72x210mm(row)
        except Exception:
            app.logger.exception("Repair PDF fallback generation failed (paper=%s, id=%s)", paper, repair_id)
            return Response(
                "<h3>Repair PDF not generated.</h3><p>Please check the server console logs for the exact error.</p>",
                status=500,
                mimetype="text/html; charset=utf-8",
            )

    try:
        expense_no = str(row["expense_no"] or "").strip()
    except Exception:
        expense_no = ""
    suffix = "slip" if paper in {"slip", "72", "72mm"} else "customer"
    download_name = f"repair_{expense_no or repair_id}_{suffix}.pdf"
    return send_file(
        out_path,
        mimetype="application/pdf",
        as_attachment=download,
        download_name=download_name,
        max_age=0,
    )


@app.route("/expense/repair/<int:repair_id>/delete", methods=["POST"])
def expense_repair_delete(repair_id: int):
    conn = get_db()
    row = conn.execute(
        "SELECT expense_id FROM vehicle_repairs WHERE id = ?",
        (repair_id,),
    ).fetchone()
    conn.execute("DELETE FROM vehicle_repairs WHERE id = ?", (repair_id,))
    if row and row.get("expense_id"):
        conn.execute("DELETE FROM salaries WHERE expense_id = ?", (row["expense_id"],))
        conn.execute("DELETE FROM expenses WHERE id = ?", (row["expense_id"],))
    conn.commit()
    conn.close()
    return redirect(url_for("expense_dashboard", type="repair"))


@app.route("/settings", methods=["GET", "POST"])
def settings():
    current_user = get_current_user_profile() or {}
    if not current_user.get("is_super_admin"):
        abort(403)
    active_tab = request.args.get("tab", "data-settings").strip() or "data-settings"
    status = request.args.get("status", "").strip()
    valid_tabs = {"data-settings", "billing-message", "gst-settings", "printer-settings", "access-control", "staff-roles", "company-settings"}
    if active_tab not in valid_tabs:
        active_tab = "data-settings"

    if request.method == "POST":
        if request.form.get("action") == "date_settings":
            set_setting("worker_delivery_days", request.form.get("worker_days", "0"))
            set_setting("delivery_days", request.form.get("delivery_days", "0"))
            set_setting("order_date_offset_days", request.form.get("order_date_offset_days", "0"))
            set_setting("insurance_alert_days", request.form.get("insurance_alert_days", "0"))
            set_setting("loss_amount", request.form.get("loss_amount", "0"))
            return redirect(url_for("settings", tab="data-settings", status="date_saved"))
        elif request.form.get("action") == "sms_settings":
            set_setting("sms_order_content", request.form.get("sms_order_content", "").strip())
            posted_company_name = request.form.get("company_name")
            if posted_company_name is None:
                company_name = get_setting("company_name", get_setting("branch_name", "")).strip()
            else:
                company_name = posted_company_name.strip()
            address_line1 = request.form.get("address_line1", "").strip()
            address_line2 = request.form.get("address_line2", "").strip()
            address_line3 = request.form.get("address_line3", "").strip()
            address_name = ", ".join([line for line in [address_line1, address_line2, address_line3] if line])
            company_phone = request.form.get("company_phone", "").strip()
            print_logo_path = request.form.get("print_logo_path", "").strip()
            set_setting("company_name", company_name)
            if company_name:
                set_setting("branch_name", company_name)
            set_setting("address_line1", address_line1)
            set_setting("address_line2", address_line2)
            set_setting("address_line3", address_line3)
            set_setting("address_name", address_name)
            set_setting("company_phone", company_phone)
            set_setting("print_logo_path", print_logo_path)
            return redirect(url_for("settings", tab="billing-message", status="sms_saved"))
        elif request.form.get("action") == "gst_settings":
            gst_no = request.form.get("gst_no", "").strip()
            gst_value_mode = request.form.get("gst_value_mode", "percent").strip().lower()
            if gst_value_mode not in {"percent", "amount"}:
                gst_value_mode = "percent"
            default_gst_percent = request.form.get("default_gst_percent", "0").strip()
            default_gst_amount = request.form.get("default_gst_amount", "0").strip()
            gst_enabled = "1" if request.form.get("gst_enabled") == "1" else "0"
            set_setting("gst_no", gst_no)
            set_setting("gst_value_mode", gst_value_mode)
            set_setting("default_gst_percent", default_gst_percent)
            set_setting("default_gst_amount", default_gst_amount)
            set_setting("gst_enabled", gst_enabled)
            return redirect(url_for("settings", tab="gst-settings", status="gst_saved"))
        elif request.form.get("action") == "printer_settings":
            default_printer_name = request.form.get("default_printer_name", "").strip()
            auto_print_on_click = "1" if request.form.get("auto_print_on_click") == "1" else "0"
            set_setting("default_printer_name", default_printer_name)
            set_setting("auto_print_on_click", auto_print_on_click)
            return redirect(url_for("settings", tab="printer-settings", status="printer_saved"))
        elif request.form.get("action") == "business_mode_settings":
            mode = (request.form.get("business_mode") or "sale").strip().lower()
            if mode not in {"sale", "rental"}:
                mode = "sale"
            set_setting("business_mode", mode)
            return redirect(url_for("settings", tab="company-settings", status="business_mode_saved"))
        elif request.form.get("action") == "branch_mode_device_settings":
            mode = (request.form.get("business_mode") or "sale").strip().lower()
            if mode not in {"sale", "rental"}:
                mode = "sale"
            max_mobile_devices = parse_device_limit(request.form.get("max_mobile_devices"), 1)
            max_desktop_devices = parse_device_limit(request.form.get("max_desktop_devices"), 1)
            set_setting("business_mode", mode)
            set_setting("max_mobile_devices", str(max_mobile_devices))
            set_setting("max_desktop_devices", str(max_desktop_devices))
            return redirect(url_for("settings", tab="company-settings", status="branch_mode_device_saved"))
        elif request.form.get("action") == "device_limit_settings":
            max_mobile_devices = parse_device_limit(request.form.get("max_mobile_devices"), 1)
            max_desktop_devices = parse_device_limit(request.form.get("max_desktop_devices"), 1)
            set_setting("max_mobile_devices", str(max_mobile_devices))
            set_setting("max_desktop_devices", str(max_desktop_devices))
            return redirect(url_for("settings", tab="company-settings", status="device_limits_saved"))
        elif request.form.get("action") == "add_staff_role":
            conn = get_db()
            name = request.form.get("role_name", "").strip()
            if name:
                existing = conn.execute(
                    """
                    SELECT id
                    FROM staff_roles
                    WHERE LOWER(LTRIM(RTRIM(name))) = LOWER(LTRIM(RTRIM(?)))
                    """,
                    (name,),
                ).fetchone()
                if not existing:
                    next_sort = conn.execute(
                        "SELECT ISNULL(MAX(sort_order), -1) + 1 AS next_sort FROM staff_roles"
                    ).fetchone()["next_sort"]
                    conn.execute(
                        "INSERT INTO staff_roles (name, sort_order, created_at) VALUES (?, ?, SYSDATETIME())",
                        (name, int(next_sort)),
                    )
                    conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="staff-roles", status="staff_role_saved"))
        elif request.form.get("action") == "delete_staff_role":
            role_id = (request.form.get("role_id") or "").strip()
            if role_id.isdigit():
                conn = get_db()
                conn.execute("DELETE FROM staff_roles WHERE id = ?", (int(role_id),))
                conn.commit()
                conn.close()
            return redirect(url_for("settings", tab="staff-roles", status="staff_role_deleted"))
        elif request.form.get("action") == "save_staff_role_order":
            ordered_ids = request.form.getlist("role_order_ids")
            conn = get_db()
            for idx, raw_id in enumerate(ordered_ids):
                if not str(raw_id).strip().isdigit():
                    continue
                conn.execute(
                    "UPDATE staff_roles SET sort_order = ? WHERE id = ?",
                    (idx, int(raw_id)),
                )
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="staff-roles", status="staff_role_order_saved"))
        elif request.form.get("action") == "create_app_role":
            conn = get_db()
            ensure_default_role_records(conn)
            role_name = (request.form.get("role_name") or "").strip()
            role_key = normalize_user_role(role_name)
            selected_permissions = request.form.getlist("role_permissions")
            if not role_name:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_name_required"))
            if role_key in {ROLE_SUPER_ADMIN}:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_reserved"))
            if not [key for key in selected_permissions if normalize_permission_key(key) in MENU_PERMISSION_KEYS]:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_permissions_required"))
            existing_role = get_role_record(conn, role_key)
            if existing_role:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_exists"))
            next_sort_order = len(list_app_roles(conn)) + 1
            conn.execute(
                """
                INSERT INTO app_roles (role_key, name, is_system, is_super_admin, is_active, sort_order, created_at, updated_at)
                VALUES (?, ?, 0, 0, 1, ?, SYSDATETIME(), SYSDATETIME())
                """,
                (role_key, role_name, next_sort_order),
            )
            save_role_permissions(conn, role_key, selected_permissions)
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="role_created"))
        elif request.form.get("action") == "update_app_role":
            role_key = normalize_user_role(request.form.get("role_key"))
            selected_permissions = request.form.getlist("role_permissions")
            role_name = (request.form.get("role_name") or "").strip()
            is_active = "1" if request.form.get("is_active") == "1" else "0"
            conn = get_db()
            ensure_default_role_records(conn)
            role_row = get_role_record(conn, role_key)
            if not role_row:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_not_found"))
            if role_row.get("is_super_admin"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_super_admin_locked"))
            if not role_name:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_name_required"))
            if not [key for key in selected_permissions if normalize_permission_key(key) in MENU_PERMISSION_KEYS]:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_permissions_required"))
            conn.execute(
                """
                UPDATE app_roles
                SET name = ?, is_active = ?, updated_at = SYSDATETIME()
                WHERE role_key = ?
                """,
                (
                    role_name,
                    "1" if role_row.get("is_system") else is_active,
                    role_key,
                ),
            )
            save_role_permissions(conn, role_key, selected_permissions)
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="role_updated"))
        elif request.form.get("action") == "delete_app_role":
            role_key = normalize_user_role(request.form.get("role_key"))
            conn = get_db()
            ensure_default_role_records(conn)
            role_row = get_role_record(conn, role_key)
            if not role_row:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_not_found"))
            if role_row.get("is_system") or role_row.get("is_super_admin"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_delete_blocked"))
            role_in_use = conn.execute(
                "SELECT TOP 1 id FROM app_users WHERE role = ?",
                (role_key,),
            ).fetchone()
            if role_in_use:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="role_in_use"))
            conn.execute("DELETE FROM role_permissions WHERE role_key = ?", (role_key,))
            conn.execute("DELETE FROM app_roles WHERE role_key = ?", (role_key,))
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="role_deleted"))
        elif request.form.get("action") == "create_app_user":
            username = (request.form.get("username") or "").strip()
            display_name = (request.form.get("display_name") or "").strip()
            role = normalize_user_role(request.form.get("role"))
            password = request.form.get("password") or ""
            confirm_password = request.form.get("confirm_password") or ""
            target_branch_code = normalize_branch_code(request.form.get("branch_code"))
            target_branch = get_branch_record(target_branch_code)

            if not target_branch:
                return redirect(url_for("settings", tab="access-control", status="branch_invalid"))
            if not username:
                return redirect(url_for("settings", tab="access-control", status="user_username_required"))
            if not password:
                return redirect(url_for("settings", tab="access-control", status="user_password_required"))
            if password != confirm_password:
                return redirect(url_for("settings", tab="access-control", status="user_password_mismatch"))

            target_database_name = target_branch["database_name"]
            ensure_database_ready(target_database_name)
            conn = get_db_for_database(target_database_name)
            ensure_default_role_records(conn)
            role_row = get_role_record(conn, role)
            if not role_row or not role_row.get("is_active"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_role_invalid"))
            if role_row.get("is_super_admin"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_super_admin_create_blocked"))
            user_branch_code = None if role_row.get("is_super_admin") else target_branch["code"]
            existing_user = conn.execute(
                "SELECT id FROM app_users WHERE username = ?",
                (username,),
            ).fetchone()
            if existing_user:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_username_exists"))

            cursor = conn.execute(
                """
                INSERT INTO app_users (
                    username,
                    password_hash,
                    role,
                    branch_code,
                    display_name,
                    is_active,
                    created_at,
                    updated_at
                )
                VALUES (?, ?, ?, ?, ?, 1, SYSDATETIME(), SYSDATETIME())
                """,
                (
                    username,
                    generate_password_hash(password),
                    role,
                    user_branch_code,
                    display_name or username,
                ),
            )
            conn.execute("DELETE FROM user_menu_permissions WHERE user_id = ?", (cursor.lastrowid,))
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="user_created"))
        elif request.form.get("action") == "update_app_user":
            user_id_raw = (request.form.get("user_id") or "").strip()
            if not user_id_raw.isdigit():
                return redirect(url_for("settings", tab="access-control", status="user_not_found"))
            user_id = int(user_id_raw)
            username = (request.form.get("username") or "").strip()
            display_name = (request.form.get("display_name") or "").strip()
            role = normalize_user_role(request.form.get("role"))
            password = request.form.get("password") or ""
            confirm_password = request.form.get("confirm_password") or ""
            is_active = "1" if request.form.get("is_active") == "1" else "0"
            target_branch_code = normalize_branch_code(request.form.get("branch_code"))
            target_branch = get_branch_record(target_branch_code)

            if not username:
                return redirect(url_for("settings", tab="access-control", status="user_username_required"))
            if password and password != confirm_password:
                return redirect(url_for("settings", tab="access-control", status="user_password_mismatch"))
            if not target_branch:
                return redirect(url_for("settings", tab="access-control", status="branch_invalid"))

            conn = get_db()
            ensure_default_role_records(conn)
            user_row = conn.execute("SELECT * FROM app_users WHERE id = ?", (user_id,)).fetchone()
            if not user_row:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_not_found"))

            duplicate = conn.execute(
                "SELECT id FROM app_users WHERE username = ? AND id <> ?",
                (username, user_id),
            ).fetchone()
            if duplicate:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_username_exists"))

            existing_role_row = get_role_record(conn, user_row.get("role"))
            is_super_admin = bool((existing_role_row or {}).get("is_super_admin"))
            target_role_row = get_role_record(conn, role)
            if not target_role_row or not target_role_row.get("is_active"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_role_invalid"))
            if not is_super_admin and target_role_row.get("is_super_admin"):
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_super_admin_create_blocked"))
            final_role = ROLE_SUPER_ADMIN if is_super_admin else role
            final_active = "1" if is_super_admin else is_active
            final_branch_code = None if (is_super_admin or target_role_row.get("is_super_admin")) else target_branch["code"]

            if password:
                conn.execute(
                    """
                    UPDATE app_users
                    SET username = ?,
                        display_name = ?,
                        role = ?,
                        branch_code = ?,
                        is_active = ?,
                        password_hash = ?,
                        updated_at = SYSDATETIME()
                    WHERE id = ?
                    """,
                    (
                        username,
                        display_name or username,
                        final_role,
                        final_branch_code,
                        final_active,
                        generate_password_hash(password),
                        user_id,
                    ),
                )
            else:
                conn.execute(
                    """
                    UPDATE app_users
                    SET username = ?,
                        display_name = ?,
                        role = ?,
                        branch_code = ?,
                        is_active = ?,
                        updated_at = SYSDATETIME()
                    WHERE id = ?
                    """,
                    (
                        username,
                        display_name or username,
                        final_role,
                        final_branch_code,
                        final_active,
                        user_id,
                    ),
                )
            conn.execute("DELETE FROM user_menu_permissions WHERE user_id = ?", (user_id,))
            if session.get("user_id") == user_id:
                session["username"] = username
                session["role"] = final_role
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="user_updated"))
        elif request.form.get("action") == "delete_app_user":
            user_id_raw = (request.form.get("user_id") or "").strip()
            if not user_id_raw.isdigit():
                return redirect(url_for("settings", tab="access-control", status="user_not_found"))
            user_id = int(user_id_raw)
            if session.get("user_id") == user_id:
                return redirect(url_for("settings", tab="access-control", status="user_delete_self_blocked"))

            conn = get_db()
            user_row = conn.execute("SELECT * FROM app_users WHERE id = ?", (user_id,)).fetchone()
            if not user_row:
                conn.close()
                return redirect(url_for("settings", tab="access-control", status="user_not_found"))
            if normalize_user_role(user_row["role"]) == ROLE_SUPER_ADMIN:
                super_admin_summary = conn.execute(
                    """
                    SELECT COUNT(*) AS total, MIN(id) AS default_id
                    FROM app_users
                    WHERE LOWER(COALESCE(role, '')) = ?
                    """,
                    (ROLE_SUPER_ADMIN,),
                ).fetchone()
                if int(super_admin_summary["total"] or 0) <= 1:
                    conn.close()
                    return redirect(url_for("settings", tab="access-control", status="user_delete_last_super_admin_blocked"))
                if int(super_admin_summary["default_id"] or 0) == user_id:
                    conn.close()
                    return redirect(url_for("settings", tab="access-control", status="user_delete_default_super_admin_blocked"))

            conn.execute("DELETE FROM app_user_devices WHERE user_id = ?", (user_id,))
            conn.execute("DELETE FROM user_menu_permissions WHERE user_id = ?", (user_id,))
            conn.execute("DELETE FROM app_users WHERE id = ?", (user_id,))
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="access-control", status="user_deleted"))
        elif request.form.get("action") == "change_password":
            user_id = int(session.get("user_id") or 0)
            current_password = request.form.get("current_password") or ""
            new_password = request.form.get("new_password") or ""
            confirm_password = request.form.get("confirm_password") or ""
            if not user_id:
                return redirect(url_for("settings", tab="company-settings", status="password_user_not_found"))
            if not current_password or not new_password or not confirm_password:
                return redirect(url_for("settings", tab="company-settings", status="password_required"))
            if new_password != confirm_password:
                return redirect(url_for("settings", tab="company-settings", status="password_mismatch"))
            if len(new_password) < 4:
                return redirect(url_for("settings", tab="company-settings", status="password_short"))

            conn = get_db()
            user_row = conn.execute("SELECT id, password_hash FROM app_users WHERE id = ?", (user_id,)).fetchone()
            if not user_row:
                conn.close()
                return redirect(url_for("settings", tab="company-settings", status="password_user_not_found"))
            if not check_password_hash(user_row["password_hash"] or "", current_password):
                conn.close()
                return redirect(url_for("settings", tab="company-settings", status="password_current_invalid"))
            conn.execute(
                """
                UPDATE app_users
                SET password_hash = ?, updated_at = SYSDATETIME()
                WHERE id = ?
                """,
                (generate_password_hash(new_password), user_id),
            )
            conn.commit()
            conn.close()
            return redirect(url_for("settings", tab="company-settings", status="password_changed"))
        elif request.form.get("action") == "company_branding":
            brand_name = (request.form.get("brand_company_name") or "").strip()
            if brand_name:
                set_setting("brand_company_name", brand_name)
            else:
                set_setting("brand_company_name", "")

            existing_logo = get_setting("brand_logo_filename", "").strip() or None
            new_logo = save_branding_upload(request.files.get("brand_logo"), fallback=existing_logo)
            set_setting("brand_logo_filename", new_logo or "")
            return redirect(url_for("settings", tab="company-settings", status="brand_saved"))
        elif request.form.get("action") == "add_branch":
            if not (get_current_user_profile() or {}).get("is_super_admin"):
                abort(403)
            ok, message, branch = create_branch(
                request.form.get("branch_name", ""),
                session.get("user_id"),
            )
            status_key = "branch_created" if ok else "branch_create_failed"
            if ok and branch:
                session["branch_switch_message"] = f"{message} You can switch to {branch['name']} any time."
            else:
                session["branch_switch_message"] = message
            return redirect(url_for("settings", tab="company-settings", status=status_key))
        elif request.form.get("action") == "switch_branch":
            if not (get_current_user_profile() or {}).get("is_super_admin"):
                abort(403)
            target_branch = get_branch_record(request.form.get("branch_code"))
            if not target_branch:
                return redirect(url_for("settings", tab="company-settings", status="branch_invalid"))
            session["branch_code"] = target_branch["code"]
            session["branch_name"] = target_branch["name"]
            return redirect(url_for("settings", tab="company-settings", status="branch_switched"))
        elif request.form.get("action") == "delete_branch":
            if not (get_current_user_profile() or {}).get("is_super_admin"):
                abort(403)
            ok, message = delete_branch(request.form.get("branch_code"))
            status_key = "branch_deleted" if ok else "branch_delete_failed"
            session["branch_switch_message"] = message
            return redirect(url_for("settings", tab="company-settings", status=status_key))
        elif request.form.get("action") == "rename_branch":
            if not (get_current_user_profile() or {}).get("is_super_admin"):
                abort(403)
            ok, message, branch = rename_branch(
                request.form.get("branch_code"),
                request.form.get("branch_name", ""),
            )
            status_key = "branch_renamed" if ok else "branch_rename_failed"
            session["branch_switch_message"] = message
            if ok and branch and session.get("branch_code") == branch.get("code"):
                session["branch_name"] = branch.get("name")
                g.current_branch = branch
            return redirect(url_for("settings", tab="company-settings", status=status_key))
        return redirect(url_for("settings", tab=active_tab))

    default_sms_order_content = "Thank you for your order. We appreciate your trust."
    address_lines = get_company_address_lines()
