@app.route("/orders/<int:order_id>/edit", methods=["GET", "POST"])
def order_edit(order_id):
    conn = get_db()

    order = conn.execute(
        "SELECT * FROM orders WHERE id = ?", (order_id,)
    ).fetchone()
    if not order:
        conn.close()
        return redirect(url_for("orders"))

    customer = conn.execute(
        "SELECT * FROM customers WHERE id = ?", (order["customer_id"],)
    ).fetchone()

    order_items = conn.execute(
        "SELECT * FROM order_items WHERE order_id = ?", (order_id,)
    ).fetchall()

    measurements = conn.execute(
        "SELECT * FROM measurements WHERE customer_id = ?", (customer["id"],)
    ).fetchall()

    images = conn.execute(
        "SELECT * FROM order_images WHERE order_id = ?", (order_id,)
    ).fetchall()

    images_by_item = {}
    for img in images:
        images_by_item.setdefault(img["item_type"], []).append(img)

    # ---------------- POST : UPDATE ONLY ----------------
    if request.method == "POST":

        status = request.form.get("order_status")
        due_date = request.form.get("due_date") or None
        advance_amount = request.form.get("advance_amount") or 0
        paid_amount = request.form.get("paid_amount") or 0

        # 1ï¸âƒ£ UPDATE ORDER TABLE
        conn.execute(
            """
            UPDATE orders
            SET status = ?, due_date = ?, advance_amount = ?, paid_amount = ?
            WHERE id = ?
            """,
            (status, due_date, advance_amount, paid_amount, order_id),
        )
        # 2ï¸âƒ£ UPDATE ORDER ITEMS (THIS IS WHAT YOU ASKED)
        item_ids = request.form.getlist("item_id[]")
        item_qtys = request.form.getlist("item_qty[]")

        for iid, qty in zip(item_ids, item_qtys):
            conn.execute(
                "UPDATE order_items SET qty = ? WHERE id = ?",
                (qty, iid)
            )

        conn.commit()
        conn.close()

        return redirect(
            url_for(
                "customer_detail",
                customer_id=customer["id"],
                order_id=order_id
            )
        )

    # ---------------- GET : LOAD EDIT PAGE ----------------
    conn.close()
    return render_template(
        "order_edit.html",
        order=order,
        customer=customer,
        order_items=order_items,
        measurements=measurements,
        images_by_item=images_by_item,
    )
    
@app.route("/expense/add", methods=["GET", "POST"])
def expense_add():
    conn = get_db()
    staffs = conn.execute(
        "SELECT id, tailor_code, name FROM tailors WHERE status = 'Active' ORDER BY name"
    ).fetchall()

    def render_expense_add(
        error: str | None = None,
        expense_no: str | None = None,
        close_connection: bool = False,
        form_data=None,
    ):
        if close_connection:
            conn.close()
        resolved_form_data = form_data if form_data is not None else request.form
        active_kind = "salary" if (resolved_form_data.get("is_salary") == "1") else "expense"
        return render_template(
            "expense_add.html",
            error=error,
            expense_no=expense_no or generate_expense_no(conn),
            staffs=staffs,
            form_data=resolved_form_data,
            active_kind=active_kind,
            back_type=active_kind,
        )

    if request.method == "POST":
        submit_action = (request.form.get("submit_action") or "save").strip().lower()
        name = request.form.get("expense_name", "").strip()
        expense_amount = request.form.get("expense_amount", "").strip()
        salary_amount = request.form.get("salary_amount", "").strip()
        is_salary = request.form.get("is_salary") == "1"
        staff_no = (request.form.get("staff_no") or "").strip()
        expense_no = generate_expense_no(conn)
        staff_row = None

        if is_salary:
            if not staff_no:
                return render_expense_add("Staff is required for salary payment", expense_no, close_connection=True)
            staff_row = conn.execute(
                """
                SELECT TOP 1 tailor_code, name, phone, role, status
                FROM tailors
                WHERE CAST(id AS NVARCHAR(100)) = ? OR tailor_code = ?
                ORDER BY id DESC
                """,
                (staff_no, staff_no),
            ).fetchone()
            if not staff_row:
                return render_expense_add("Selected staff was not found", expense_no, close_connection=True)
            name = f"Salary - {str(staff_row['name'] or staff_no).strip()}"
        elif not name:
            return render_expense_add("Expense name is required", expense_no, close_connection=True)

        if is_salary:
            if not salary_amount:
                return render_expense_add("Salary amount is required", expense_no, close_connection=True)
            final_amount = float(salary_amount)
        else:
            if not expense_amount:
                return render_expense_add("Expense amount is required", expense_no, close_connection=True)
            final_amount = float(expense_amount)

        created_at = now_str()
        expense_id, expense_no = create_expense_record(conn, name, final_amount, created_at)
        cur = conn.cursor()

        # âœ… SALARY INSERT ONLY WHEN CHECKED
        if is_salary:
            shift_no = request.form.get("shift_no") or "-"   # âœ… prevents NOT NULL crash

            cur.execute(
                """
                INSERT INTO salaries (
                    expense_id, staff_no, shift_no, salary_amount, created_at
                )
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    expense_id,
                    staff_no,
                    shift_no,
                    float(salary_amount),
                    created_at,
                ),
            )


        conn.commit()
        conn.close()

        if submit_action == "print":
            pdf_path = generate_expense_pdf_80mm(
                expense_no,
                name,
                final_amount,
                created_at,
                is_salary=is_salary,
                staff_no=staff_no
            )
            return send_file(
                pdf_path,
                mimetype="application/pdf",
                as_attachment=False,
                download_name=f"{expense_no}.pdf",
                max_age=0,
            )

        return redirect(url_for("expense_dashboard", type=("salary" if is_salary else "expense")))

    # expense_no = generate_expense_no(conn)
    # conn.close()
    # return render_template("expense_add.html", expense_no=expense_no)

    expense_no = generate_expense_no(conn)

    conn.close()
    requested_kind = (request.args.get("kind") or "expense").strip().lower()
    if requested_kind not in {"expense", "salary"}:
        requested_kind = "expense"
    prefill_form = {"is_salary": "1"} if requested_kind == "salary" else {}

    return render_template(
        "expense_add.html",
        expense_no=expense_no,
        staffs=staffs,
        form_data=prefill_form,
        active_kind=requested_kind,
        back_type=requested_kind,
    )


@app.route("/expense/<int:expense_id>/edit", methods=["GET", "POST"])
def expense_edit(expense_id: int):
    mode = (request.args.get("mode") or "edit").strip().lower()
    view_only = mode == "view"
    conn = get_db()
    expense = conn.execute(
        "SELECT * FROM expenses WHERE id = ?",
        (expense_id,),
    ).fetchone()
    salary = conn.execute(
        "SELECT * FROM salaries WHERE expense_id = ?",
        (expense_id,),
    ).fetchone()
    staffs = conn.execute(
        "SELECT id, tailor_code, name FROM tailors WHERE status = 'Active' ORDER BY name"
    ).fetchall()
    if not expense:
        conn.close()
        return redirect(url_for("expense_dashboard"))

    if request.method == "POST":
        name = request.form.get("expense_name", "").strip()
        amount = request.form.get("expense_amount", "").strip()
        selected_staff_id = (request.form.get("staff_no") or "").strip()
        if salary and selected_staff_id:
            staff_row = conn.execute(
                "SELECT TOP 1 name FROM tailors WHERE CAST(id AS NVARCHAR(100)) = ? ORDER BY id DESC",
                (selected_staff_id,),
            ).fetchone()
            if staff_row and staff_row["name"]:
                name = str(staff_row["name"]).strip()
        if not name or not amount:
            conn.close()
            return render_template(
                "expense_edit.html",
                expense=expense,
                salary=salary,
                staffs=staffs,
                view_only=False,
                error="Name and amount are required.",
            )
        conn.execute(
            "UPDATE expenses SET expense_name = ?, amount = ? WHERE id = ?",
            (name, float(amount), expense_id),
        )
        if salary:
            staff_no = request.form.get("staff_no", "").strip() or "-"
            shift_no = salary["shift_no"] if salary["shift_no"] else "-"
            conn.execute(
                """
                UPDATE salaries
                SET staff_no = ?, shift_no = ?, salary_amount = ?
                WHERE expense_id = ?
                """,
                (staff_no, shift_no, float(amount), expense_id),
            )
        conn.commit()
        refreshed_expense = conn.execute(
            "SELECT * FROM expenses WHERE id = ?",
            (expense_id,),
        ).fetchone()
        refreshed_salary = conn.execute(
            "SELECT * FROM salaries WHERE expense_id = ?",
            (expense_id,),
        ).fetchone()
        conn.close()
        submit_action = (request.form.get("submit_action") or "save").strip().lower()
        if submit_action == "print" and refreshed_expense:
            pdf_path = generate_expense_pdf_80mm(
                str(refreshed_expense["expense_no"] or ""),
                str(refreshed_expense["expense_name"] or ""),
                float(refreshed_expense["amount"] or 0),
                str(refreshed_expense["created_at"] or now_str()),
                is_salary=bool(refreshed_salary),
                staff_no=str(refreshed_salary["staff_no"] or "") if refreshed_salary else None,
            )
            return send_file(
                pdf_path,
                mimetype="application/pdf",
                as_attachment=False,
                download_name=f"{refreshed_expense['expense_no']}.pdf",
                max_age=0,
            )
        return redirect(url_for("expense_edit", expense_id=expense_id, mode="view"))

    conn.close()
    return render_template(
        "expense_edit.html",
        expense=expense,
        salary=salary,
        staffs=staffs,
        view_only=view_only,
    )


