@app.route("/categories", methods=["GET", "POST"])
def categories():
    if request.method == "POST":
        action = request.form.get("action", "")
        conn = get_db()
        cur = conn.cursor()

        if action == "add_category":
            name = request.form.get("category_name", "").strip()
            measurement_type = request.form.get("measurement_type", "Shirt").strip()
            if name:
                existing = cur.execute(
                    """
                    SELECT id
                    FROM categories
                    WHERE LOWER(LTRIM(RTRIM(name))) = LOWER(LTRIM(RTRIM(?)))
                    """,
                    (name,),
                ).fetchone()
                if not existing:
                    try:
                        next_sort = cur.execute(
                            "SELECT ISNULL(MAX(sort_order), -1) + 1 AS next_sort FROM categories"
                        ).fetchone()["next_sort"]
                        cur.execute(
                            "INSERT INTO categories (name, measurement_type, sort_order) VALUES (?, ?, ?)",
                            (name, measurement_type, int(next_sort)),
                        )
                    except pyodbc.IntegrityError:
                        # Another request inserted the same category concurrently.
                        pass

        elif action == "delete_category":
            category_id = request.form.get("category_id")
            if category_id:
                cur.execute(
                    "DELETE FROM measurement_labels WHERE category_id = ?",
                    (category_id,),
                )
                cur.execute(
                    "DELETE FROM subcategories WHERE category_id = ?",
                    (category_id,),
                )
                cur.execute("DELETE FROM categories WHERE id = ?", (category_id,))

        elif action == "add_subcategory":
            category_id = request.form.get("subcategory_category_id")
            name = request.form.get("subcategory_name", "").strip()
            if category_id and name:
                existing = cur.execute(
                    """
                    SELECT id
                    FROM subcategories
                    WHERE category_id = ?
                      AND LOWER(LTRIM(RTRIM(name))) = LOWER(LTRIM(RTRIM(?)))
                    """,
                    (category_id, name),
                ).fetchone()
                if not existing:
                    try:
                        cur.execute(
                            "INSERT INTO subcategories (category_id, name) VALUES (?, ?)",
                            (category_id, name),
                        )
                    except pyodbc.IntegrityError:
                        # Duplicate-race/case-space variant, ignore.
                        pass

        elif action == "delete_subcategory":
            subcategory_id = request.form.get("subcategory_id")
            if subcategory_id:
                cur.execute(
                    "DELETE FROM measurement_labels WHERE subcategory_id = ?",
                    (subcategory_id,),
                )
                cur.execute("DELETE FROM subcategories WHERE id = ?", (subcategory_id,))

        elif action == "add_requirement":
            name = request.form.get("requirement_name", "").strip()
            icon = request.files.get("requirement_icon")
            if name and icon and icon.filename:
                filename = f"{uuid.uuid4().hex}_{secure_filename(icon.filename)}"
                filepath = os.path.join(app.config["REQ_ICON_FOLDER"], filename)
                icon.save(filepath)
                next_sort = cur.execute(
                    "SELECT ISNULL(MAX(sort_order), -1) + 1 AS next_sort FROM requirement_icons"
                ).fetchone()["next_sort"]
                cur.execute(
                    "INSERT INTO requirement_icons (name, filename, sort_order) VALUES (?, ?, ?)",
                    (name, filename, int(next_sort)),
                )

        elif action == "delete_requirement":
            req_id = request.form.get("requirement_id")
            if req_id:
                row = cur.execute(
                    "SELECT filename FROM requirement_icons WHERE id = ?",
                    (req_id,),
                ).fetchone()
                if row:
                    try:
                        os.remove(os.path.join(app.config["REQ_ICON_FOLDER"], row["filename"]))
                    except OSError:
                        pass
                cur.execute("DELETE FROM requirement_icons WHERE id = ?", (req_id,))

        elif action == "add_uom":
            name = request.form.get("uom_name", "").strip()
            if name:
                existing = cur.execute("SELECT id FROM uoms WHERE name = ?", (name,)).fetchone()
                if not existing:
                    cur.execute("INSERT INTO uoms (name) VALUES (?)", (name,))

        elif action == "delete_uom":
            uom_id = request.form.get("uom_id")
            if uom_id:
                cur.execute("DELETE FROM uoms WHERE id = ?", (uom_id,))

        elif action == "add_staff_role":
            name = request.form.get("role_name", "").strip()
            if name:
                existing = cur.execute(
                    """
                    SELECT id
                    FROM staff_roles
                    WHERE LOWER(LTRIM(RTRIM(name))) = LOWER(LTRIM(RTRIM(?)))
                    """,
                    (name,),
                ).fetchone()
                if not existing:
                    try:
                        next_sort = cur.execute(
                            "SELECT ISNULL(MAX(sort_order), -1) + 1 AS next_sort FROM staff_roles"
                        ).fetchone()["next_sort"]
                        cur.execute(
                            "INSERT INTO staff_roles (name, sort_order, created_at) VALUES (?, ?, SYSDATETIME())",
                            (name, int(next_sort)),
                        )
                    except pyodbc.IntegrityError:
                        pass

        elif action == "delete_staff_role":
            role_id = request.form.get("role_id")
            if role_id and str(role_id).strip().isdigit():
                cur.execute("DELETE FROM staff_roles WHERE id = ?", (int(role_id),))

        elif action == "save_fields":
            subcategory_id = request.form.get("fields_subcategory_id")
            field_keys = request.form.getlist("field_key")
            field_labels = request.form.getlist("field_label")
            if subcategory_id:
                cur.execute(
                    "DELETE FROM measurement_fields WHERE subcategory_id = ?",
                    (subcategory_id,),
                )
                used = set()
                for idx, (key, label) in enumerate(
                    zip(field_keys, field_labels, strict=False)
                ):
                    key = (key or "").strip()
                    label = (label or "").strip()
                    if label.lower() == "[object object]":
                        continue
                    if not label:
                        continue
                    base = "".join(ch for ch in (key or label).lower() if ch.isalnum())
                    base = base[:12] if base else "field"
                    key = base
                    counter = 2
                    while key.lower() in used:
                        key = f"{base}{counter}"
                        counter += 1
                    used.add(key.lower())
                    cur.execute(
                        """
                        INSERT INTO measurement_fields (subcategory_id, field_key, field_label, sort_order)
                        VALUES (?, ?, ?, ?)
                        """,
                        (subcategory_id, key, label, idx),
                    )

        elif action == "save_category_order":
            ordered_ids = request.form.getlist("category_order_ids")
            for idx, raw_id in enumerate(ordered_ids):
                if not str(raw_id).strip().isdigit():
                    continue
                cur.execute(
                    "UPDATE categories SET sort_order = ? WHERE id = ?",
                    (idx, int(raw_id)),
                )

        elif action == "save_requirement_order":
            ordered_ids = request.form.getlist("requirement_order_ids")
            for idx, raw_id in enumerate(ordered_ids):
                if not str(raw_id).strip().isdigit():
                    continue
                cur.execute(
                    "UPDATE requirement_icons SET sort_order = ? WHERE id = ?",
                    (idx, int(raw_id)),
                )

        elif action == "save_staff_role_order":
            ordered_ids = request.form.getlist("role_order_ids")
            for idx, raw_id in enumerate(ordered_ids):
                if not str(raw_id).strip().isdigit():
                    continue
                cur.execute(
                    "UPDATE staff_roles SET sort_order = ? WHERE id = ?",
                    (idx, int(raw_id)),
                )

        active_tab = request.form.get("active_tab", "").strip()
        if active_tab in {"kits-roles", "icons", "categories", "subcategories", "fields"}:
            active_tab = "repair-kits"
        if active_tab not in {"repair-kits", "staff-roles"}:
            active_tab = "repair-kits"
        conn.commit()
        conn.close()
        if active_tab:
            return redirect(url_for("categories", tab=active_tab))
        return redirect(url_for("categories"))

    conn = get_db()
    requirement_icons = conn.execute(
        "SELECT * FROM requirement_icons ORDER BY sort_order, name"
    ).fetchall()
    staff_roles = conn.execute(
        "SELECT * FROM staff_roles ORDER BY sort_order, name"
    ).fetchall()
    conn.close()

    active_tab = (request.args.get("tab") or "repair-kits").strip()
    if active_tab in {"kits-roles", "icons", "categories", "subcategories", "fields"}:
        active_tab = "repair-kits"
    if active_tab not in {"repair-kits", "staff-roles"}:
        active_tab = "repair-kits"

    return render_template(
        "categories.html",
        requirement_icons=requirement_icons,
        staff_roles=staff_roles,
        active_tab=active_tab,
    )

@app.route("/api/staff/<staff_ref>")
def get_staff_name(staff_ref):
    conn = get_db()
    row = conn.execute(
        """
        SELECT TOP 1 name, phone, role, status
        FROM tailors
        WHERE CAST(id AS NVARCHAR(100)) = ? OR tailor_code = ?
        ORDER BY id DESC
        """,
        (staff_ref, staff_ref)
    ).fetchone()
    conn.close()

    if not row:
        return {"name": "", "phone": "", "role": "", "status": ""}
    return {
        "name": row["name"] or "",
        "phone": row["phone"] or "",
        "role": row["role"] or "",
        "status": row["status"] or "",
    }



@app.route("/orders/<int:order_id>", methods=["GET", "POST"])
def order_detail(order_id: int):
    conn = get_db()
    source = (request.args.get("source") or "").strip().lower()
    if source not in {"orders", "customers"}:
        source = ""
    if request.method == "POST":
        status = request.form.get("status", "In-Progress")
        assigned_tailor = request.form.get("assigned_tailor", "").strip() or None
        due_date = request.form.get("due_date", "").strip() or None
        notes = request.form.get("notes", "").strip() or None
        advance_amount = request.form.get("advance_amount", "").strip()
        total_amount = request.form.get("total_amount", "").strip()
        paid_flag = request.form.get("paid") == "1"
        picked_up_flag = request.form.get("picked_up") == "1"

        current = conn.execute(
            "SELECT status, paid_at, delivered_at, completed_at, picked_up_at FROM orders WHERE id = ?",
            (order_id,),
        ).fetchone()
        if not current:
            conn.close()
            return redirect(url_for("orders"))
        previous_status = (current["status"] or "").strip() if current else ""
        now = now_str()
        paid_at = current["paid_at"]
        completed_at = current["completed_at"]
        picked_up_at = current["picked_up_at"]
        if status == "Completed" and not completed_at:
            completed_at = now
        if status == "Delivered" and not completed_at:
            completed_at = now
        if paid_flag and not paid_at:
            paid_at = now
        if picked_up_flag and not picked_up_at:
            picked_up_at = now

        conn.execute(
            """
            UPDATE orders
            SET status = ?, assigned_tailor = ?, due_date = ?, notes = ?,
                advance_amount = ?, total_amount = ?, paid_at = ?,
                completed_at = ?, picked_up_at = ?
            WHERE id = ?
            """,
            (
                status,
                assigned_tailor,
                due_date,
                notes,
                float(advance_amount) if advance_amount else None,
                float(total_amount) if total_amount else None,
                paid_at,
                completed_at,
                picked_up_at,
                order_id,
            ),
        )
        sync_completed_notification(conn, order_id, previous_status, status, completed_at)
        conn.commit()
        row = conn.execute(
            "SELECT customer_id FROM orders WHERE id = ?",
            (order_id,),
        ).fetchone()
        if row:
            customer_id = row["customer_id"]
            conn.close()
            return redirect(url_for("customer_detail", customer_id=customer_id, order_id=order_id, source=source))

    order = conn.execute(
        """
        SELECT orders.*, customers.name, customers.phone, customers.notes AS customer_notes
        FROM orders
        JOIN customers ON customers.id = orders.customer_id
        WHERE orders.id = ?
        """,
        (order_id,),
    ).fetchone()
    if not order:
        conn.close()
        return redirect(url_for("orders"))
    if str(order["order_type"] or "").strip().lower() == "vehicle sale":
        sale_row = conn.execute(
    """
    SELECT vso.*, v.photo_filename, v.vehicle_image_filenames, v.rc_book_filename,
           v.insurance_document_filename, v.puc_certificate_filename, v.purchase_id_proof_filename,
           v.sale_gst_enabled, v.sale_gst_mode, v.sale_gst_value,
           v.purchase_mode, v.purchase_customer_name, v.purchase_customer_address,
           v.purchase_customer_phone, v.purchase_customer_id, v.purchase_id_proof_ref,
           v.purchase_reference
    FROM vehicle_sale_orders vso
    LEFT JOIN vehicles v ON v.id = vso.vehicle_id
    WHERE vso.order_id = ?
    """,
    (order_id,),
).fetchone()
        repairs = []
        if sale_row and sale_row["vehicle_id"]:
            repairs = conn.execute(
                """
                SELECT repair_date, description, cost, payment_mode, created_at
                FROM vehicle_repairs
                WHERE vehicle_id = ?
                ORDER BY COALESCE(repair_date, CAST(created_at AS DATE)) DESC, created_at DESC
                """,
                (sale_row["vehicle_id"],),
            ).fetchall()
        conn.close()
        return render_template(
            "vehicle_sale_detail_gallery.html",
            order=order,
            sale=(build_gallery_vehicle_payload(dict(sale_row)) if sale_row else None),
            repairs=repairs,
        )
    if order and request.method == "GET":
        customer_id = order["customer_id"]
        conn.close()
        return redirect(url_for("customer_detail", customer_id=customer_id, order_id=order_id, source=source))
    requirement_names = extract_requirements(order["notes"] if order else None)
    requirement_icons = []
    if requirement_names:
        placeholders = ",".join("?" for _ in requirement_names)
        requirement_icons = conn.execute(
            f"SELECT name, filename FROM requirement_icons WHERE name IN ({placeholders})",
            requirement_names,
        ).fetchall()
    items = conn.execute(
        "SELECT * FROM order_items WHERE order_id = ?", (order_id,)
    ).fetchall()
    material_items = conn.execute(
        """
        SELECT inventory.name AS item_name,
               order_material_items.qty,
               uoms.name AS uom_name,
               order_material_items.unit_price,
               order_material_items.line_total
        FROM order_material_items
        JOIN inventory ON inventory.id = order_material_items.inventory_id
        LEFT JOIN uoms ON uoms.id = order_material_items.uom_id
        WHERE order_material_items.order_id = ?
        """,
        (order_id,),
    ).fetchall()
    measurements = fetch_order_measurements(
        conn,
        int(order["customer_id"]),
        int(order["id"]),
        order["created_at"],
    )
    tailors = conn.execute("SELECT * FROM tailors ORDER BY team, name").fetchall()
    images = conn.execute(
        "SELECT filename, label, item_type FROM order_images WHERE order_id = ?",
        (order_id,),
    ).fetchall()
    images_by_item = {}
    customer_images = []
    for img in images:
        key = img["item_type"] or "Uncategorized"
        key_norm = (key or "").strip().lower()
        label_norm = str(img["label"] or "").strip().lower()
        if key_norm == "customer" or label_norm == "customer":
            customer_images.append(img)
            continue
        images_by_item.setdefault(key, []).append(img)
    if not customer_images:
        fallback_customer_photo = conn.execute(
            """
            SELECT oi.filename, oi.label, oi.item_type
            FROM order_images oi
            JOIN orders o ON o.id = oi.order_id
            WHERE o.customer_id = ?
              AND (
                LOWER(LTRIM(RTRIM(COALESCE(oi.item_type, '')))) = 'customer'
                OR LOWER(LTRIM(RTRIM(COALESCE(oi.label, '')))) = 'customer'
              )
            ORDER BY oi.id DESC
            LIMIT 1
            """,
            (int(order["customer_id"]),),
        ).fetchall()
        if fallback_customer_photo:
            customer_images = list(fallback_customer_photo)
    conn.close()

    worker_delivery_date = None
    if order and order["notes"]:
        for line in order["notes"].splitlines():
            if line.lower().startswith("worker delivery date:"):
                worker_delivery_date = date_only(line.split(":", 1)[1].strip())

    total_amount = float(order["total_amount"] or 0)
    advance_amount = float(order["advance_amount"] or 0)
    paid_amount = float(order["paid_amount"] or 0)
    gst_amount = float(order["gst_amount"] or 0)
    gst_percent = float(order["gst_percent"] or 0)
    taxable_amount = float(order["taxable_amount"] or max(total_amount - gst_amount, 0))
    stored_discount = float(order["discount_amount"] or 0) if "discount_amount" in order.keys() else 0.0
    cgst_amount = float(order["cgst_amount"] or (gst_amount / 2.0 if gst_amount > 0 else 0))
    sgst_amount = float(order["sgst_amount"] or (gst_amount / 2.0 if gst_amount > 0 else 0))
    cgst_percent = float(order["cgst_percent"] or (gst_percent / 2.0 if gst_percent > 0 else 0))
    sgst_percent = float(order["sgst_percent"] or (gst_percent / 2.0 if gst_percent > 0 else 0))
    discount_amount = max(stored_discount, 0)
    sub_total = max(taxable_amount + discount_amount, 0)
    due_amount = max(total_amount - advance_amount - paid_amount, 0)

    return render_template(
        "order_detail.html",
        order=order,
        items=items,
        material_items=material_items,
        tailors=tailors,
        images=images,
        images_by_item=images_by_item,
        customer_images=customer_images,
        worker_delivery_date=worker_delivery_date,
        sub_total=sub_total,
        discount_amount=discount_amount,
        gst_amount=gst_amount,
        cgst_amount=cgst_amount,
        sgst_amount=sgst_amount,
        gst_percent=gst_percent,
        cgst_percent=cgst_percent,
        sgst_percent=sgst_percent,
        paid_amount=paid_amount,
        due_amount=due_amount,
        measurements=measurements,
        requirement_icons=requirement_icons,
    )


def _docx_tamil_font_name() -> str:
    candidates = [
        ("Nirmala UI", r"C:\Windows\Fonts\Nirmala.ttf"),
        ("Latha", r"C:\Windows\Fonts\Latha.ttf"),
        ("Vijaya", r"C:\Windows\Fonts\Vijaya.ttf"),
        ("Noto Sans Tamil", os.path.join(FONTS_FOLDER, "NotoSansTamil-Regular.ttf")),
    ]
    for font_name, font_path in candidates:
        if os.path.exists(font_path):
            return font_name
    return "Nirmala UI"


def _set_docx_run_font(run, font_name: str, size_pt: float | None = None, bold: bool | None = None) -> None:
    if run is None:
        return
    run.font.name = font_name
    if bold is not None:
        run.bold = bold
    if size_pt is not None and Pt is not None:
        run.font.size = Pt(size_pt)
    if qn is not None:
        r_pr = run._element.get_or_add_rPr()
        r_fonts = r_pr.get_or_add_rFonts()
        r_fonts.set(qn("w:ascii"), font_name)
        r_fonts.set(qn("w:hAnsi"), font_name)
        r_fonts.set(qn("w:eastAsia"), font_name)
        r_fonts.set(qn("w:cs"), font_name)


def _fmt_measure_value_for_docx(value) -> str:
    return str(fmt_measure(value) or "").strip()


def _parse_measurement_note_pairs_for_docx(notes_text: str | None) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    ignore_labels = {
        "label",
        "requirements",
        "requirement",
        "payment method",
        "worker delivery date",
        "completed date",
        "delivery date",
        "notes",
        "note",
    }
    for raw_line in str(notes_text or "").splitlines():
        clean = raw_line.strip()
        if not clean or ":" not in clean:
            continue
        left, right = clean.split(":", 1)
        label = left.strip()
        value = right.strip()
        if not label or not value:
            continue
        if label.lower() in ignore_labels:
            continue
        pairs.append((label, value))
    return pairs


def _word_order_no(order) -> str:
    for key in ("order_no", "invoice_no"):
        if hasattr(order, "keys") and key in order.keys():
            value = str(order[key] or "").strip()
            if value:
                return value
    try:
        return f"INV{int(order['id']):03d}"
    except Exception:
        return str(order["id"])


def _word_delivery_date(order) -> str:
    if hasattr(order, "keys") and "delivery_date" in order.keys():
        text = str(order["delivery_date"] or "").strip()
        if text:
            return date_only(text)
    notes_text = str(order["notes"] if (hasattr(order, "keys") and "notes" in order.keys()) else "")
    for raw_line in notes_text.splitlines():
        line = raw_line.strip()
        low = line.lower()
        if low.startswith("worker delivery date:") or low.startswith("delivery date:"):
            return date_only(line.split(":", 1)[1].strip())
    return "-"


def _word_date_ddmmyyyy(value) -> str:
    iso = date_only(value)
    if not iso or iso == "-":
        return "-"
    match = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", iso)
    if match:
        return f"{match.group(3)}-{match.group(2)}-{match.group(1)}"
    return iso


def _word_items_text_and_qty(order_items) -> tuple[str, int]:
    item_names: list[str] = []
    total_qty = 0
    for item in order_items or []:
        name = str(item["item_type"] if "item_type" in item.keys() else "Item").strip() or "Item"
        item_names.append(name)
        qty_text = str(item["qty"] if "qty" in item.keys() else "1").strip() or "1"
        try:
            total_qty += max(0, int(float(qty_text)))
        except Exception:
            total_qty += 1
    if total_qty <= 0:
        total_qty = 1
    return " - ".join(item_names) if item_names else "-", total_qty


def _word_measure_pairs(row) -> list[tuple[str, str]]:
    value_keys = [
        "neck", "chest", "waist", "hip", "shoulder",
        "sleeve", "length", "cuff",
        "inseam", "outseam", "thigh",
        "knee", "bottom",
    ]
    measurement_label_map = {
        "neck": "Neck",
        "chest": "Chest",
        "waist": "Waist",
        "hip": "Hip",
        "shoulder": "Shoulder",
        "sleeve": "Sleeve",
        "length": "Length",
        "cuff": "Cuff",
        "inseam": "Inseam",
        "outseam": "Outseam",
        "thigh": "Thigh",
        "knee": "Knee",
        "bottom": "Bottom",
    }
    pairs: list[tuple[str, str]] = []
    notes_text = row["notes"] if "notes" in row.keys() else None
    note_pairs = _parse_measurement_note_pairs_for_docx(notes_text)
    if note_pairs:
        for label, value in note_pairs:
            clean_value = _fmt_measure_value_for_docx(value)
            if clean_value:
                pairs.append((str(label).strip(), clean_value))
        return pairs
    for key in value_keys:
        if key not in row.keys():
            continue
        val_text = _fmt_measure_value_for_docx(row[key])
        if val_text:
            pairs.append((measurement_label_map.get(key, key.title()), val_text))
    return pairs


def _word_requirements(measurements) -> str:
    for row in measurements or []:
        notes_text = str(row["notes"] if "notes" in row.keys() else "")
        for raw_line in notes_text.splitlines():
            line = raw_line.strip()
            if line.lower().startswith("requirements:"):
                value = line.split(":", 1)[1].strip()
                if value:
                    return value
    return ""


def _word_tailor_note_lines(notes_text: str | None, measurement_labels: set[str] | None = None) -> list[str]:
    lines: list[str] = []
    label_set = {str(label).strip().lower() for label in (measurement_labels or set()) if str(label).strip()}
    for raw_line in str(notes_text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        low = line.lower()
        if low.startswith("label:"):
            continue
        if low.startswith("requirements:") or low.startswith("requirement:"):
            continue
        if low.startswith("payment method:"):
            continue
        if low.startswith("worker delivery date:"):
            continue
        if low.startswith("completed date:"):
            continue
        if low.startswith("delivery date:"):
            continue
        if low.startswith("qty:"):
            continue
        if ":" in line:
            key = line.split(":", 1)[0].strip().lower()
            if key in label_set:
                continue
        lines.append(line)
    return lines


def _word_notes(order, measurements, order_items) -> str:
    merged: list[str] = []
    seen: set[str] = set()

    def add_lines(text_value: str | None, labels: set[str] | None = None) -> None:
        for line in _word_tailor_note_lines(text_value, labels):
            key = line.strip().lower()
            if not key or key in seen:
                continue
            seen.add(key)
            merged.append(line.strip())

    if hasattr(order, "keys") and "notes" in order.keys():
        add_lines(order["notes"])

    for row in measurements or []:
        notes_text = row["notes"] if "notes" in row.keys() else None
        measure_labels = {
            str(label).strip().lower()
            for label, _ in _parse_measurement_note_pairs_for_docx(notes_text)
            if str(label).strip()
        }
        add_lines(notes_text, measure_labels)

    for item in order_items or []:
        if hasattr(item, "keys") and "notes" in item.keys():
            add_lines(item["notes"])

    return " | ".join(merged)


def _chunk_pairs(pairs: list[tuple[str, str]], size: int = 9) -> list[list[tuple[str, str]]]:
    if size <= 0:
        size = 9
    return [pairs[i:i + size] for i in range(0, len(pairs), size)]


def _estimate_thermal_length_mm(order, measurements, order_items, notes_measurements=None) -> float:
    # 72mm roll width with dynamic length, so each order stays on a single page.
    base_mm = 92.0
    line_mm = 6.2
    lines = 0.0
    lines += 4.0  # header + rule + items + measurements title
    lines += max(1.0, float(len(order_items or [])) * 0.2)
    for row in measurements or []:
        lines += 1.2  # kind line
        pairs = _word_measure_pairs(row)
        pair_count = len(pairs)
        # Thermal layout prints all measurement pairs in one compact row.
        lines += 2.2 if pair_count > 0 else 1.2
        if pair_count > 0:
            # Increase slip length for dense/long measurement labels so print stays clean.
            longest_label = max(len(str(label or "").strip()) for label, _ in pairs)
            total_label_chars = sum(len(str(label or "").strip()) for label, _ in pairs)
            lines += pair_count * 0.12
            if longest_label > 10:
                lines += (longest_label - 10) / 10.0
            if total_label_chars > 70:
                lines += (total_label_chars - 70) / 35.0
    source_for_footer = notes_measurements if notes_measurements is not None else measurements
    req = _word_requirements(source_for_footer)
    if req:
        lines += 1.1
    notes_text = _word_notes(order, source_for_footer, order_items)
    if notes_text:
        note_parts = [part.strip() for part in notes_text.split("|") if part.strip()]
        lines += 1.1 + (max(0, len(note_parts) - 1) * 0.8)
    # Keep extra trailing paper so long Tamil labels/values don't overflow into next page.
    paper_buffer_mm = 50.0
    total = base_mm + (lines * line_mm) + paper_buffer_mm
    return max(220.0, min(900.0, total))


def _build_order_word_html_tailor(order, measurements, order_items, paper: str = "a4") -> str:
    is_thermal = str(paper or "").strip().lower() == "thermal"
    tamil_font = _docx_tamil_font_name()
    invoice_no = _word_order_no(order)
    created_at_text = order["created_at"] if "created_at" in order.keys() else ""
    order_date = _word_date_ddmmyyyy(created_at_text)
    delivery_date = _word_date_ddmmyyyy(_word_delivery_date(order))
    items_text, qty_total = _word_items_text_and_qty(order_items)
    req_text = _word_requirements(measurements)
    notes_text = _word_notes(order, measurements, order_items)

    def _pick_item_notes_for_row(row_obj) -> list:
        if not row_obj:
            return list(order_items or [])
        row_kind = str(row_obj["kind"] if "kind" in row_obj.keys() else "").strip().lower()
        if not row_kind:
            return list(order_items or [])
        matched: list = []
        for item in order_items or []:
            item_kind = str(item["item_type"] if "item_type" in item.keys() else "").strip().lower()
            if not item_kind:
                continue
            if (item_kind in row_kind) or (row_kind in item_kind):
                matched.append(item)
        return matched if matched else list(order_items or [])

    if is_thermal:
        # Ctrl+P thermal print must fit a fixed 72.1mm x 210mm sheet.
        thermal_len_mm = 210.0
    elif measurements:
        thermal_len_mm = max(
            _estimate_thermal_length_mm(
                order,
                [row],
                order_items,
                notes_measurements=measurements,
            )
            for row in measurements
        )
    else:
        thermal_len_mm = 297.0
    page_w = "72.1mm" if is_thermal else "297mm"
    page_h = "210mm" if is_thermal else "210mm"
    page_margin = "0mm" if is_thermal else "2mm"
    body_font_size = "11pt" if is_thermal else "12pt"
    label_font_size = "9pt" if is_thermal else "9pt"
    value_font_size = "10.5pt" if is_thermal else "12pt"

    parts: list[str] = []
    parts.append("<html><head><meta charset='utf-8'><style>")
    parts.append(f"@page Section1{{size:{page_w} {page_h};margin:{page_margin};mso-page-orientation:portrait;}}")
    parts.append("div.Section1{page:Section1;}")
    parts.append(f"body{{font-family:'{html.escape(tamil_font)}','Nirmala UI','Latha','Vijaya',sans-serif;font-size:{body_font_size};margin:0;letter-spacing:0;}}")
    parts.append(".head{width:calc(100% - 8px);max-width:calc(100% - 8px);border-collapse:separate;table-layout:auto;border-spacing:3px 0;margin:0 4px 1mm 4px;box-sizing:border-box;}")
    parts.append(".head td{padding:0 1px;vertical-align:middle;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}")
    parts.append(".head td:nth-child(2){text-align:center;}")
    parts.append(".head td:nth-child(3){text-align:right;padding-right:8px;}")
    parts.append(".rule{height:0;border-top:1px dashed #1f5f9c;margin:0.4mm 4px 0.8mm 4px;box-sizing:border-box;}")
    parts.append(".row2{width:calc(100% - 8px);max-width:calc(100% - 8px);border-collapse:separate;table-layout:auto;border-spacing:3px 0;margin:0 4px 0.4mm 4px;box-sizing:border-box;}")
    parts.append(".row2 td{padding:0 1px;vertical-align:middle;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}")
    parts.append(".row2 td:first-child{text-align:left;}")
    parts.append(".row2 td:last-child{text-align:right;padding-right:8px;}")
    parts.append(".kind{margin:0 0 0.5mm 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}")
    parts.append(".mgrid{width:100%;border-collapse:collapse;table-layout:fixed;margin:0 0 1.2mm 0;}")
    parts.append(f".mgrid .lbl{{font-size:{label_font_size};text-align:center;padding:0 0.4mm;white-space:nowrap;}}")
    parts.append(f".mgrid .val{{font-size:{value_font_size};text-align:center;padding:0 0.4mm;white-space:nowrap;}}")
    parts.append(".mgrid-thermal{width:calc(100% - 8px);max-width:calc(100% - 8px);border-collapse:separate;table-layout:auto;border-spacing:3px 0;margin:0.4mm 4px 1.0mm 4px;box-sizing:border-box;}")
    parts.append(".mgrid-thermal td{width:1%;padding:0 2px;vertical-align:top;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}")
    parts.append(f".mgrid-thermal .name{{display:block;font-size:{label_font_size};font-weight:700;line-height:1.12;white-space:nowrap;word-break:normal;overflow-wrap:normal;overflow:hidden;text-overflow:ellipsis;}}")
    parts.append(f".mgrid-thermal .value{{display:block;font-size:{value_font_size};font-weight:700;line-height:1.22;margin-top:4px;white-space:normal;overflow:hidden;text-overflow:ellipsis;}}")
    parts.append(".section{margin:1.2mm 0 0.2mm 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}")
    parts.append(".section-wrap{margin:1.2mm 0 0.2mm 0;white-space:normal;overflow:visible;word-break:break-word;}")
    parts.append("p{margin:0;line-height:1.12;}")
    parts.append("@media print{html,body{margin:0!important;padding:0!important;} .Section1{margin:0!important;padding:0!important;}}")
    if is_thermal:
        # For browser Ctrl+P, rotate thermal slip content so print output is vertical.
        parts.append(
            "@media print{"
            "@page{margin:0!important;}"
            "@page Section1{size:"
            "72.1mm 210mm"
            ";margin:0;mso-page-orientation:portrait;}"
            "html,body{margin:0!important;padding:0!important;width:72.1mm;min-height:210mm;overflow:visible;}"
            ".Section1.thermal-vertical{"
            "position:relative;"
            "display:block;"
            "top:0;"
            "left:0;"
            "margin:0;"
            "padding:0;"
            "transform-origin:top left;"
            "transform:rotate(90deg) translateY(-72.1mm);"
            "width:"
            "210mm"
            ";height:72.1mm"
            ";"
            "overflow:hidden;"
            "page-break-inside:avoid;"
            "break-inside:avoid-page;"
            "}"
            ".head,.row2,.mgrid-thermal{"
            "width:100%!important;"
            "max-width:100%!important;"
            "margin-left:0!important;"
            "margin-right:0!important;"
            "border-spacing:0!important;"
            "box-sizing:border-box!important;"
            "}"
            ".rule{margin-left:0!important;margin-right:0!important;}"
            ".thermal-slip{margin-top:0!important;padding-top:0!important;padding-bottom:0!important;height:210mm!important;max-height:210mm!important;box-sizing:border-box!important;overflow:hidden!important;page-break-after:always;break-after:page;}"
            ".thermal-slip + .thermal-slip{page-break-before:always;break-before:page;}"
            ".thermal-slip:last-child{page-break-after:auto;break-after:auto;}"
            "}"
        )

    parts.append("</style></head><body>")

    def append_measurement_block(row, idx: int) -> None:
        kind_text = str(row["kind"] if "kind" in row.keys() else "").strip() or "Measurement"
        row_id_text = str(row["id"] if "id" in row.keys() else idx)
        if is_thermal:
            parts.append("<p class='kind'>&nbsp;</p>")
        else:
            parts.append(f"<p class='kind'><b>{html.escape(row_id_text)}/{idx} - {html.escape(kind_text)}</b></p>")
        pairs = _word_measure_pairs(row)
        if not pairs:
            parts.append("<p class='section'>-</p>")
            return
        if is_thermal:
            chunk_size = max(1, len(pairs))
            for chunk in _chunk_pairs(pairs, chunk_size):
                parts.append("<table class='mgrid-thermal'><tr>")
                for label, value in chunk:
                    value_tokens = [token.strip() for token in str(value or "").split(",") if token and token.strip()]
                    if not value_tokens:
                        value_tokens = [str(value or "-").strip() or "-"]
                    value_html = "<br>".join(html.escape(token) for token in value_tokens)
                    parts.append(
                        "<td>"
                        f"<span class='name'>{html.escape(str(label))}</span>"
                        f"<span class='value'>{value_html}</span>"
                        "</td>"
                    )
                parts.append("</tr></table>")
        else:
            chunk_size = 9
            for chunk in _chunk_pairs(pairs, chunk_size):
                parts.append("<table class='mgrid'><tr>")
                for label, _ in chunk:
                    parts.append(f"<td class='lbl'>{html.escape(str(label))}</td>")
                parts.append("</tr><tr>")
                for _, value in chunk:
                    parts.append(f"<td class='val'>{html.escape(str(value))}</td>")
                parts.append("</tr></table>")

    measurement_rows = list(measurements or [])
    if not measurement_rows:
        measurement_rows = [None]

    def _html_lines(text: str) -> str:
        parts_list = [html.escape(part.strip()) for part in str(text or "").split("|") if part.strip()]
        return "<br>".join(parts_list)

    for idx, row in enumerate(measurement_rows, start=1):
        row_items = _pick_item_notes_for_row(row)
        row_items_text, row_qty_total = _word_items_text_and_qty(row_items)
        row_measurements = [row] if row is not None else []
        row_req_text = _word_requirements(row_measurements) if row_measurements else req_text
        row_notes_text = _word_notes(order, row_measurements, row_items) if row_measurements else notes_text
        section_class = "Section1 thermal-vertical thermal-slip" if is_thermal else "Section1"
        parts.append(f"<div class='{section_class}'>")
        parts.append("<table class='head'><tr>")
        parts.append(f"<td><b>INVOICE&nbsp;&nbsp;NO:</b>&nbsp;&nbsp;{html.escape(invoice_no)}</td>")
        parts.append(f"<td><b>ORDER&nbsp;&nbsp;DATE:</b>&nbsp;&nbsp;{html.escape(order_date)}</td>")
        parts.append(f"<td><b>DELIVERY&nbsp;&nbsp;DATE:</b>&nbsp;&nbsp;{html.escape(delivery_date)}</td>")
        parts.append("</tr></table>")
        parts.append("<div class='rule'></div>")
        parts.append("<table class='row2'><tr>")
        parts.append(f"<td><b>Items</b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;:&nbsp;&nbsp;{html.escape(row_items_text)}</td>")
        parts.append("</tr></table>")
        parts.append("<p class='section'><b>Measurements</b></p>")
        if row is None:
            parts.append("<p class='section'>-</p>")
        else:
            append_measurement_block(row, idx)
        if row_req_text:
            parts.append(f"<p class='section-wrap'><b>Requirements</b>&nbsp;:&nbsp;{_html_lines(row_req_text)}</p>")
        if row_notes_text:
            parts.append(f"<p class='section-wrap'><b>Notes</b>&nbsp;:&nbsp;{_html_lines(row_notes_text)}</p>")
        parts.append("</div>")

    parts.append("</body></html>")
    return "".join(parts)


def _generate_order_word_html_tailor(order, measurements, order_items, paper: str = "a4") -> str:
    folder = os.path.join(APP_DIR, "static", "order_docs")
    os.makedirs(folder, exist_ok=True)
    file_path = os.path.join(folder, f"order_{order['id']}_tailor.doc")
    html_text = _build_order_word_html_tailor(order, measurements, order_items, paper=paper)
    with open(file_path, "w", encoding="utf-8-sig") as handle:
        handle.write(html_text)
    return file_path


def generate_order_docx_tailor(order, measurements, order_items, paper: str = "a4") -> str:
    if Document is None:
        return _generate_order_word_html_tailor(order, measurements, order_items, paper=paper)

    folder = os.path.join(APP_DIR, "static", "order_docs")
    os.makedirs(folder, exist_ok=True)
    file_path = os.path.join(folder, f"order_{order['id']}_tailor.docx")

    is_thermal = str(paper or "").strip().lower() == "thermal"
    tamil_font = _docx_tamil_font_name()
    doc = Document()
    if is_thermal and measurements:
        thermal_len_mm = max(_estimate_thermal_length_mm(order, [row], order_items) for row in measurements)
    else:
        thermal_len_mm = _estimate_thermal_length_mm(order, measurements, order_items) if is_thermal else 297.0
    section = doc.sections[0]
    if Mm is not None:
        if is_thermal:
            if WD_ORIENTATION is not None:
                section.orientation = WD_ORIENTATION.PORTRAIT
            section.page_width = Mm(72)
            section.page_height = Mm(thermal_len_mm)
            section.top_margin = Mm(0)
            section.bottom_margin = Mm(1)
            section.left_margin = Mm(1)
            section.right_margin = Mm(1)
        else:
            if WD_ORIENTATION is not None:
                section.orientation = WD_ORIENTATION.LANDSCAPE
            section.page_width = Mm(297)
            section.page_height = Mm(210)
            section.top_margin = Mm(8)
            section.bottom_margin = Mm(8)
            section.left_margin = Mm(8)
            section.right_margin = Mm(8)

    normal_style = doc.styles["Normal"]
    if Pt is not None:
        normal_style.font.size = Pt(12 if is_thermal else 11)
    normal_style.font.name = tamil_font
    try:
        normal_style.paragraph_format.space_before = Pt(0)
        normal_style.paragraph_format.space_after = Pt(0)
        normal_style.paragraph_format.line_spacing = 1.0
    except Exception:
        pass
    if qn is not None:
        style_rpr = normal_style.element.get_or_add_rPr()
        style_rfonts = style_rpr.get_or_add_rFonts()
        style_rfonts.set(qn("w:ascii"), tamil_font)
        style_rfonts.set(qn("w:hAnsi"), tamil_font)
        style_rfonts.set(qn("w:eastAsia"), tamil_font)
        style_rfonts.set(qn("w:cs"), tamil_font)

    invoice_no = _word_order_no(order)
    created_at_text = order["created_at"] if "created_at" in order.keys() else ""
    order_date = _word_date_ddmmyyyy(created_at_text)
    delivery_date = _word_date_ddmmyyyy(_word_delivery_date(order))
    items_text, qty_total = _word_items_text_and_qty(order_items)
    req_text = _word_requirements(measurements)
    notes_text = _word_notes(order, measurements, order_items)
    body_size = 13 if is_thermal else 12
    label_size = 11 if is_thermal else 11
    value_size = 18 if is_thermal else 14

    if not is_thermal:
        head = doc.add_table(rows=1, cols=3)
        head.autofit = True
        head_cells = head.rows[0].cells
        _set_docx_run_font(head_cells[0].paragraphs[0].add_run(f"INVOICE  NO:  {invoice_no}"), tamil_font, size_pt=body_size, bold=True)
        _set_docx_run_font(head_cells[1].paragraphs[0].add_run(f"ORDER  DATE:  {order_date}"), tamil_font, size_pt=body_size, bold=True)
        _set_docx_run_font(head_cells[2].paragraphs[0].add_run(f"DELIVERY  DATE:  {delivery_date}"), tamil_font, size_pt=body_size, bold=True)
        if WD_ALIGN_PARAGRAPH is not None:
            head_cells[0].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.LEFT
            head_cells[1].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
            head_cells[2].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT

        rule = doc.add_paragraph()
        _set_docx_run_font(rule.add_run("-" * 90), tamil_font, size_pt=body_size)

        item_tbl = doc.add_table(rows=1, cols=2)
        item_cells = item_tbl.rows[0].cells
        _set_docx_run_font(item_cells[0].paragraphs[0].add_run(f"Items        :  {items_text}"), tamil_font, size_pt=body_size, bold=True)

        mtitle = doc.add_paragraph()
        _set_docx_run_font(mtitle.add_run("Measurements"), tamil_font, size_pt=body_size + 1, bold=True)

    for idx, row in enumerate(measurements, start=1):
        if is_thermal:
            if idx > 1:
                doc.add_page_break()
            head = doc.add_table(rows=1, cols=3)
            head.autofit = True
            head_cells = head.rows[0].cells
            _set_docx_run_font(head_cells[0].paragraphs[0].add_run(f"INVOICE  NO:  {invoice_no}"), tamil_font, size_pt=body_size, bold=True)
            _set_docx_run_font(head_cells[1].paragraphs[0].add_run(f"ORDER  DATE:  {order_date}"), tamil_font, size_pt=body_size, bold=True)
            _set_docx_run_font(head_cells[2].paragraphs[0].add_run(f"DELIVERY  DATE:  {delivery_date}"), tamil_font, size_pt=body_size, bold=True)
            if WD_ALIGN_PARAGRAPH is not None:
                head_cells[0].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.LEFT
                head_cells[1].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
                head_cells[2].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT

            rule = doc.add_paragraph()
            _set_docx_run_font(rule.add_run("-" * 90), tamil_font, size_pt=body_size)

            item_tbl = doc.add_table(rows=1, cols=2)
            item_cells = item_tbl.rows[0].cells
            _set_docx_run_font(item_cells[0].paragraphs[0].add_run(f"Items        :  {items_text}"), tamil_font, size_pt=body_size, bold=True)

            mtitle = doc.add_paragraph()
            _set_docx_run_font(mtitle.add_run("Measurements"), tamil_font, size_pt=body_size + 1, bold=True)

        kind_text = str(row["kind"] if "kind" in row.keys() else "").strip()
        row_id_text = str(row["id"] if "id" in row.keys() else idx)
        kind_line = doc.add_paragraph()
        _set_docx_run_font(kind_line.add_run(f"{row_id_text}/{idx}  -  {kind_text or 'Measurement'}"), tamil_font, size_pt=body_size, bold=True)

        pairs = _word_measure_pairs(row)
        if not pairs:
            empty_line = doc.add_paragraph()
            _set_docx_run_font(empty_line.add_run("-"), tamil_font, size_pt=body_size)
            continue

        chunk_size = max(1, len(pairs)) if is_thermal else 9
        for chunk in _chunk_pairs(pairs, chunk_size):
            table = doc.add_table(rows=2, cols=len(chunk))
            table.autofit = True
            label_cells = table.rows[0].cells
            value_cells = table.rows[1].cells
            for col_idx, (label, value) in enumerate(chunk):
                p_label = label_cells[col_idx].paragraphs[0]
                _set_docx_run_font(p_label.add_run(str(label)), tamil_font, size_pt=label_size, bold=True)
                p_value = value_cells[col_idx].paragraphs[0]
                _set_docx_run_font(p_value.add_run(str(value)), tamil_font, size_pt=value_size, bold=True)
                if WD_ALIGN_PARAGRAPH is not None:
                    p_label.alignment = WD_ALIGN_PARAGRAPH.CENTER
                    p_value.alignment = WD_ALIGN_PARAGRAPH.CENTER

        if is_thermal:
            if req_text:
                req_line = doc.add_paragraph()
                _set_docx_run_font(req_line.add_run(f"Requirements : {req_text}"), tamil_font, size_pt=body_size + 1, bold=True)
            if notes_text:
                notes_line = doc.add_paragraph()
                _set_docx_run_font(notes_line.add_run(f"Notes : {notes_text}"), tamil_font, size_pt=body_size + 1, bold=True)

    if is_thermal and not measurements:
        head = doc.add_table(rows=1, cols=3)
        head.autofit = True
        head_cells = head.rows[0].cells
        _set_docx_run_font(head_cells[0].paragraphs[0].add_run(f"INVOICE  NO:  {invoice_no}"), tamil_font, size_pt=body_size, bold=True)
        _set_docx_run_font(head_cells[1].paragraphs[0].add_run(f"ORDER  DATE:  {order_date}"), tamil_font, size_pt=body_size, bold=True)
        _set_docx_run_font(head_cells[2].paragraphs[0].add_run(f"DELIVERY  DATE:  {delivery_date}"), tamil_font, size_pt=body_size, bold=True)
        if WD_ALIGN_PARAGRAPH is not None:
            head_cells[0].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.LEFT
            head_cells[1].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.CENTER
            head_cells[2].paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT
        mtitle = doc.add_paragraph()
        _set_docx_run_font(mtitle.add_run("Measurements"), tamil_font, size_pt=body_size + 1, bold=True)
        empty_line = doc.add_paragraph()
        _set_docx_run_font(empty_line.add_run("-"), tamil_font, size_pt=body_size)
        if req_text:
            req_line = doc.add_paragraph()
            _set_docx_run_font(req_line.add_run(f"Requirements : {req_text}"), tamil_font, size_pt=body_size + 1, bold=True)
        if notes_text:
            notes_line = doc.add_paragraph()
            _set_docx_run_font(notes_line.add_run(f"Notes : {notes_text}"), tamil_font, size_pt=body_size + 1, bold=True)

    if not is_thermal:
        if req_text:
            req_line = doc.add_paragraph()
            _set_docx_run_font(req_line.add_run(f"Requirements : {req_text}"), tamil_font, size_pt=body_size + 1, bold=True)
        if notes_text:
            notes_line = doc.add_paragraph()
            _set_docx_run_font(notes_line.add_run(f"Notes : {notes_text}"), tamil_font, size_pt=body_size + 1, bold=True)

    doc.save(file_path)
    return file_path


def _render_order_print_tailor(order_id: int, paper: str = "a4"):
    conn = get_db()
    order = conn.execute(
        """
        SELECT orders.*, customers.name, customers.phone, customers.address
        FROM orders
        JOIN customers ON customers.id = orders.customer_id
        WHERE orders.id = ?
        """,
        (order_id,),
    ).fetchone()
    if not order:
        conn.close()
        return redirect(url_for("orders"))
    measurements = fetch_order_measurements(
        conn,
        int(order["customer_id"]),
        int(order["id"]),
        order["created_at"],
    )
    items = conn.execute(
        "SELECT * FROM order_items WHERE order_id = ?",
        (order_id,),
    ).fetchall()
    conn.close()
    selected_item_type = request.args.get("item_type", "").strip().lower()
    if selected_item_type:
        items = [
            item for item in items
            if (item["item_type"] or "").strip().lower() == selected_item_type
        ]
        measurements = [
            row for row in measurements
            if selected_item_type in (row["kind"] or "").strip().lower()
        ]
        order = dict(order)
        order["notes"] = ""
    # Tailor slip is fixed to landscape text orientation for direct printer flow.
    is_landscape = True

    if request.method == "POST" or request.args.get("direct", "").strip() == "1":
        pdf_path = generate_order_pdf_80mm(
            order,
            measurements,
            items,
            mode="tailor",
            landscape=is_landscape,
            tailor_paper=paper,
        )
        ok, err = force_print_to_selected_printer(pdf_path, order_id, "tailor")
        if not ok:
            return jsonify({"ok": False, "message": err}), 500
        return jsonify({"ok": True, "message": "Sent to selected printer."})

    try:
        docx_path = generate_order_docx_tailor(order, measurements, items, paper=paper)
    except Exception as exc:
        return jsonify({"ok": False, "message": f"Tailor Word document was not generated: {exc}"}), 500

    download_requested = request.args.get("download", "").strip() == "1"
    preview_requested = request.args.get("preview", "").strip()
    # Default browser view for tailor slip. Use ?download=1 for file download.
    show_preview = (preview_requested != "0") and (not download_requested)
    if show_preview:
        preview_html = _build_order_word_html_tailor(order, measurements, items, paper=paper)
        return Response(preview_html, mimetype="text/html; charset=utf-8")

    if os.path.exists(docx_path):
        is_docx = str(docx_path).lower().endswith(".docx")
        out_name = f"order_{order_id}_tailor.docx" if is_docx else f"order_{order_id}_tailor.doc"
        mime = (
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
            if is_docx
            else "application/msword"
        )
        return send_file(
            docx_path,
            as_attachment=download_requested,
            download_name=out_name,
            mimetype=mime,
        )
    return jsonify({"ok": False, "message": "Tailor Word document was not generated."}), 500


@app.route("/orders/<int:order_id>/print/a4", methods=["GET", "POST"])
def order_print_a4(order_id: int):
    conn = get_db()
    order = conn.execute("SELECT * FROM orders WHERE id = ?", (order_id,)).fetchone()
    if order and str(order["order_type"] or "").strip().lower() == "vehicle sale":
        sale = conn.execute(
            """
            SELECT vso.*, c.name AS customer_name_live, c.phone AS customer_phone_live
            FROM vehicle_sale_orders vso
            LEFT JOIN customers c ON c.id = vso.customer_id
            WHERE vso.order_id = ?
            """,
            (order_id,),
        ).fetchone()
        conn.close()
        if not sale:
            return redirect(url_for("orders"))

        customer_name = (sale.get("customer_name") or sale.get("customer_name_live") or "").strip()
        customer_phone = (sale.get("customer_phone") or sale.get("customer_phone_live") or "").strip()
        customer_address = (sale.get("customer_address") or "").strip()

        selling_price = float(sale.get("selling_price") or 0)
        repair_cost = float(sale.get("repair_cost") or 0)
        subtotal_amount = float(sale.get("subtotal_amount") or selling_price or 0)
        discount_amount = float(sale.get("discount_amount") or 0)
        gst_percent = float(sale.get("gst_percent") or 0)
        gst_amount = float(sale.get("gst_amount") or 0)
        advance_amount = float(sale.get("advance_amount") or 0)
        total_amount = float(sale.get("total_amount") or max(subtotal_amount - discount_amount + gst_amount, 0))
        taxable_amount = max(subtotal_amount - discount_amount, 0)

        order_for_print = dict(order)
        order_for_print["order_type"] = "Vehicle Sale"
        order_for_print["name"] = customer_name or "-"
        order_for_print["phone"] = customer_phone or "-"
        order_for_print["address"] = customer_address or ""
        order_for_print["total_amount"] = total_amount
        order_for_print["advance_amount"] = advance_amount
        order_for_print["paid_amount"] = float(order_for_print.get("paid_amount") or 0)
        order_for_print["discount_amount"] = discount_amount
        order_for_print["gst_percent"] = gst_percent
        order_for_print["gst_amount"] = gst_amount
        order_for_print["taxable_amount"] = taxable_amount
        order_for_print.setdefault("cgst_amount", 0)
        order_for_print.setdefault("sgst_amount", 0)
        order_for_print.setdefault("cgst_percent", 0)
        order_for_print.setdefault("sgst_percent", 0)
        order_for_print.setdefault("notes", "")

        items = [
            {
                "item_type": f"{(sale.get('vehicle_name') or 'Vehicle').strip()} ({(sale.get('vehicle_number') or '').strip()})".strip(),
                "qty": 1,
                "uom_name": "",
                "unit_price": selling_price,
                "line_total": selling_price,
                "item_group": "material",
            },
        ]


        pdf_path = generate_order_pdf_80mm(order_for_print, [], items, mode="customer", landscape=False)
        download_requested = request.args.get("download", "").strip() == "1"
        if os.path.exists(pdf_path):
            return send_file(
                pdf_path,
                as_attachment=download_requested,
                download_name=f"vehicle_sale_{order_id}.pdf",
                mimetype="application/pdf",
            )
        return jsonify({"ok": False, "message": "Vehicle sale PDF was not generated."}), 500
    conn.close()
    return _render_order_print_tailor(order_id, paper="a4")


