            if purchase_settlement_status == "Unpaid" and float(purchase_paid_amount) > 0:
                conn.close()
                return render_inventory_add("For Unpaid status, paid amount must be 0.")
            if purchase_settlement_status == "Partial" and not (0 < float(purchase_paid_amount) < float(purchase_price)):
                conn.close()
