        purchase_finance_yard_ref = (request.form.get("pi_finance_customer_phone") or "").strip() or None
        purchase_finance_settlement_date = (request.form.get("pi_finance_id_proof_ref") or "").strip() or None
        purchase_agent_name = (request.form.get("pi_agent_customer_name") or "").strip() or None
        purchase_agent_broker_details = (request.form.get("pi_agent_customer_phone") or "").strip() or None
