        purchase_finance_company = (request.form.get("pi_finance_company") or request.form.get("pi_finance_customer_name") or "").strip() or None
        purchase_finance_yard_ref = (request.form.get("pi_finance_yard_ref") or request.form.get("pi_finance_address") or "").strip() or None
