        purchase_branch_from_branch = (request.form.get("pi_branch_from_branch") or request.form.get("pi_branch_customer_name") or "").strip() or None
        purchase_branch_transfer_id = (request.form.get("pi_branch_transfer_id") or request.form.get("pi_branch_customer_phone") or "").strip() or None
        purchase_branch_handled_by = (request.form.get("pi_branch_handled_by") or request.form.get("pi_branch_address") or "").strip() or None

