@app.route("/vendors/add", methods=["GET", "POST"])
def vendors_add():
    conn = get_db()
    vendor_code = generate_vendor_code(conn)
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        phone = request.form.get("phone", "").strip()
        address = request.form.get("address", "").strip()
        if not name:
            conn.close()
            return render_template(
                "vendors_add.html",
                vendor_code=vendor_code,
                error="Vendor name is required.",
            )
        if not phone:
            conn.close()
            return render_template(
                "vendors_add.html",
                vendor_code=vendor_code,
                error="Phone number is required.",
            )
        if not address:
            conn.close()
            return render_template(
                "vendors_add.html",
                vendor_code=vendor_code,
                error="Address is required.",
            )
        if phone and not is_valid_phone(phone):
            conn.close()
            return render_template(
                "vendors_add.html",
                vendor_code=vendor_code,
                error="Phone number must contain digits only. (+ is optional.)",
            )
        conn.execute(
            """
            INSERT INTO vendors (vendor_code, name, phone, email, address, created_at)
            VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                vendor_code,
                name,
                phone or None,
                request.form.get("email", "").strip() or None,
                address,
                now_str(),
            ),
        )
        conn.commit()
        conn.close()
        return redirect(url_for("vendors"))
    conn.close()
    return render_template("vendors_add.html", vendor_code=vendor_code)


