@app.route("/api/change-password", methods=["POST"])
@jwt_required()
def api_change_password():
    try:
        data = request.get_json(force=True, silent=True) or {}
        current_password = data.get("current_password") or ""
        new_password = data.get("new_password") or ""

        if not current_password or not new_password:
            return jsonify({"success": False, "message": "Current and new password are required."}), 400

        claims = get_jwt()
        user_id = get_jwt_identity()
        branch_code = claims.get("branch_code")
        selected_branch = get_branch_record(branch_code)
        if not selected_branch:
            return jsonify({"success": False, "message": "Invalid branch."}), 400

        conn = get_db_for_branch(selected_branch["code"])
        try:
            user_row = conn.execute(
                "SELECT id, password_hash FROM app_users WHERE id = ?",
                (user_id,),
            ).fetchone()
            if not user_row:
                return jsonify({"success": False, "message": "User not found."}), 404

            if not verify_user_password(user_row["password_hash"], current_password):
                return jsonify({"success": False, "message": "Current password is incorrect."}), 401

            new_hash = generate_password_hash(new_password)
            conn.execute(
                "UPDATE app_users SET password_hash = ? WHERE id = ?",
                (new_hash, user_row["id"]),
            )
            conn.commit()
            return jsonify({"success": True, "message": "Password changed successfully."})
        finally:
            conn.close()
    except Exception as e:
        return jsonify({"success": False, "message": str(e)}), 500


# ────────────────────────────────────────────────────────────
# AI VEHICLE DETECTION — auto-fill Add Vehicle form from photos
# POST /api/vehicles/ai-detect
# Accepts up to 4 "photo" files (same field name/limit as
# api_vehicle_add above). Sends them to a Groq vision model and
# returns a best-guess vehicle_name/color/type, each with a
# confidence flag — this is a SUGGESTION only, never auto-saved;
# the Flutter form pre-fills fields from this response but staff
# still review/edit before hitting the real "Add Vehicle" submit.
# ────────────────────────────────────────────────────────────

GROQ_API_KEY = os.getenv("GROQ_API_KEY", "")
GROQ_VISION_MODEL = os.getenv("GROQ_VISION_MODEL", "qwen/qwen3.6-27b")

AI_DETECT_SYSTEM_PROMPT = """You identify motorcycles/scooters from dealership photos.

You'll see up to 2 photos of the SAME vehicle. Return ONLY this JSON object, no markdown, no extra text:

{
  "vehicle_name": "<Brand + Model>",
  "vehicle_name_confidence": "high" | "medium" | "low",
  "color": "<primary color(s)>",
  "color_confidence": "high" | "medium" | "low",
  "vehicle_type": "<e.g. Commuter Motorcycle, Scooter, Cruiser>",
  "visible_damage": "<short note, or 'None visible'>",
  "registration_no": "<ONLY if a plate is clearly legible, else null>",
  "notes": "<one short useful sentence>"
  
}

Rules:
- Prefer visible text/decals/logos over shape guessing for vehicle_name.
- If no text is legible, still guess from shape but mark vehicle_name_confidence "low".
- Never invent a registration number.
- Do not guess model year, kms driven, ownership, insurance, or price — omit them entirely.
- JSON only."""


def _photo_to_data_url(upload, *, max_dim: int = 512, quality: int = 55) -> str | None:
    """Read an uploaded photo, downscale/compress it, and return a base64
    data: URL for the Groq vision API's image_url content block.

    Vision models spend input tokens based on image resolution, so a
    full-size phone photo (often 3000px+ wide) can blow past Groq's free
    tier tokens-per-minute cap on its own. Resizing to a modest max
    dimension and re-encoding as JPEG keeps 3 photos well within budget
    while still leaving plenty of detail for the model to read text/logos.

    max_dim/quality are tunable per call site: vehicle "what does this bike
    look like" photos can be small and heavily compressed, but document
    scans (RC book / insurance / PUC) need a larger max_dim and higher
    quality or the small printed text becomes unreadable to the model.
    """
    if not upload or not getattr(upload, "filename", ""):
        return None
    upload.stream.seek(0)
    raw = upload.stream.read()
    upload.stream.seek(0)
    if not raw:
        return None

    try:
        img = Image.open(io.BytesIO(raw))
        img = img.convert("RGB")
        if img.width > max_dim or img.height > max_dim:
            img.thumbnail((max_dim, max_dim), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=quality, optimize=True)
        compressed = buf.getvalue()
        print(f"[AI-DETECT] Compressed photo: {len(raw)} bytes -> {len(compressed)} bytes "
              f"({img.width}x{img.height})")
    except Exception as e:
        # If Pillow can't process it for any reason, fall back to the
        # original bytes rather than silently dropping the photo.
        print(f"[AI-DETECT] Compression FAILED, using raw bytes ({len(raw)} bytes). Error: {e}")
        compressed = raw

    encoded = base64.b64encode(compressed).decode("ascii")
    return f"data:image/jpeg;base64,{encoded}"


def _document_to_data_url(upload) -> str | None:
    """Same idea as _photo_to_data_url but tuned for OCR of a document scan
    (RC book): reads small printed text/numbers (e.g. chassis number), so
    it needs more resolution than the vehicle-shape photos, but not full
    phone-camera resolution. Groq's vision tokens are driven by pixel
    dimensions, not JPEG quality/file size, so max_dim=1200 (down from an
    earlier 1600, which was a no-op for the ~1600px-tall photos this
    actually receives) is what cuts the token cost that was eating most
    of the org's per-minute budget."""
    return _photo_to_data_url(upload, max_dim=1200, quality=85)


def _insurance_document_to_data_url(upload) -> str | None:
    """Insurance photos only need to yield 2 dates (see the trimmed-down
    INSURANCE_SYSTEM_PROMPT), not fine print like a chassis number, so
    they don't need RC-book-level resolution."""
    return _photo_to_data_url(upload, max_dim=900, quality=70)


def _call_groq_vision(system_prompt: str, image_urls: list[str], *, max_tokens: int = 450):
    """Shared Groq vision call used by both the vehicle-photo detector and
    the document OCR detectors below. Returns (parsed_json_dict, error_message).
    On any failure, parsed_json_dict is None and error_message explains why.

    Retries once on a 429 (tokens-per-minute rate limit) — Groq's error
    body tells us exactly how many seconds until the window resets (e.g.
    "Please try again in 15.8s"), so we wait that long (plus a small
    buffer) and retry instead of immediately failing the request. This is
    the main fix for RC book + insurance back-to-back calls tripping the
    same per-minute budget."""
    if not GROQ_API_KEY:
        return None, "AI detection is not configured on this server."

    user_content = [{"type": "text", "text": "Extract the requested details from the attached image(s)."}]
    user_content += [{"type": "image_url", "image_url": {"url": url}} for url in image_urls]

    payload = {
        "model": GROQ_VISION_MODEL,
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_content},
        ],
        "temperature": 0.2,
        "max_tokens": max_tokens,
        "reasoning_effort": "none",
        "response_format": {"type": "json_object"},
    }

    for attempt in range(2):  # initial try + 1 retry
        try:
            res = http_requests.post(
                "https://api.groq.com/openai/v1/chat/completions",
                headers={
                    "Authorization": f"Bearer {GROQ_API_KEY}",
                    "Content-Type": "application/json",
                },
                json=payload,
                timeout=45,
            )
        except Exception as e:
            return None, f"AI service error: {e}"

        if res.status_code == 429 and attempt == 0:
            wait_seconds = 5.0  # sane fallback if we can't parse Groq's message
            match = re.search(r"try again in ([\d.]+)s", res.text)
            if match:
                wait_seconds = float(match.group(1))
            wait_seconds = min(wait_seconds, 30.0) + 1.0  # small buffer, capped
            print(f"[AI-DETECT] Groq 429, waiting {wait_seconds:.1f}s then retrying once...")
            time.sleep(wait_seconds)
            continue

        if res.status_code != 200:
            print(f"[AI-DETECT] Groq returned {res.status_code}: {res.text}")
            return None, "AI detection failed."

        break
    else:
        return None, "AI detection failed."

    try:
        raw_content = res.json()["choices"][0]["message"]["content"]
        return json.loads(raw_content), None
    except Exception as e:
        return None, f"Could not parse AI response: {e}"


# ────────────────────────────────────────────────────────────
# Document OCR prompts — RC Book / Insurance / PUC.
# Each mirrors AI_DETECT_SYSTEM_PROMPT's contract: JSON only, a
# confidence flag per extracted field, never invent values, dates
# normalized to ISO (YYYY-MM-DD) so they drop straight into <input
# type="date"> / Flutter DateTime fields regardless of the date format
# printed on the physical document.
# ────────────────────────────────────────────────────────────

RC_BOOK_SYSTEM_PROMPT = """You read Indian vehicle Registration Certificate (RC) book/card photos.

Return ONLY this JSON object, no markdown, no extra text:

{
  "registration_no": "<vehicle registration/number plate, e.g. TN-01-AB-1234>",
  "registration_no_confidence": "high" | "medium" | "low",
  "rc_number": "<RC document/certificate number if printed, else null>",
  "rc_owner_name": "<registered owner's full name>",
  "rc_owner_name_confidence": "high" | "medium" | "low",
  "rc_owner_address": "<registered owner's address>",
  "chassis_no": "<chassis/frame number>",
  "chassis_no_confidence": "high" | "medium" | "low",
  "engine_no": "<engine number, else null>",
  "model_year": "<manufacture/registration year as YYYY, else null>",
  "rc_book_start_date": "<registration/RC valid-from date as YYYY-MM-DD, else null>",
  "rc_book_end_date": "<RC validity/expiry date as YYYY-MM-DD, else null>",
  "notes": "<one short useful sentence>"
}

Rules:
- Only fill a field if it is actually legible in the image; otherwise use null and mark confidence "low".
- Never invent a registration number, chassis number, or owner name.
- Convert any date to YYYY-MM-DD regardless of how it's printed on the document.
- JSON only."""

INSURANCE_SYSTEM_PROMPT = """You read Indian two-wheeler insurance policy/certificate photos.

We only need the insurance validity period from this document (everything
else -- registration no, owner name, chassis no, etc. -- comes from the RC
book instead). Return ONLY this JSON object, no markdown, no extra text:

{
  "insurance_start_date": "<period of insurance FROM date as YYYY-MM-DD>",
  "insurance_end_date": "<period of insurance TO/expiry date as YYYY-MM-DD>",
  "insurance_start_date_confidence": "high" | "medium" | "low",
  "insurance_end_date_confidence": "high" | "medium" | "low",
  "notes": "<one short useful sentence>"
}

Rules:
- Only fill a field if it is actually legible in the image; otherwise use null and mark confidence "low".
- Never invent a date.
- Convert any date to YYYY-MM-DD regardless of how it's printed on the document.
- JSON only."""

PUC_SYSTEM_PROMPT = """You read Indian Pollution Under Control (PUC) certificate photos.

Return ONLY this JSON object, no markdown, no extra text:

{
  "puc_number": "<PUC certificate number, else null>",
  "registration_no": "<vehicle registration number on the certificate, else null>",
  "puc_valid_from": "<test/issue date as YYYY-MM-DD, else null>",
  "puc_valid_upto": "<expiry date as YYYY-MM-DD>",
  "puc_valid_upto_confidence": "high" | "medium" | "low",
  "notes": "<one short useful sentence>"
}

Rules:
- Only fill a field if it is actually legible in the image; otherwise use null and mark confidence "low".
- Never invent a certificate number or date.
- Convert any date to YYYY-MM-DD regardless of how it's printed on the document.
- JSON only."""


@app.route("/api/vehicles/ai-detect-documents", methods=["POST"])
@jwt_required()
def api_vehicle_ai_detect_documents():
    """
    Mobile AI document extraction — auto-fill Add Vehicle form from the RC
    Book (page 1 + page 2) / Insurance photos, the same way
    api_vehicle_ai_detect() auto-fills name/color/type from the bike
    photos. PUC is intentionally not accepted here — it isn't needed to
    get the details this endpoint extracts.

    Multipart fields (all optional, send whichever the user has uploaded
    so far — e.g. they may attach just the RC book front page first):
      rc_book           : 1 file (RC book page 1 / front)
      rc_book_back      : 1 file (RC book page 2 / back)
      insurance_doc      : 1 file

    Returns a single merged "detected" object (same shape family as
    /api/vehicles/ai-detect) plus a "sections" object showing which
    document each field came from, and a "warnings" list for any
    document that failed to process. Like the photo detector, this is a
    SUGGESTION only — the mobile form should pre-fill fields from this
    response but the user still reviews/edits before saving.
    """
    if not GROQ_API_KEY:
        return jsonify({"success": False, "message": "AI detection is not configured on this server."}), 503

    rc_book_upload = request.files.get("rc_book")
    rc_book_back_upload = request.files.get("rc_book_back")
    insurance_upload = request.files.get("insurance_doc")

    if not any([
        rc_book_upload and getattr(rc_book_upload, "filename", ""),
        rc_book_back_upload and getattr(rc_book_back_upload, "filename", ""),
        insurance_upload and getattr(insurance_upload, "filename", ""),
    ]):
        return jsonify({
            "success": False,
            "message": "Attach at least one of: RC book (page 1 or 2), insurance document.",
        }), 400

    detected: dict = {}
    sections: dict = {}
    warnings: list[str] = []

    # RC book is sent as a single job with up to 2 images (front + back),
    # since it's one document — both pages go to the model together so
    # details that only appear on the back page (e.g. chassis no) are
    # still picked up.
    # max_tokens is tuned per job to match how much each schema actually
    # needs — insurance now only returns 2 dates (+ confidences/notes), so
    # a smaller reservation leaves more of the org's per-minute token
    # budget free for the RC book call that runs right before it.
    jobs = [
        ("rc_book", [rc_book_upload, rc_book_back_upload], RC_BOOK_SYSTEM_PROMPT, 450, _document_to_data_url),
        ("insurance", [insurance_upload], INSURANCE_SYSTEM_PROMPT, 200, _insurance_document_to_data_url),
    ]

    for section_name, uploads, prompt, job_max_tokens, to_data_url in jobs:
        valid_uploads = [u for u in uploads if u and getattr(u, "filename", "")]
        if not valid_uploads:
            continue

        data_urls = []
        for upload in valid_uploads:
            data_url = to_data_url(upload)
            if not data_url:
                warnings.append(f"Could not read one of the {section_name} images.")
                continue
            data_urls.append(data_url)

        if not data_urls:
            continue

        result, error = _call_groq_vision(prompt, data_urls, max_tokens=job_max_tokens)
        if error:
            print(f"[AI-DETECT-DOCS] {section_name} failed: {error}")
            warnings.append(f"{section_name.replace('_', ' ').title()} detection failed: {error}")
            continue

        sections[section_name] = result
        # Merge into the flat "detected" dict. Later sections don't
        # silently clobber an already-confident value from an earlier
        # one — prefer whichever has higher confidence, and otherwise
        # keep the first non-null value seen. (In practice this rarely
        # triggers now: RC book is the sole source for registration_no/
        # chassis_no/owner details, and insurance only contributes its
        # two date fields, so the two sections' keys barely overlap.)
        for key, value in (result or {}).items():
            if value in (None, ""):
                continue
            if key.endswith("_confidence"):
                detected.setdefault(key, value)
                continue
            if key not in detected:
                detected[key] = value
            else:
                base_key = key
                new_conf = (result or {}).get(f"{base_key}_confidence", "medium")
                old_conf = detected.get(f"{base_key}_confidence", "medium")
                rank = {"high": 2, "medium": 1, "low": 0}
                if rank.get(new_conf, 1) > rank.get(old_conf, 1):
                    detected[key] = value
                    detected[f"{base_key}_confidence"] = new_conf

    if not sections:
        return jsonify({
            "success": False,
            "message": "Could not process any of the attached documents.",
            "warnings": warnings,
        }), 502

    return jsonify({
        "success": True,
        "detected": detected,
        "sections": sections,
        "warnings": warnings,
    }), 200


@app.route("/api/vehicles/ai-detect", methods=["POST"])
@jwt_required()
def api_vehicle_ai_detect():
    if not GROQ_API_KEY:
        return jsonify({"success": False, "message": "AI detection is not configured on this server."}), 503

    uploaded_photos = [
        upload for upload in request.files.getlist("photo")
        if upload and getattr(upload, "filename", "")
    ]
    if not uploaded_photos:
        return jsonify({"success": False, "message": "Please attach at least 1 vehicle photo."}), 400

    photo_error = validate_vehicle_image_uploads(uploaded_photos, min_files=1, max_files=4)
    if photo_error:
        return jsonify({"success": False, "message": photo_error}), 400

    image_blocks = []
    for upload in uploaded_photos[:2]:
        data_url = _photo_to_data_url(upload)
        if data_url:
            image_blocks.append({"type": "image_url", "image_url": {"url": data_url}})

    if not image_blocks:
        return jsonify({"success": False, "message": "Could not read the uploaded photo(s)."}), 400

    total_b64_chars = sum(len(b["image_url"]["url"]) for b in image_blocks)
    print(f"[AI-DETECT] Sending {len(image_blocks)} image(s) to Groq, "
          f"total base64 length: {total_b64_chars} chars")

    user_content = [{"type": "text", "text": "Identify this vehicle from the attached photo(s)."}] + image_blocks

    try:
        res = http_requests.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers={
                "Authorization": f"Bearer {GROQ_API_KEY}",
                "Content-Type": "application/json",
            },
            json={
                "model": GROQ_VISION_MODEL,
                "messages": [
                    {"role": "system", "content": AI_DETECT_SYSTEM_PROMPT},
                    {"role": "user", "content": user_content},
                ],
                "temperature": 0.2,
                "max_tokens": 450,
                "reasoning_effort": "none",
                "response_format": {"type": "json_object"},
            },
            timeout=45,
        )
    except Exception as e:
        return jsonify({"success": False, "message": f"AI service error: {e}"}), 502

    if res.status_code != 200:
        print(f"[AI-DETECT] Groq returned {res.status_code}: {res.text}")
        return jsonify({"success": False, "message": "AI detection failed.", "detail": res.text}), 502

    try:
        raw_content = res.json()["choices"][0]["message"]["content"]
        detected = json.loads(raw_content)
    except Exception as e:
        return jsonify({"success": False, "message": f"Could not parse AI response: {e}"}), 502

    return jsonify({"success": True, "detected": detected}), 200


@app.route("/api/vehicles/<int:vehicle_id>/sell", methods=["POST"])
@jwt_required()
def api_vehicle_sell(vehicle_id: int):
    """
    Mobile Sell Vehicle.

    JSON body fields:
      customer_name        (required)
      customer_phone       (required)
      customer_identifier  (required)
      customer_address     (optional)
      selling_price        (required, decimal)
      discount_amount      (optional, decimal, default 0)
      gst_percent          (optional, decimal, default 0)
      advance_amount       (optional, decimal, default 0)
      payment_method       (optional: Cash/UPI/Bank/GPay/Card, default Cash)
      delivery_date        (optional, YYYY-MM-DD)
    """
    conn = get_db()
    try:
        # -- vehicle must exist and not already be sold/transferred
        row = conn.execute(
            "SELECT * FROM vehicles WHERE id = ?", (vehicle_id,)
        ).fetchone()
        if not row:
            return jsonify({"success": False, "message": "Vehicle not found."}), 404

        status_v = (row.get("status") or "available").strip().lower()
        if status_v in ("sold", "transferred", "rented"):
            return jsonify({
                "success": False,
                "message": f"Vehicle is already {status_v.capitalize()}."
            }), 409

        data = request.get_json(force=True, silent=True) or {}

        def req_str(key):
            return str(data.get(key) or "").strip()

        def opt_money(key, default=0.0):
            raw = str(data.get(key) or "").strip()
            if not raw:
                return default
            try:
                return max(float(raw), 0.0)
            except (TypeError, ValueError):
                return default

        customer_name   = req_str("customer_name")
        customer_phone  = req_str("customer_phone")
        customer_id_no  = req_str("customer_identifier")
        customer_address = req_str("customer_address")

        if not customer_name:
            return jsonify({"success": False, "message": "Customer name is required."}), 400
        if not customer_phone:
            return jsonify({"success": False, "message": "Customer phone is required."}), 400
        if not customer_id_no:
            return jsonify({"success": False, "message": "Customer ID is required."}), 400

        # -- pricing
        _repair_row = conn.execute(
            "SELECT COALESCE(SUM(COALESCE(cost, 0)), 0) AS total FROM vehicle_repairs WHERE vehicle_id = ?",
            (vehicle_id,),
        ).fetchone()
        repair_cost = float((_repair_row[0] if _repair_row else None) or 0)

        selling_price    = opt_money("selling_price")
        discount_amount  = opt_money("discount_amount")
        gst_percent      = opt_money("gst_percent")
        advance_amount   = opt_money("advance_amount")
        payment_method   = req_str("payment_method") or "Cash"
        if payment_method not in {"Cash", "UPI", "Bank", "GPay", "Card"}:
            payment_method = "Cash"

        subtotal_amount  = round(selling_price, 2)
        taxable_amount   = round(max(subtotal_amount - discount_amount, 0.0), 2)
        gst_amount       = round(taxable_amount * gst_percent / 100.0, 2) if gst_percent > 0 else 0.0
        total_amount     = round(taxable_amount + gst_amount, 2)
        purchase_price   = float(row.get("purchase_price") or 0)
        purchase_total   = round(purchase_price + repair_cost, 2)

        delivery_date = req_str("delivery_date") or now_str()[:10]
        sale_code = generate_vehicle_sale_code(conn)
        now = now_str()

        # -- upsert customer
        try:
            customer_id = upsert_customer(
                conn,
                customer_name,
                customer_phone,
                f"Customer ID: {customer_id_no}",
                customer_address or None,
            )
        except ValueError as exc:
            return jsonify({"success": False, "message": str(exc)}), 400

        # -- create order row first (needed for FK)
        order_notes = (
            f"Vehicle Number: {row.get('vehicle_number') or ''}\n"
            f"Customer ID: {customer_id_no}\n"
            f"Payment method: {payment_method}"
        )
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO orders (
                customer_id, customer_display_id, notes,
                due_date, status, priority,
                advance_amount, discount_amount, total_amount, taxable_amount,
                gst_percent, gst_amount,
                cgst_percent, cgst_amount, sgst_percent, sgst_amount,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                customer_id,
                customer_display_id(customer_id),
                order_notes,
                delivery_date,
                "Sold",
                "Normal",
                advance_amount,
                discount_amount,
                total_amount,
                taxable_amount,
                gst_percent,
                gst_amount,
                gst_percent / 2,
                gst_amount / 2,
                gst_percent / 2,
                gst_amount / 2,
                now,
            ),
        )
        conn.commit()
        order_id = cur.lastrowid

        gallery_names = ",".join(
            n.strip()
            for n in str(row.get("vehicle_image_filenames") or "").split(",")
            if n.strip()
        )

        # -- create vehicle_sale_orders row
        cur.execute(
            """
            INSERT INTO vehicle_sale_orders (
                order_id, customer_id, sale_code,
                customer_name, customer_identifier, customer_phone, customer_address,
                vehicle_id, vehicle_name, vehicle_number,
                model_year, registration_no, owners,
                purchase_price, selling_price, repair_cost,
                subtotal_amount, purchase_total_cost,
                discount_amount, gst_percent, gst_amount,
                advance_amount, total_amount,
                payment_method, vehicle_image_filenames,
                created_at, updated_at
            ) VALUES (
                ?, ?, ?,
                ?, ?, ?, ?,
                ?, ?, ?,
                ?, ?, ?,
                ?, ?, ?,
                ?, ?,
                ?, ?, ?,
                ?, ?,
                ?, ?,
                ?, ?
            )
            """,
            (
                order_id, customer_id, sale_code,
                customer_name, customer_id_no, customer_phone, customer_address,
                vehicle_id, row.get("vehicle_name"), row.get("vehicle_number"),
                row.get("model_year"), row.get("registration_no"), row.get("owners"),
                purchase_price, selling_price, repair_cost,
                subtotal_amount, purchase_total,
                discount_amount, gst_percent, gst_amount,
                advance_amount, total_amount,
                payment_method, gallery_names,
                now, now,
            ),
        )

        # -- mark vehicle as Sold
        conn.execute(
            "UPDATE vehicles SET status = ?, updated_at = ? WHERE id = ?",
            ("Sold", now, vehicle_id),
        )
        conn.commit()
        sale_id = cur.lastrowid

        return jsonify({
            "success": True,
            "message": "Vehicle sold successfully.",
            "sale_code": sale_code,
            "sale_id": sale_id,
            "order_id": order_id,
            "total_amount": total_amount,
        }), 201

    except Exception as e:
        conn.rollback()
        return jsonify({"success": False, "message": f"Failed to record sale: {e}"}), 500
    finally:
        conn.close()


@app.route("/api/vehicles/<int:vehicle_id>/repairs", methods=["POST"])
@jwt_required()
def api_add_repair(vehicle_id):
    conn = get_db()
    try:
        data = request.get_json()

        repair_date = data.get("repair_date")
        description = data.get("description")
        amount = float(data.get("amount", 0))

        created_at = now_str()
        vehicle = conn.execute(
            """
            SELECT vehicle_name, vehicle_number
            FROM vehicles
            WHERE id = ?
            """,
            (vehicle_id,),
        ).fetchone()
        if not vehicle:
            return jsonify({
                "success": False,
                "message": "Vehicle not found."
            }), 404

        expense_id = upsert_repair_expense(
            conn,
            None,
            amount,
            vehicle["vehicle_name"],
            vehicle["vehicle_number"],
            created_at,
        )

        conn.execute(
            """
            INSERT INTO vehicle_repairs
            (vehicle_id, expense_id, repair_status, repair_date,
             description, cost, total_cost, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                vehicle_id,
                expense_id,
                "In-Progress",
                repair_date,
                description,
                amount,
                amount,
                created_at,
            ),
        )

        # Update vehicle status
        conn.execute(
            """
            UPDATE vehicles
            SET status = 'In Repair'
            WHERE id = ?
            """,
            (vehicle_id,),
        )

        check = conn.execute(
           """
           SELECT vehicle_name, vehicle_number, status
           FROM vehicles
           WHERE id = ?
           """,
           (vehicle_id,),
        ).fetchone()
        print("Vehicle after repair:", dict(check))
        print("STATUS AFTER REPAIR UPDATE:", dict(check))

        conn.commit()

        return jsonify({
            "success": True,
            "message": "Repair added successfully."
        })

    except Exception as e:
        conn.rollback()

        import traceback
        print("\n========== REPAIR ERROR ==========")
        traceback.print_exc()
        print("==================================\n")

        return jsonify({
            "success": False,
            "error": str(e)
        }), 500

    finally:
        conn.close()

@app.route("/api/vehicles/<int:vehicle_id>/rent", methods=["POST"])
@jwt_required()
def api_vehicle_rent(vehicle_id: int):
    """
    Mobile Rent Out Vehicle (used when business_mode == 'rental').

    JSON body fields:
      customer_name        (required)
      customer_phone       (required)
      customer_identifier  (required)
      customer_address     (optional)
      rate_type             (optional: daily/hourly/weekly, default daily)
      rate_amount            (required, decimal)
      duration_units         (required, decimal — number of days/hours/weeks booked)
      rental_start_date      (optional, YYYY-MM-DD, default today)
      rental_end_date        (optional, YYYY-MM-DD, default start + duration)
      security_deposit        (optional, decimal, default 0)
      discount_amount         (optional, decimal, default 0)
      gst_percent              (optional, decimal, default 0)
      advance_amount            (optional, decimal, default 0)
      payment_method            (optional: Cash/UPI/Bank/GPay/Card, default Cash)
    """
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT * FROM vehicles WHERE id = ?", (vehicle_id,)
        ).fetchone()
        if not row:
            return jsonify({"success": False, "message": "Vehicle not found."}), 404

        status_v = (row.get("status") or "available").strip().lower()
        if status_v in ("sold", "transferred", "rented"):
            return jsonify({
                "success": False,
                "message": f"Vehicle is already {status_v.capitalize()}."
            }), 409

        data = request.get_json(force=True, silent=True) or {}

        def req_str(key):
            return str(data.get(key) or "").strip()

        def opt_money(key, default=0.0):
            raw = str(data.get(key) or "").strip()
            if not raw:
                return default
            try:
                return max(float(raw), 0.0)
            except (TypeError, ValueError):
                return default

        customer_name   = req_str("customer_name")
        customer_phone  = req_str("customer_phone")
        customer_id_no  = req_str("customer_identifier")
        customer_address = req_str("customer_address")

        if not customer_name:
            return jsonify({"success": False, "message": "Customer name is required."}), 400
        if not customer_phone:
            return jsonify({"success": False, "message": "Customer phone is required."}), 400
        if not customer_id_no:
            return jsonify({"success": False, "message": "Customer ID is required."}), 400

        rate_type = req_str("rate_type").lower() or "daily"
        if rate_type not in {"hourly", "daily", "weekly"}:
            rate_type = "daily"

        rate_amount = opt_money("rate_amount")
        duration_units = opt_money("duration_units", 1.0) or 1.0
        if rate_amount <= 0:
            return jsonify({"success": False, "message": "Rate amount is required."}), 400

        rental_start_raw = req_str("rental_start_date") or now_str()[:10]
        try:
            rental_start_date = datetime.strptime(rental_start_raw, "%Y-%m-%d").date()
        except ValueError:
            rental_start_date = datetime.now().date()

        rental_end_raw = req_str("rental_end_date")
        if rental_end_raw:
            try:
                rental_end_date = datetime.strptime(rental_end_raw, "%Y-%m-%d").date()
            except ValueError:
                rental_end_date = rental_start_date + timedelta(days=max(int(duration_units), 1))
        else:
            if rate_type == "hourly":
                rental_end_date = rental_start_date
            else:
                days = duration_units * 7 if rate_type == "weekly" else duration_units
                rental_end_date = rental_start_date + timedelta(days=max(int(round(days)), 1))

        security_deposit = opt_money("security_deposit")
        discount_amount  = opt_money("discount_amount")
        gst_percent      = opt_money("gst_percent")
        advance_amount   = opt_money("advance_amount")
        payment_method   = req_str("payment_method") or "Cash"
        if payment_method not in {"Cash", "UPI", "Bank", "GPay", "Card"}:
            payment_method = "Cash"

        rental_amount    = round(rate_amount * duration_units, 2)
        subtotal_amount  = rental_amount
        taxable_amount   = round(max(subtotal_amount - discount_amount, 0.0), 2)
        gst_amount       = round(taxable_amount * gst_percent / 100.0, 2) if gst_percent > 0 else 0.0
        total_amount     = round(taxable_amount + gst_amount, 2)

        rental_code = generate_vehicle_rental_code(conn)
        now = now_str()

        try:
            customer_id = upsert_customer(
                conn,
                customer_name,
                customer_phone,
                f"Customer ID: {customer_id_no}",
                customer_address or None,
            )
        except ValueError as exc:
            return jsonify({"success": False, "message": str(exc)}), 400

        order_notes = (
            f"Vehicle Number: {row.get('vehicle_number') or ''}\n"
            f"Customer ID: {customer_id_no}\n"
            f"Payment method: {payment_method}"
        )
        cur = conn.cursor()
        cur.execute(
            """
            INSERT INTO orders (
                customer_id, customer_display_id, notes,
                due_date, status, priority,
                advance_amount, discount_amount, total_amount, taxable_amount,
                gst_percent, gst_amount,
                cgst_percent, cgst_amount, sgst_percent, sgst_amount,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                customer_id,
                customer_display_id(customer_id),
                order_notes,
                rental_end_date.isoformat(),
                "Rented",
                "Normal",
                advance_amount,
                discount_amount,
                total_amount,
                taxable_amount,
                gst_percent,
                gst_amount,
                gst_percent / 2,
                gst_amount / 2,
                gst_percent / 2,
                gst_amount / 2,
                now,
            ),
        )
        conn.commit()
        order_id = cur.lastrowid

        gallery_names = ",".join(
            n.strip()
            for n in str(row.get("vehicle_image_filenames") or "").split(",")
            if n.strip()
        )

        cur.execute(
            """
            INSERT INTO vehicle_rental_orders (
                order_id, customer_id, rental_code,
                customer_name, customer_identifier, customer_phone, customer_address,
                vehicle_id, vehicle_name, vehicle_number,
                model_year, registration_no, owners,
                rate_type, rate_amount, duration_units,
                rental_start_date, rental_end_date,
                rental_amount, security_deposit,
                discount_amount, gst_percent, gst_amount,
                advance_amount, total_amount,
                payment_method, status, vehicle_image_filenames,
                created_at, updated_at
            ) VALUES (
                ?, ?, ?,
                ?, ?, ?, ?,
                ?, ?, ?,
                ?, ?, ?,
                ?, ?, ?,
                ?, ?,
                ?, ?,
                ?, ?, ?,
                ?, ?,
                ?, ?, ?,
                ?, ?
            )
            """,
            (
                order_id, customer_id, rental_code,
                customer_name, customer_id_no, customer_phone, customer_address,
                vehicle_id, row.get("vehicle_name"), row.get("vehicle_number"),
                row.get("model_year"), row.get("registration_no"), row.get("owners"),
                rate_type, rate_amount, duration_units,
                rental_start_date.isoformat(), rental_end_date.isoformat(),
                rental_amount, security_deposit,
                discount_amount, gst_percent, gst_amount,
                advance_amount, total_amount,
                payment_method, "Active", gallery_names,
                now, now,
            ),
        )

        conn.execute(
            "UPDATE vehicles SET status = ?, updated_at = ? WHERE id = ?",
            ("Rented", now, vehicle_id),
        )
        conn.commit()
        rental_id = cur.lastrowid

        return jsonify({
            "success": True,
            "message": "Vehicle rented out successfully.",
            "rental_code": rental_code,
            "rental_id": rental_id,
            "order_id": order_id,
            "total_amount": total_amount,
            "rental_end_date": rental_end_date.isoformat(),
        }), 201

    except Exception as e:
        conn.rollback()
        return jsonify({"success": False, "message": f"Failed to record rental: {e}"}), 500
    finally:
        conn.close()


@app.route("/api/rentals/<int:rental_id>/return", methods=["POST"])
@jwt_required()
def api_rental_return(rental_id: int):
    """
    Mobile Return Rented Vehicle.

    JSON body fields:
      actual_return_date  (optional, YYYY-MM-DD, default today)
      late_fee             (optional, decimal, default auto-calculated from overdue days)
      extra_charges          (optional, decimal, default 0)
      deposit_refunded         (optional, decimal, default full security_deposit)
    """
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT * FROM vehicle_rental_orders WHERE id = ?", (rental_id,)
        ).fetchone()
        if not row:
            return jsonify({"success": False, "message": "Rental not found."}), 404
        if (row.get("status") or "").strip().lower() != "active":
            return jsonify({"success": False, "message": "This rental is already closed."}), 409

        data = request.get_json(force=True, silent=True) or {}

        return_raw = str(data.get("actual_return_date") or "").strip() or now_str()[:10]
        try:
            actual_return_date = datetime.strptime(return_raw, "%Y-%m-%d").date()
        except ValueError:
            actual_return_date = datetime.now().date()

        expected_end = row.get("rental_end_date")
        if isinstance(expected_end, str):
            try:
                expected_end = datetime.strptime(expected_end[:10], "%Y-%m-%d").date()
            except ValueError:
                expected_end = None

        overdue_days = 0
        if expected_end and actual_return_date > expected_end:
            overdue_days = (actual_return_date - expected_end).days

        rate_amount = float(row.get("rate_amount") or 0)
        auto_late_fee = round(overdue_days * rate_amount, 2) if overdue_days else 0.0

        def opt_money(key, default):
            raw = str(data.get(key) or "").strip()
            if not raw:
                return default
            try:
                return max(float(raw), 0.0)
            except (TypeError, ValueError):
                return default

        late_fee = opt_money("late_fee", auto_late_fee)
        extra_charges = opt_money("extra_charges", 0.0)
        deposit_refunded = opt_money("deposit_refunded", float(row.get("security_deposit") or 0))

        final_total = round(float(row.get("total_amount") or 0) + late_fee + extra_charges, 2)
        now = now_str()

        conn.execute(
            """
            UPDATE vehicle_rental_orders
            SET actual_return_date = ?, late_fee = ?, extra_charges = ?,
                deposit_refunded = ?, total_amount = ?, status = 'Returned', updated_at = ?
            WHERE id = ?
            """,
            (actual_return_date.isoformat(), late_fee, extra_charges, deposit_refunded, final_total, now, rental_id),
        )
        conn.execute(
            "UPDATE vehicles SET status = 'Available', updated_at = ? WHERE id = ?",
            (now, row.get("vehicle_id")),
        )
        conn.commit()

        return jsonify({
            "success": True,
            "message": "Vehicle returned successfully.",
            "rental_id": rental_id,
            "overdue_days": overdue_days,
            "late_fee": late_fee,
            "extra_charges": extra_charges,
            "deposit_refunded": deposit_refunded,
            "total_amount": final_total,
        })

    except Exception as e:
        conn.rollback()
        return jsonify({"success": False, "message": f"Failed to process return: {e}"}), 500
    finally:
        conn.close()


def _serialize_rental_row(row):
    """Shared shaping for /api/rentals list + detail rows."""
    gallery_source = row.get("vehicle_gallery") or row.get("vehicle_image_filenames") or ""
    gallery_images = [
        build_upload_url(f"uploads/vehicles/{name.strip()}")
        for name in str(gallery_source).split(",")
        if name.strip()
    ]

    status_raw = (row.get("status") or "Active").strip()
    end_date = row.get("rental_end_date")
    is_overdue = False
    if status_raw.lower() == "active" and end_date:
        end_val = end_date if not isinstance(end_date, str) else end_date[:10]
        try:
            end_parsed = end_val if hasattr(end_val, "year") else datetime.strptime(end_val, "%Y-%m-%d").date()
            is_overdue = datetime.now().date() > end_parsed
        except (ValueError, TypeError):
            is_overdue = False

    return {
        "id": row["id"],
        "rental_code": row.get("rental_code") or "-",
        "order_id": row.get("order_id"),
        "vehicle_id": row.get("vehicle_id"),
        "vehicle_name": row.get("vehicle_name") or "-",
        "vehicle_number": row.get("vehicle_number") or "-",
        "model_year": str(row.get("model_year") or "-"),
        "registration_no": row.get("registration_no") or "-",
        "owners": row.get("owners"),
        "rate_type": row.get("rate_type") or "daily",
        "rate_amount": float(row.get("rate_amount") or 0),
        "duration_units": float(row.get("duration_units") or 0),
        "rental_start_date": str(row.get("rental_start_date") or ""),
        "rental_end_date": str(row.get("rental_end_date") or ""),
        "actual_return_date": str(row.get("actual_return_date") or ""),
        "rental_amount": float(row.get("rental_amount") or 0),
        "security_deposit": float(row.get("security_deposit") or 0),
        "deposit_refunded": float(row.get("deposit_refunded") or 0),
        "late_fee": float(row.get("late_fee") or 0),
        "extra_charges": float(row.get("extra_charges") or 0),
        "discount_amount": float(row.get("discount_amount") or 0),
        "gst_percent": float(row.get("gst_percent") or 0),
        "gst_amount": float(row.get("gst_amount") or 0),
        "advance_amount": float(row.get("advance_amount") or 0),
        "total_amount": float(row.get("total_amount") or 0),
        "payment_method": row.get("payment_method") or "-",
        "status": status_raw,
        "is_overdue": is_overdue,
        "customer_name": row.get("customer_name") or "-",
        "customer_phone": row.get("customer_phone") or "-",
        "customer_identifier": row.get("customer_identifier") or "-",
        "customer_address": row.get("customer_address") or "-",
        "created_at": str(row.get("created_at") or ""),
        "gallery_images": gallery_images,
    }


@app.route("/api/rentals", methods=["GET"])
@jwt_required()
def api_rentals():
    """
    Mobile Rentals listing.

    Query params:
      q          : search text (vehicle name / number / customer name / phone)
      status     : "", "all", "active", "returned"
      from_date  : YYYY-MM-DD (filters on rental created_at)
      to_date    : YYYY-MM-DD
    """
    search = (request.args.get("q") or "").strip()
    status_filter = (request.args.get("status") or "").strip().lower()
    from_date = (request.args.get("from_date") or "").strip()
    to_date = (request.args.get("to_date") or "").strip()

    conn = get_db()
    try:
        params: list = []

        query = """
            SELECT
                vro.*,
                v.vehicle_image_filenames AS vehicle_gallery
            FROM vehicle_rental_orders vro
            LEFT JOIN vehicles v ON v.id = vro.vehicle_id
            WHERE 1=1
        """

        if search:
            query += """ AND (
                vro.vehicle_name LIKE ? OR vro.vehicle_number LIKE ?
                OR vro.customer_name LIKE ? OR vro.customer_phone LIKE ?
            )"""
            like = f"%{search}%"
            params.extend([like, like, like, like])

        if status_filter and status_filter != "all":
            query += " AND LOWER(vro.status) = ?"
            params.append(status_filter)

        if from_date:
            query += " AND date(vro.created_at) >= ?"
            params.append(from_date)

        if to_date:
            query += " AND date(vro.created_at) <= ?"
            params.append(to_date)

        query += " ORDER BY ISNULL(vro.updated_at, vro.created_at) DESC, vro.id DESC"

        rows = conn.execute(query, tuple(params)).fetchall()
        result = [_serialize_rental_row(row) for row in rows]

        return jsonify({"success": True, "rentals": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e), "rentals": []}), 500
    finally:
        conn.close()


