@app.route("/api/sales", methods=["GET"])
@jwt_required()
def api_sales():
    """
    Mobile Sales listing.
    Lists recorded vehicle sale orders (vehicle_sale_orders), each carrying
    both the vehicle details and the buyer (customer) details together.

    Query params:
      q          : search text (vehicle name / number / customer name / phone)
      from_date  : YYYY-MM-DD (filters on sale created_at)
      to_date    : YYYY-MM-DD
    """
    search = (request.args.get("q") or "").strip()
    from_date = (request.args.get("from_date") or "").strip()
    to_date = (request.args.get("to_date") or "").strip()

    conn = get_db()
    try:
        params: list = []

        query = """
            SELECT
                vso.*,
                o.due_date AS delivery_date,
                v.vehicle_image_filenames AS vehicle_gallery
            FROM vehicle_sale_orders vso
            LEFT JOIN orders o ON o.id = vso.order_id
            LEFT JOIN vehicles v ON v.id = vso.vehicle_id
            WHERE 1=1
        """

        if search:
            query += """ AND (
                vso.vehicle_name LIKE ? OR vso.vehicle_number LIKE ?
                OR vso.customer_name LIKE ? OR vso.customer_phone LIKE ?
            )"""
            like = f"%{search}%"
            params.extend([like, like, like, like])

        if from_date:
            query += " AND date(vso.created_at) >= ?"
            params.append(from_date)

        if to_date:
            query += " AND date(vso.created_at) <= ?"
            params.append(to_date)

        query += " ORDER BY ISNULL(vso.updated_at, vso.created_at) DESC, vso.id DESC"

        rows = conn.execute(query, tuple(params)).fetchall()

        result = [_serialize_sale_row(row) for row in rows]

        return jsonify({"success": True, "sales": result})
    except Exception as e:
        return jsonify({"success": False, "error": str(e), "sales": []}), 500
    finally:
        conn.close()


