@app.route("/api/sales/<int:sale_id>", methods=["PUT"])
@jwt_required()
def api_sale_update(sale_id: int):
    """
    Mobile Edit Sale.
    Accepts a JSON body; any key present is updated, others are left as-is.
    When selling_price / discount_amount / gst_percent change, the
    dependent totals (subtotal, taxable, gst_amount, total_amount) are
    recomputed the same way api_vehicle_sell() computes them originally.
    """
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT * FROM vehicle_sale_orders WHERE id = ?", (sale_id,)
        ).fetchone()
        if not row:
            return jsonify({"success": False, "error": "Sale not found"}), 404

        data = request.get_json(force=True, silent=True) or {}

        def to_str(key):
            return str(data.get(key)).strip() if key in data else None

        def to_money(key):
            if key not in data:
                return None
            raw = str(data.get(key) or "").strip()
            if not raw:
                return 0.0
            try:
                return max(float(raw), 0.0)
            except (TypeError, ValueError):
                return None

        customer_name = to_str("customer_name")
        if customer_name is not None and not customer_name:
            return jsonify({"success": False, "message": "Customer name is required."}), 400

        customer_phone = to_str("customer_phone")
        customer_address = to_str("customer_address")
        payment_method = to_str("payment_method")
        if payment_method is not None and payment_method not in {"Cash", "UPI", "Bank", "GPay", "Card"}:
            payment_method = payment_method or "Cash"

        delivery_date = to_str("delivery_date")

        selling_price = to_money("selling_price")
        discount_amount = to_money("discount_amount")
        gst_percent = to_money("gst_percent")
        advance_amount = to_money("advance_amount")

        for money_field in ("selling_price", "discount_amount", "gst_percent", "advance_amount"):
            if money_field in data and to_money(money_field) is None:
                return jsonify({"success": False, "message": f"{money_field} must be a number."}), 400

        set_clauses: list = []
        params: list = []

        if customer_name is not None:
            set_clauses.append("customer_name = ?")
            params.append(customer_name)
        if customer_phone is not None:
            set_clauses.append("customer_phone = ?")
            params.append(customer_phone)
        if customer_address is not None:
            set_clauses.append("customer_address = ?")
            params.append(customer_address)
        if payment_method is not None:
            set_clauses.append("payment_method = ?")
            params.append(payment_method)

        needs_recalc = any(f in data for f in ("selling_price", "discount_amount", "gst_percent"))
        if needs_recalc:
            repair_cost = float(row.get("repair_cost") or 0)
            purchase_price = float(row.get("purchase_price") or 0)
            new_selling_price = selling_price if selling_price is not None else float(row.get("selling_price") or 0)
            new_discount = discount_amount if discount_amount is not None else float(row.get("discount_amount") or 0)
            new_gst_percent = gst_percent if gst_percent is not None else float(row.get("gst_percent") or 0)

            subtotal_amount = round(new_selling_price, 2)
            taxable_amount = round(max(subtotal_amount - new_discount, 0.0), 2)
            gst_amount = round(taxable_amount * new_gst_percent / 100.0, 2) if new_gst_percent > 0 else 0.0
            total_amount = round(taxable_amount + gst_amount, 2)
            purchase_total_cost = round(purchase_price + repair_cost, 2)

            set_clauses += [
                "selling_price = ?", "discount_amount = ?", "gst_percent = ?",
                "gst_amount = ?", "subtotal_amount = ?", "total_amount = ?",
                "purchase_total_cost = ?",
            ]
            params += [
                new_selling_price, new_discount, new_gst_percent,
                gst_amount, subtotal_amount, total_amount, purchase_total_cost,
            ]

        if advance_amount is not None:
            set_clauses.append("advance_amount = ?")
            params.append(advance_amount)

        if not set_clauses:
            return jsonify({"success": False, "message": "No fields to update."}), 400

        now = now_str()
        set_clauses.append("updated_at = ?")
        params.append(now)
        params.append(sale_id)

        conn.execute(
            f"UPDATE vehicle_sale_orders SET {', '.join(set_clauses)} WHERE id = ?",
            tuple(params),
        )

        if delivery_date and row.get("order_id"):
            conn.execute(
                "UPDATE orders SET due_date = ? WHERE id = ?",
                (delivery_date, row.get("order_id")),
            )

        conn.commit()

        updated_row = conn.execute(
            """
            SELECT
                vso.*,
                o.due_date AS delivery_date,
                v.vehicle_image_filenames AS vehicle_gallery,
                v.purchase_mode AS vehicle_purchase_mode,
                v.purchase_customer_name AS vehicle_purchase_customer_name,
                v.purchase_customer_phone AS vehicle_purchase_customer_phone,
                v.purchase_customer_address AS vehicle_purchase_customer_address,
                v.purchase_agent_name AS vehicle_purchase_agent_name,
                v.purchase_agent_phone AS vehicle_purchase_agent_phone,
                v.purchase_agent_address AS vehicle_purchase_agent_address,
                v.purchase_co_name AS vehicle_purchase_co_name,
                v.purchase_co_phone AS vehicle_purchase_co_phone,
                v.purchase_co_address AS vehicle_purchase_co_address
            FROM vehicle_sale_orders vso
            LEFT JOIN orders o ON o.id = vso.order_id
            LEFT JOIN vehicles v ON v.id = vso.vehicle_id
            WHERE vso.id = ?
            """,
            (sale_id,),
        ).fetchone()

        return jsonify({
            "success": True,
            "message": "Sale updated successfully.",
            "sale": _serialize_sale_row(updated_row),
        })
    except Exception as e:
        conn.rollback()
        traceback.print_exc()
        return jsonify({"success": False, "message": f"Failed to update sale: {e}"}), 500
    finally:
        conn.close()


@app.route("/api/sales/<int:sale_id>/id-proof", methods=["POST"])
@jwt_required()
def api_sale_id_proof(sale_id: int):
    """
    Mobile — upload/replace the buyer's Customer ID Proof for a sale.

    Sent as multipart/form-data (not JSON) because it carries a file:
      customer_id_proof_file  (required, image or pdf)
      customer_id_proof_ref   (optional, YYYY-MM-DD reference date)

    This mirrors the upload the web "Edit Sale" screen already does, so a
    sale created on mobile (which the JSON /sell endpoint can't attach a
    file to) can still get its ID proof attached afterwards.
    """
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT * FROM vehicle_sale_orders WHERE id = ?", (sale_id,)
        ).fetchone()
        if not row:
            return jsonify({"success": False, "message": "Sale not found."}), 404

        upload = request.files.get("customer_id_proof_file")
        if not upload or not getattr(upload, "filename", ""):
            return jsonify({"success": False, "message": "Choose an ID proof file to upload."}), 400

        filename = save_vehicle_sale_upload(
            upload,
            fallback=row.get("customer_id_proof_filename"),
            customer_name=row.get("customer_name"),
            doc_label="id proof",
        )
        if not filename:
            return jsonify({"success": False, "message": "Unsupported file. Please upload an image or PDF."}), 400

        ref_raw = (request.form.get("customer_id_proof_ref") or "").strip()[:10]
        ref_value = ref_raw if ref_raw and date_only(ref_raw) != "-" else row.get("customer_id_proof_ref")

        conn.execute(
            """
            UPDATE vehicle_sale_orders
            SET customer_id_proof_filename = ?, customer_id_proof_ref = ?, updated_at = ?
            WHERE id = ?
            """,
            (filename, ref_value, now_str(), sale_id),
        )
        conn.commit()

        return jsonify({
            "success": True,
            "message": "Customer ID proof uploaded.",
            "customer_id_proof_filename": filename,
            "customer_id_proof_url": build_upload_url(f"uploads/vehicle_sales/{filename}"),
        })
    except Exception as e:
        conn.rollback()
        traceback.print_exc()
        return jsonify({"success": False, "message": f"Failed to upload ID proof: {e}"}), 500
    finally:
        conn.close()


