def _serialize_sale_row(row):
    """Shared shaping for /api/sales list + detail rows."""
    gallery_source = row.get("vehicle_gallery") or row.get("vehicle_image_filenames") or ""
    print("vehicle_gallery =", row.get("vehicle_gallery"))
    print("vehicle_image_filenames =", row.get("vehicle_image_filenames"))
    print("gallery_source =", gallery_source)
    gallery_images = [
        build_upload_url(f"uploads/vehicles/{name.strip()}")
        for name in str(gallery_source).split(",")
        if name.strip()
    ]

    return {
        "id": row["id"],
        "sale_code": row.get("sale_code") or "-",
        "order_id": row.get("order_id"),
        "vehicle_id": row.get("vehicle_id"),
        "vehicle_name": row.get("vehicle_name") or "-",
        "vehicle_number": row.get("vehicle_number") or "-",
        "model_year": str(row.get("model_year") or "-"),
        "registration_no": row.get("registration_no") or "-",
        "owners": row.get("owners"),
        "purchase_price": float(row.get("purchase_price") or 0),
        "selling_price": float(row.get("selling_price") or 0),
        "repair_cost": float(row.get("repair_cost") or 0),
        "purchase_total_cost": float(
            row.get("purchase_total_cost")
            or ((row.get("purchase_price") or 0) + (row.get("repair_cost") or 0))
        ),
        # Where the vehicle was originally bought from (owner/customer, agent, or company)
        "purchase_mode": row.get("vehicle_purchase_mode") or "",
        "purchase_customer_name": row.get("vehicle_purchase_customer_name") or "",
        "purchase_customer_phone": row.get("vehicle_purchase_customer_phone") or "",
        "purchase_customer_address": row.get("vehicle_purchase_customer_address") or "",
        "purchase_agent_name": row.get("vehicle_purchase_agent_name") or "",
        "purchase_agent_phone": row.get("vehicle_purchase_agent_phone") or "",
        "purchase_agent_address": row.get("vehicle_purchase_agent_address") or "",
        "purchase_co_name": row.get("vehicle_purchase_co_name") or "",
        "purchase_co_phone": row.get("vehicle_purchase_co_phone") or "",
        "purchase_co_address": row.get("vehicle_purchase_co_address") or "",
        "subtotal_amount": float(row.get("subtotal_amount") or 0),
        "discount_amount": float(row.get("discount_amount") or 0),
        "gst_percent": float(row.get("gst_percent") or 0),
        "gst_amount": float(row.get("gst_amount") or 0),
        "advance_amount": float(row.get("advance_amount") or 0),
        "total_amount": float(row.get("total_amount") or 0),
        "payment_method": row.get("payment_method") or "-",
        "customer_name": row.get("customer_name") or "-",
        "customer_phone": row.get("customer_phone") or "-",
        "customer_identifier": row.get("customer_identifier") or "-",
        "customer_address": row.get("customer_address") or "-",
        "delivery_date": str(row.get("delivery_date") or ""),
        "created_at": str(row.get("created_at") or ""),
        "gallery_images": gallery_images,
        "customer_id_proof_filename": row.get("customer_id_proof_filename") or "",
        "customer_id_proof_url": (
            build_upload_url(f"uploads/vehicle_sales/{row.get('customer_id_proof_filename')}")
            if row.get("customer_id_proof_filename") else None
        ),
        "customer_id_proof_ref": date_only(row.get("customer_id_proof_ref")) if row.get("customer_id_proof_ref") else "",
        "customer_photo_filename": row.get("customer_photo_filename") or "",
        "customer_photo_url": (
            build_upload_url(f"uploads/vehicle_sales/{row.get('customer_photo_filename')}")
            if row.get("customer_photo_filename") else None
        ),
        "customer_with_bike_photo_filename": row.get("customer_with_bike_photo_filename") or "",
        "customer_with_bike_photo_url": (
            build_upload_url(f"uploads/vehicle_sales/{row.get('customer_with_bike_photo_filename')}")
            if row.get("customer_with_bike_photo_filename") else None
        ),
    }

        
