@app.route("/api/expenses", methods=["GET"])
@jwt_required()
def api_expenses():
    """
    Mobile expenses listing.
    Mirrors the web /expense dashboard (misc expenses + salary payments).

    Query params:
      kind       : "" (default, all) | "expense" | "salary"
      q          : search text (expense name / expense number)
      from_date  : YYYY-MM-DD
      to_date    : YYYY-MM-DD
    """
    kind = (request.args.get("kind") or "").strip().lower()
    if kind not in {"", "expense", "salary", "repair"}:
        kind = ""

    search = (request.args.get("q") or "").strip()
    from_date = (request.args.get("from_date") or "").strip()
    to_date = (request.args.get("to_date") or "").strip()

    conn = get_db()
    try:
        ensure_expenses_category_column(conn)
        ensure_expense_categories_table(conn)

        params: list = []

        query = """
            SELECT
            e.id,
            e.expense_no,
            e.expense_name,
            e.amount,
            e.category,
            e.created_at,

            s.id AS salary_id,
            s.staff_no,
            s.shift_no,
            s.salary_amount,

            vr.id AS repair_id,
            vr.repair_date,
            vr.description,
            v.vehicle_name,
            v.vehicle_number

        FROM expenses e

        LEFT JOIN salaries s
            ON s.expense_id = e.id

        LEFT JOIN vehicle_repairs vr
            ON vr.expense_id = e.id

        LEFT JOIN vehicles v
            ON v.id = vr.vehicle_id

        WHERE 1=1
"""

        if kind == "salary":
            query += " AND s.id IS NOT NULL"
        elif kind == "repair":
            query += " AND vr.id IS NOT NULL"
        elif kind == "expense":
            query += " AND s.id IS NULL AND vr.id IS NULL"

        if search:
            query += " AND (e.expense_name LIKE ? OR e.expense_no LIKE ?)"
            params.extend([f"%{search}%", f"%{search}%"])

        if from_date:
            query += " AND date(e.created_at) >= ?"
            params.append(from_date)

        if to_date:
            query += " AND date(e.created_at) <= ?"
            params.append(to_date)

        query += " ORDER BY e.created_at DESC, e.id DESC"

        rows = conn.execute(query, tuple(params)).fetchall()

        result = []
        for row in rows:
            print("RAW SALARY ROW:", dict(row))
            is_salary = row["salary_id"] is not None
            is_repair = row["repair_id"] is not None
            result.append({
                "id": row["id"],
                "expense_no": row["expense_no"] or "-",
                "expense_name": row["expense_name"] or "-",
                "amount": float(row["amount"] or 0),
                "category": row["category"] or None,
                "created_at": str(row["created_at"] or ""),
                "date": str(row["created_at"] or ""),
                "is_salary": is_salary,
                "is_repair": is_repair,
                "staff_no": row["staff_no"] if is_salary else None,
                "shift_no": row["shift_no"] if is_salary else None,
                "salary_amount": float(row["salary_amount"] or 0) if is_salary else None,
                "vehicle_name": row["vehicle_name"],
                "vehicle_number": row["vehicle_number"],
                "repair_date": str(row["repair_date"] or ""),
                "reasonForRepair": row["description"],
            })

        total_amount = sum(r["amount"] for r in result)

        for r in result:
            print(r)

        return jsonify({
            "success": True,
            "kind": kind or "all",
            "expenses": result,
            "total_amount": total_amount,
        })
    except Exception as e:
        return jsonify({"success": False, "error": str(e), "expenses": []}), 500
    finally:
        conn.close()


@app.route("/api/expenses", methods=["POST"])
@jwt_required()
def api_expense_add():
    """
    Mobile Add Expense.

    JSON body fields:
      is_salary       (optional bool, default false)

      -- when is_salary is false --
      expense_name    (required)
      expense_amount  (required, decimal)

      -- when is_salary is true --
      staff_no        (required, tailor id or tailor_code)
      salary_amount   (required, decimal)
      shift_no        (optional, default "-")
    """
    data = request.get_json(force=True, silent=True) or {}

    def req_str(key):
        return str(data.get(key) or "").strip()

    is_salary = bool(data.get("is_salary")) or req_str("is_salary") in {"1", "true", "True"}
    category_input = req_str("category")

    conn = get_db()
    try:
        ensure_expenses_category_column(conn)
        ensure_expense_categories_table(conn)

        created_at = now_str()
        staff_row = None

        if is_salary:
            staff_no = req_str("staff_no")
            salary_amount_raw = req_str("salary_amount")
            shift_no = req_str("shift_no") or "-"

            if not staff_no:
                return jsonify({"success": False, "message": "Staff is required for salary payment."}), 400
            if not salary_amount_raw:
                return jsonify({"success": False, "message": "Salary amount is required."}), 400

            try:
                final_amount = max(float(salary_amount_raw), 0.0)
            except (TypeError, ValueError):
                return jsonify({"success": False, "message": "Salary amount must be a number."}), 400

            staff_row = conn.execute(
                """
                SELECT TOP 1 tailor_code, name, phone, role, status
                FROM tailors
                WHERE CAST(id AS NVARCHAR(100)) = ? OR tailor_code = ?
                ORDER BY id DESC
                """,
                (staff_no, staff_no),
            ).fetchone()
            if not staff_row:
                return jsonify({"success": False, "message": "Selected staff was not found."}), 404

            expense_name = f"Salary - {str(staff_row['name'] or staff_no).strip()}"
        else:
            expense_name = req_str("expense_name")
            expense_amount_raw = req_str("expense_amount")

            if not expense_name:
                return jsonify({"success": False, "message": "Expense name is required."}), 400
            if not expense_amount_raw:
                return jsonify({"success": False, "message": "Expense amount is required."}), 400

            try:
                final_amount = max(float(expense_amount_raw), 0.0)
            except (TypeError, ValueError):
                return jsonify({"success": False, "message": "Expense amount must be a number."}), 400

        expense_id, expense_no = create_expense_record(
            conn,
            expense_name,
            final_amount,
            created_at,
            category=(category_input if not is_salary else None),
        )
        if not is_salary and category_input:
            add_expense_category_if_missing(conn, category_input)

        if is_salary:
            print("=== SALARY INSERT DEBUG ===")
            print("expense_id:", expense_id)
            print("staff_no:", staff_no)
            print("shift_no:", shift_no)
            print("final_amount:", final_amount)
            cur = conn.cursor()
            cur.execute(
                """
                INSERT INTO salaries (
                    expense_id, staff_no, shift_no, salary_amount, created_at
                )
                VALUES (?, ?, ?, ?, ?)
                """,
                (expense_id, staff_no, shift_no, final_amount, created_at),
            )

        conn.commit()

        return jsonify({
            "success": True,
            "message": "Expense recorded successfully.",
            "expense": {
                "id": expense_id,
                "expense_no": expense_no,
                "expense_name": expense_name,
                "amount": final_amount,
                "category": (category_input if not is_salary else None) or None,
                "created_at": created_at,
                "date": created_at,
                "is_salary": is_salary,
                "is_repair": False,
                "staff_no": staff_no if is_salary else None,
            },
        }), 201

    except Exception as e:
        conn.rollback()
        return jsonify({"success": False, "message": f"Failed to record expense: {e}"}), 500
    finally:
        conn.close()

@app.route("/api/expenses/<int:expense_id>", methods=["PUT"])
@jwt_required()
def api_expense_update(expense_id: int):
    """
    Mobile Edit Expense.
    Works for plain expenses AND salary payments — if the expense is
    linked to a salaries row, salary_amount is kept in sync with the new
    amount (mirrors the web /expense/<id>/edit route). Editing a
    repair-linked expense is intentionally not supported here (the
    mobile app hides Edit for repair rows); such rows are rejected.

    JSON body fields:
      expense_name  (required for plain expenses; ignored for salaries —
                     the salary's expense_name always tracks the staff name)
      amount        (required, decimal)
    """
    conn = get_db()
    try:
        expense = conn.execute(
            "SELECT * FROM expenses WHERE id = ?", (expense_id,)
        ).fetchone()
        if not expense:
            return jsonify({"success": False, "message": "Expense not found."}), 404

        salary = conn.execute(
            "SELECT * FROM salaries WHERE expense_id = ?", (expense_id,)
        ).fetchone()
        repair = conn.execute(
            "SELECT id FROM vehicle_repairs WHERE expense_id = ?", (expense_id,)
        ).fetchone()

        if repair:
            return jsonify({
                "success": False,
                "message": "Repair expenses can't be edited here — edit the repair instead.",
            }), 400

        data = request.get_json(force=True, silent=True) or {}

        amount_raw = str(data.get("amount") or "").strip()
        if not amount_raw:
            return jsonify({"success": False, "message": "Amount is required."}), 400
        try:
            amount = max(float(amount_raw), 0.0)
        except (TypeError, ValueError):
            return jsonify({"success": False, "message": "Amount must be a number."}), 400

        if salary:
            expense_name = expense["expense_name"]
        else:
            expense_name = str(data.get("expense_name") or "").strip()
            if not expense_name:
                return jsonify({"success": False, "message": "Expense name is required."}), 400

        conn.execute(
            "UPDATE expenses SET expense_name = ?, amount = ? WHERE id = ?",
            (expense_name, amount, expense_id),
        )
        if salary:
            conn.execute(
                "UPDATE salaries SET salary_amount = ? WHERE expense_id = ?",
                (amount, expense_id),
            )
        conn.commit()

        refreshed = conn.execute(
            "SELECT * FROM expenses WHERE id = ?", (expense_id,)
        ).fetchone()
        refreshed_salary = conn.execute(
            "SELECT * FROM salaries WHERE expense_id = ?", (expense_id,)
        ).fetchone()

        return jsonify({
            "success": True,
            "message": "Expense updated successfully.",
            "expense": {
                "id": refreshed["id"],
                "expense_no": refreshed["expense_no"] or "-",
                "expense_name": refreshed["expense_name"] or "-",
                "amount": float(refreshed["amount"] or 0),
                "created_at": str(refreshed["created_at"] or ""),
                "date": str(refreshed["created_at"] or ""),
                "is_salary": bool(refreshed_salary),
                "is_repair": False,
                "staff_no": refreshed_salary["staff_no"] if refreshed_salary else None,
                "shift_no": refreshed_salary["shift_no"] if refreshed_salary else None,
                "salary_amount": float(refreshed_salary["salary_amount"] or 0) if refreshed_salary else None,
            },
        })
    except Exception as e:
        conn.rollback()
        traceback.print_exc()
        return jsonify({"success": False, "message": f"Failed to update expense: {e}"}), 500
    finally:
        conn.close()


@app.route("/api/dashboard/search")
def api_dashboard_search():
    q = (request.args.get("q") or "").strip()
    from_date = (request.args.get("from_date") or "").strip()
    to_date = (request.args.get("to_date") or "").strip()
    if not q:
        return jsonify({"results": []})

    conn = get_db()
    try:
        results = build_dashboard_search_results(
            conn,
            q,
            from_date=from_date,
            to_date=to_date,
        )
        return jsonify({"results": results})
    except Exception as e:
        return jsonify({"error": str(e), "results": []}), 500
    finally:
        conn.close()


@app.route("/api/dashboard")
def api_dashboard():
    conn = get_db()
    try:
        today_iso = datetime.now().date().isoformat()

        # ── Date-range filter (From/To pickers in the app) ──
        from_date = (request.args.get("from_date") or request.args.get("fromDate") or "").strip()
        to_date = (request.args.get("to_date") or request.args.get("toDate") or "").strip()

        def _is_valid_iso_date(value: str) -> bool:
            try:
                datetime.strptime(value, "%Y-%m-%d")
                return True
            except ValueError:
                return False

        if from_date and not _is_valid_iso_date(from_date):
            from_date = ""
        if to_date and not _is_valid_iso_date(to_date):
            to_date = ""
        if from_date and to_date and from_date > to_date:
            from_date, to_date = to_date, from_date

        date_filter_active = bool(from_date and to_date)

        def q(sql, params=()):
            try:
                row = conn.execute(sql, params).fetchone()
                if row is None:
                    return 0
                return row[0]
            except Exception:
                return 0

        # Vehicles are dated by purchase_date (fallback created_at).
        vehicle_date_clause = " AND date(COALESCE(purchase_date, created_at)) BETWEEN ? AND ?"
        vehicle_date_params = (from_date, to_date) if date_filter_active else ()
        vdc = vehicle_date_clause if date_filter_active else ""

        total_vehicles = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE 1=1" + vdc, vehicle_date_params) or 0)
        available = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE LOWER(COALESCE(status,'available'))='available'" + vdc, vehicle_date_params) or 0)
        sold_count = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE LOWER(COALESCE(status,''))='sold'" + vdc, vehicle_date_params) or 0)
        rented_count = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE LOWER(COALESCE(status,''))='rented'" + vdc, vehicle_date_params) or 0)
        under_repair = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE REPLACE(REPLACE(LOWER(COALESCE(status,'available')),'-','_'),' ','_') IN ('in_repair','inrepair','repair','under_repair')" + vdc, vehicle_date_params) or 0)
        ready_to_sale = int(q("SELECT COUNT(*) AS c FROM vehicles WHERE LOWER(COALESCE(status,'available'))='available'" + vdc, vehicle_date_params) or 0)

        purchase_total = float(q("SELECT COALESCE(SUM(COALESCE(purchase_price,0)),0) AS s FROM vehicles WHERE 1=1" + vdc, vehicle_date_params) or 0)

        expenses_date_clause = " AND date(created_at) BETWEEN ? AND ?"
        edc = expenses_date_clause if date_filter_active else ""
        expenses_date_params = (from_date, to_date) if date_filter_active else ()

        expenses_total = float(q("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE 1=1" + edc, expenses_date_params) or 0)

        repair_sql = "SELECT COALESCE(SUM(amount), 0) FROM expenses WHERE LOWER(TRIM(expense_name)) LIKE 'repair%'" + edc
        repair_cost = float(conn.execute(repair_sql, expenses_date_params).fetchone()[0] or 0)

        rental_mode = is_rental_mode()

        if rental_mode:
            rental_sql = """
                SELECT COUNT(*) AS total_sales,
                       COALESCE(SUM(COALESCE(vro.total_amount,0)),0) AS total_revenue
                FROM vehicle_rental_orders vro
                WHERE 1=1
            """ + (" AND date(vro.created_at) BETWEEN ? AND ?" if date_filter_active else "")
            sales_row = conn.execute(rental_sql, vehicle_date_params).fetchone()
        else:
            sale_sql = """
                SELECT COUNT(*) AS total_sales,
                       COALESCE(SUM(COALESCE(vso.total_amount,0)),0) AS total_revenue,
                       COALESCE(SUM(COALESCE(v.purchase_price,0)),0) AS total_purchase,
                       COALESCE(SUM(COALESCE(vso.repair_cost,0)),0) AS total_repair
                FROM vehicle_sale_orders vso
                JOIN vehicles v ON v.id=vso.vehicle_id
                LEFT JOIN orders o ON o.id=vso.order_id
                WHERE vso.order_id IS NOT NULL
                  AND LOWER(COALESCE(o.status,'in-progress'))<>'cancelled'
            """ + (" AND date(vso.created_at) BETWEEN ? AND ?" if date_filter_active else "")
            sales_row = conn.execute(sale_sql, vehicle_date_params).fetchone()
        total_sales    = int(sales_row["total_sales"] or 0)
        total_revenue  = float(sales_row["total_revenue"] or 0)

        if rental_mode:
            # A rented vehicle is still an owned asset — it isn't "spent" the
            # way a sold vehicle's purchase price is, so rental profit is
            # simply the money collected from rentals (deposits/late fees
            # already flow into total_amount), not revenue minus the bike's
            # purchase cost.
            total_purchase = 0.0
            total_repair   = 0.0
            total_profit   = total_revenue
            active_rentals = int(q("""
                SELECT COUNT(*) AS c FROM vehicle_rental_orders WHERE LOWER(status)='active'
            """) or 0)
        else:
            total_purchase = float(sales_row["total_purchase"] or 0)
            total_repair   = float(sales_row["total_repair"] or 0)
            total_profit   = total_revenue - total_purchase - total_repair
            active_rentals = 0

        if rental_mode:
            today_sales = int(q("""
                SELECT COUNT(*) AS c FROM vehicle_rental_orders
                WHERE date(created_at)=?
            """, (today_iso,)) or 0)
        else:
            today_sales = int(q("""
                SELECT COUNT(*) AS c FROM vehicle_sale_orders vso
                LEFT JOIN orders o ON o.id=vso.order_id
                WHERE vso.order_id IS NOT NULL
                  AND LOWER(COALESCE(o.status,'in-progress'))<>'cancelled'
                  AND date(vso.created_at)=?
            """, (today_iso,)) or 0)

        # Recent vehicles (last 6, or every vehicle in the selected range)
        recent_vehicles = []
        try:
            rv_sql = "SELECT id, vehicle_name, vehicle_number, status, purchase_price, created_at FROM vehicles WHERE 1=1" + vdc
            rv_sql += " ORDER BY COALESCE(updated_at,created_at) DESC, id DESC"
            if not date_filter_active:
                rv_sql += " LIMIT 6"
            rows = conn.execute(rv_sql, vehicle_date_params).fetchall()
            recent_vehicles = [
                {
                    "id": r["id"],
                    "vehicle_name": r["vehicle_name"] or "-",
                    "vehicle_number": r["vehicle_number"] or "-",
                    "status": r["status"] or "Available",
                    "purchase_price": float(r["purchase_price"] or 0),
                }
                for r in rows
            ]
        except Exception:
            pass

        # Recent sales / rentals (last 6, or every sale in the selected range)
        recent_sales = []
        try:
            if rental_mode:
                rs_sql = """
                    SELECT vro.order_id, vro.vehicle_name, vro.vehicle_number,
                           COALESCE(vro.total_amount,0) AS sale_price,
                           COALESCE(vro.customer_name,'') AS customer_name,
                           vro.created_at
                    FROM vehicle_rental_orders vro
                    WHERE 1=1
                """ + (" AND date(vro.created_at) BETWEEN ? AND ?" if date_filter_active else "")
                rs_sql += " ORDER BY COALESCE(vro.updated_at,vro.created_at) DESC, vro.id DESC"
                if not date_filter_active:
                    rs_sql += " LIMIT 6"
                rows = conn.execute(rs_sql, vehicle_date_params).fetchall()
            else:
                rs_sql = """
                    SELECT vso.order_id, vso.vehicle_name, vso.vehicle_number,
                           COALESCE(vso.total_amount,0) AS sale_price,
                           COALESCE(c.name,'') AS customer_name,
                           vso.created_at
                    FROM vehicle_sale_orders vso
                    LEFT JOIN orders o ON o.id=vso.order_id
                    LEFT JOIN customers c ON c.id=o.customer_id
                    WHERE vso.order_id IS NOT NULL
                      AND LOWER(COALESCE(o.status,'in-progress'))<>'cancelled'
                """ + (" AND date(vso.created_at) BETWEEN ? AND ?" if date_filter_active else "")
                rs_sql += " ORDER BY COALESCE(vso.updated_at,vso.created_at) DESC, vso.id DESC"
                if not date_filter_active:
                    rs_sql += " LIMIT 6"
                rows = conn.execute(rs_sql, vehicle_date_params).fetchall()
            recent_sales = [
                {
                    "order_id": r["order_id"],
                    "vehicle_name": r["vehicle_name"] or "-",
                    "vehicle_number": r["vehicle_number"] or "-",
                    "customer_name": r["customer_name"] or "-",
                    "sale_price": float(r["sale_price"] or 0),
                    "created_at": str(r["created_at"] or ""),
                }
                for r in rows
            ]
        except Exception:
            pass

        # Recent expenses (last 6, or every expense in the selected range)
        recent_expenses = []
        try:
            re_sql = "SELECT id, expense_no, expense_name, amount, created_at FROM expenses WHERE 1=1" + edc
            re_sql += " ORDER BY created_at DESC, id DESC"
            if not date_filter_active:
                re_sql += " LIMIT 6"
            rows = conn.execute(re_sql, expenses_date_params).fetchall()
            recent_expenses = [
                {
                    "id": r["id"],
                    "expense_no": r["expense_no"] or "-",
                    "expense_name": r["expense_name"] or "-",
                    "amount": float(r["amount"] or 0),
                    "created_at": str(r["created_at"] or ""),
                }
                for r in rows
            ]
        except Exception:
            pass

        conn.close()
        print("Repair Cost =", repair_cost)

        return jsonify({
            "metrics": {
                "total_vehicles":  total_vehicles,
                "total_sales":     total_sales,
                "purchase":        purchase_total,
                "expenses":        expenses_total,
                "repair_cost":     repair_cost,
                "available":       available,
                "today_sales":     today_sales,
                "under_repair":    under_repair,
                "ready_to_sale":   ready_to_sale,
                "sold":            total_sales,
                "sold_count":      sold_count,
                "rented_count":    rented_count,
                "profit":          total_profit,
                "total_revenue":   total_revenue,
                "active_rentals":  active_rentals,
            },
            "recent_vehicles": recent_vehicles,
            "recent_sales":    recent_sales,
            "recent_expenses": recent_expenses,
        })
    except Exception as e:
        conn.close()
        return jsonify({"error": str(e)}), 500


import threading
import webbrowser
@app.before_request
def enforce_device_binding_on_api():
    """Re-validate device binding on every /api/* call (not just at login).

    If a user's device_id is later reset by an admin, or the token is used
    from a different device than it was issued for, the request is
    rejected immediately -- the client must re-login. This closes the gap
    where a stolen/shared JWT token would otherwise keep working on other
    devices until it expired.
    """
    if not is_device_binding_enforced():
        return None

    path = request.path or ""
    if not path.startswith("/api/"):
        return None
    if path in {"/api/login"} or request.method == "OPTIONS":
        return None

    try:
        verify_jwt_in_request(optional=True)
    except Exception:
        return None  # let @jwt_required() on the route itself handle it

    claims = get_jwt()
    if not claims:
        return None

    token_device_id = (claims.get("device_id") or "").strip()
    branch_code = claims.get("branch_code")
    user_id = get_jwt_identity()
    if not token_device_id or not user_id or not branch_code:
        return None

    branch = get_branch_record(branch_code)
    if not branch:
        return None

    conn = get_db_for_branch(branch["code"])
    try:
        user_row = conn.execute(
            "SELECT id, license_expiry_date FROM app_users WHERE id = ?", (user_id,)
        ).fetchone()
        is_bound = bool(user_row) and device_is_bound(conn, int(user_id), "mobile", token_device_id)
    finally:
        conn.close()

    if not user_row:
        return None

    expiry_ok, expiry_message = check_license_expiry(user_row)
    if not expiry_ok:
        return jsonify({
            "success": False,
            "code": "LICENSE_EXPIRED",
            "message": expiry_message,
        }), 403

    if not is_bound:
        return jsonify({
            "success": False,
            "code": "DEVICE_MISMATCH",
            "message": "This device is not licensed for this account. Please log in again or contact your administrator.",
        }), 403

    return None


@app.route("/api/admin/reset-device", methods=["POST"])
@jwt_required()
def api_admin_reset_device():
    """Unbind a user's device -- e.g. they got a new phone, or a factory
    reset changed their device id. Only admin/super_admin can do this."""
    claims = get_jwt()
    role = (claims.get("role") or "").strip().lower()
    if role not in {"admin", "super_admin"}:
        return jsonify({"success": False, "message": "Only admins can reset device bindings."}), 403

    data = request.get_json(force=True, silent=True) or {}
    target_username = (data.get("username") or "").strip()
    if not target_username:
        return jsonify({"success": False, "message": "username is required."}), 400

    # "mobile" clears the phone binding, "desktop" clears the PC/EXE
    # binding, anything else (or omitted) clears both.
    platform_choice = (data.get("platform") or "both").strip().lower()
    if platform_choice not in {"mobile", "desktop", "both"}:
        platform_choice = "both"

    branch_code = claims.get("branch_code")
    branch = get_branch_record(branch_code)
    if not branch:
        return jsonify({"success": False, "message": "Invalid branch."}), 400

    conn = get_db_for_branch(branch["code"])
    try:
        target = conn.execute(
            "SELECT id FROM app_users WHERE username = ?", (target_username,)
        ).fetchone()
        if not target:
            return jsonify({"success": False, "message": "User not found."}), 404

        if platform_choice in {"mobile", "both"}:
            conn.execute(
                "UPDATE app_users SET device_id = NULL, device_bound_at = NULL, device_platform = NULL WHERE id = ?",
                (target["id"],),
            )
            conn.execute(
                "DELETE FROM app_user_devices WHERE user_id = ? AND device_type = 'mobile'",
                (target["id"],),
            )
        if platform_choice in {"desktop", "both"}:
            conn.execute(
                "UPDATE app_users SET desktop_device_id = NULL, desktop_device_bound_at = NULL, desktop_device_platform = NULL WHERE id = ?",
                (target["id"],),
            )
            conn.execute(
                "DELETE FROM app_user_devices WHERE user_id = ? AND device_type = 'desktop'",
                (target["id"],),
            )
        conn.commit()
    finally:
        conn.close()

    label = {"mobile": "mobile", "desktop": "desktop", "both": "mobile + desktop"}[platform_choice]
    return jsonify({"success": True, "message": f"{label} device binding reset for '{target_username}'. They can log in from a new device now."})


@app.route("/api/admin/set-license-expiry", methods=["POST"])
@jwt_required()
def api_admin_set_license_expiry():
    """Set, extend, or remove a client user's license expiry date.

    Body: {
      "username": "client_ramesh",
      "expiry_date": "2027-01-31"   // YYYY-MM-DD, omit/null to remove expiry (unlimited)
    }
    """
    claims = get_jwt()
    role = (claims.get("role") or "").strip().lower()
    if role not in {"admin", "super_admin"}:
        return jsonify({"success": False, "message": "Only admins can set license expiry."}), 403

    data = request.get_json(force=True, silent=True) or {}
    target_username = (data.get("username") or "").strip()
    expiry_date_raw = (data.get("expiry_date") or "").strip()
    if not target_username:
        return jsonify({"success": False, "message": "username is required."}), 400

    expiry_dt = None
    if expiry_date_raw:
        try:
            expiry_dt = datetime.fromisoformat(expiry_date_raw)
        except ValueError:
            return jsonify({"success": False, "message": "expiry_date must be in YYYY-MM-DD format."}), 400

    branch_code = claims.get("branch_code")
    branch = get_branch_record(branch_code)
    if not branch:
        return jsonify({"success": False, "message": "Invalid branch."}), 400

    conn = get_db_for_branch(branch["code"])
    try:
        target = conn.execute(
            "SELECT id FROM app_users WHERE username = ?", (target_username,)
        ).fetchone()
        if not target:
            return jsonify({"success": False, "message": "User not found."}), 404

        conn.execute(
            "UPDATE app_users SET license_expiry_date = ? WHERE id = ?",
            (expiry_dt, target["id"]),
        )
        conn.commit()
    finally:
        conn.close()

    if expiry_dt:
        return jsonify({"success": True, "message": f"License for '{target_username}' set to expire on {expiry_dt.strftime('%d %b %Y')}."})
    return jsonify({"success": True, "message": f"License expiry removed for '{target_username}' (now unlimited)."})


@app.route("/api/branches", methods=["GET"])
def api_list_branches():
    """Public (pre-login) list of branches/companies the mobile app can log
    into. Each branch is a separate database (see branch_catalog / build_
    branch_database_name), so this mirrors exactly what's configured under
    Settings > Company Settings on the web, instead of a hardcoded list."""
    branches = list_branches()
    return jsonify({
        "success": True,
        "branches": [
            {
                "code": b["code"],
                "name": b.get("name") or prettify_branch_name(b["code"]),
                "is_default": bool(b.get("is_default")),
            }
            for b in branches
        ],
    })


@app.route("/api/login", methods=["POST"])
def api_login():
    data = request.get_json()

    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    branch_code = normalize_branch_code(data.get("branch_code"))

    selected_branch = get_branch_record(branch_code)

    if not selected_branch:
        return jsonify({
            "success": False,
            "message": "Invalid branch."
        }), 400

    conn = get_db_for_branch(selected_branch["code"])
    ensure_default_role_records(conn)

    user_row = conn.execute(
        """
        SELECT TOP 1 *
        FROM app_users
        WHERE username = ?
          AND (
                LOWER(COALESCE(role,''))='super_admin'
                OR COALESCE(branch_code, ?) = ?
              )
        ORDER BY
            CASE
                WHEN LOWER(COALESCE(role,''))='super_admin'
                THEN 0
                ELSE 1
            END,
            id ASC
        """,
        (
            username,
            selected_branch["code"],
            selected_branch["code"],
        ),
    ).fetchone()

    if not user_row:
        conn.close()
        return jsonify({
            "success": False,
            "message": "Invalid username."
        }), 401

    if not verify_user_password(user_row["password_hash"], password):
        conn.close()
        return jsonify({
            "success": False,
            "message": "Invalid password."
        }), 401

    expiry_ok, expiry_message = check_license_expiry(user_row)
    if not expiry_ok:
        conn.close()
        return jsonify({
            "success": False,
            "code": "LICENSE_EXPIRED",
            "message": expiry_message,
        }), 403

    device_id = (data.get("device_id") or "").strip()
    device_platform = (data.get("device_platform") or "").strip() or None
    is_admin_web_tool = (
        device_platform == "admin_web_tool"
        and normalize_user_role(user_row["role"]) in {ROLE_ADMIN, ROLE_SUPER_ADMIN}
    )
    if not is_admin_web_tool:
        device_ok, device_message = bind_or_check_device(
            conn,
            user_row,
            device_id,
            device_platform,
            device_type="mobile",
            branch_code=selected_branch["code"],
        )
        if not device_ok:
            conn.close()
            return jsonify({
                "success": False,
                "code": "DEVICE_MISMATCH",
                "message": device_message,
            }), 403

    conn.close()

    identity = {
    "id": user_row["id"],
    "username": user_row["username"],
    "role": user_row["role"],
    "branch_code": selected_branch["code"]
}
    # flask-jwt-extended requires the "sub" claim (identity) to be a plain
    # string. Passing a dict here used to encode fine but fails to DECODE
    # on every subsequent request (422 Unprocessable Entity). Use the user
    # id as the identity, and carry the rest as additional claims.
    token = create_access_token(
        identity=str(user_row["id"]),
        additional_claims={
            "username": user_row["username"],
            "role": user_row["role"],
            "branch_code": selected_branch["code"],
            "device_id": "" if is_admin_web_tool else device_id,
        },
    )

    # No JWT exists yet at this point in the request (we just created it
    # above), so branch-scoped settings like business_mode would otherwise
    # fall back to the default branch. Pin it explicitly to the branch the
    # user just logged into — same pattern the web /login route uses.
    g.current_branch = selected_branch

    return jsonify({
    "success": True,
    "message": "Login successful",
    "access_token": token,
    "user": identity,
    "business_mode": get_business_mode(),
    "branding": get_branding_info(),
})

