@jwt_required()
def api_set_business_mode():
    claims = get_jwt()
    role = (claims.get("role") or "").strip().lower()
    if role not in {"admin", "super_admin"}:
        return jsonify({"success": False, "message": "Only admins can change the business mode."}), 403

    data = request.get_json(force=True, silent=True) or {}
    mode = (data.get("business_mode") or "").strip().lower()
    if mode not in {"sale", "rental"}:
        return jsonify({"success": False, "message": "business_mode must be 'sale' or 'rental'."}), 400

    set_setting("business_mode", mode)
    return jsonify({"success": True, "business_mode": mode})

